/// Selectivity for `aeroftp-cli keystore export`.
///
/// `full` (default) packages every vault entry plus the SQLite
/// databases under `~/.config/com.aeroftp.AeroFTP/`, the user's
/// installed plugins, rollback snapshots, and the GUI's whitelisted
/// localStorage keys. `vault-only` writes the slim pre-v3.7.8 shape:
/// vault entries only, no filesystem or UI state. The on-disk
/// envelope is the same v2 format in both cases.
#[derive(Copy, Clone, Debug, ValueEnum)]
enum KeystoreExportModeArg {
    /// Full snapshot (vault + SQLite DBs + plugins + sync snapshots + UI prefs)
    Full,
    /// Slim export, vault entries only, no filesystem state
    #[clap(name = "vault-only")]
    VaultOnly,
}

impl KeystoreExportModeArg {
    fn into_inner(self) -> ftp_client_gui_lib::keystore_export::ExportMode {
        match self {
            Self::Full => ftp_client_gui_lib::keystore_export::ExportMode::Full,
            Self::VaultOnly => ftp_client_gui_lib::keystore_export::ExportMode::VaultOnly,
        }
    }
}

/// Conflict resolution for `aeroftp-cli keystore import`.
///
/// `skip` (default) leaves existing vault entries alone -- the safer
/// option for "rehydrate a new machine". `overwrite` replaces every
/// existing entry with the backup's value, suitable for "restore my
/// vault after I accidentally cleared it".
#[derive(Copy, Clone, Debug, ValueEnum)]
enum KeystoreMergeArg {
    Skip,
    Overwrite,
}

impl KeystoreMergeArg {
    fn as_str(self) -> &'static str {
        match self {
            Self::Skip => "skip",
            Self::Overwrite => "overwrite",
        }
    }
}

#[derive(Subcommand)]
enum KeystoreCommands {
    /// Export an encrypted `.aeroftp-keystore` backup file.
    ///
    /// Password resolution order (first match wins):
    ///   1. AEROFTP_KEYSTORE_PASSWORD environment variable
    ///   2. `--password-stdin` (reads one line from stdin)
    ///   3. `--password <pw>` (visible in process list, prints a warning)
    ///   4. interactive prompt on stderr (when stdin is a TTY)
    ///
    /// Minimum password length is 8 characters; backend enforces.
    Export {
        /// Output `.aeroftp-keystore` path
        #[arg(long, short = 'o')]
        output: String,
        /// Export mode
        #[arg(long, value_enum, default_value_t = KeystoreExportModeArg::Full)]
        mode: KeystoreExportModeArg,
        /// Encryption password (visible in `ps`; prefer --password-stdin or env)
        #[arg(long)]
        password: Option<String>,
        /// Read one password line from stdin
        #[arg(long = "password-stdin")]
        password_stdin: bool,
        /// Override the source config directory (where SQLite DBs and
        /// plugins live). Defaults to the same directory the GUI uses.
        #[arg(long = "config-dir")]
        config_dir: Option<String>,
        /// Output a JSON summary on stdout (metadata + size + zstd
        /// ratio); errors go to stderr in any mode.
        #[arg(long)]
        json: bool,
    },
    /// Import an encrypted `.aeroftp-keystore` backup file into the
    /// current installation. Sections that have been opted out via
    /// `--skip-*` are left untouched on disk. After a successful
    /// import that touched SQLite or files the CLI prints a
    /// `requires_restart=true` line and exits 0; the AeroFTP GUI
    /// must be restarted before exercising the restored DBs.
    Import {
        /// Backup `.aeroftp-keystore` path
        #[arg(long, short = 'i')]
        input: String,
        /// Decryption password (same resolution order as `export`)
        #[arg(long)]
        password: Option<String>,
        #[arg(long = "password-stdin")]
        password_stdin: bool,
        /// Merge strategy for vault entries that already exist
        #[arg(long, value_enum, default_value_t = KeystoreMergeArg::Skip)]
        merge: KeystoreMergeArg,
        /// Skip the vault entries section
        #[arg(long = "skip-vault")]
        skip_vault: bool,
        /// Skip the SQLite databases section
        #[arg(long = "skip-sqlite")]
        skip_sqlite: bool,
        /// Skip the file trees section (plugins, sync_snapshots)
        #[arg(long = "skip-files")]
        skip_files: bool,
        /// Skip the localStorage UI-preferences section
        #[arg(long = "skip-local-storage")]
        skip_local_storage: bool,
        /// Override the destination config directory
        #[arg(long = "config-dir")]
        config_dir: Option<String>,
        /// Output a JSON import-result summary on stdout
        #[arg(long)]
        json: bool,
    },
    /// Inspect the cleartext envelope metadata of a backup file
    /// WITHOUT decrypting the payload. Useful for "what's in this
    /// file?" before typing the password.
    ///
    /// NB: the cleartext metadata cannot be cryptographically trusted
    /// before decryption. A genuine import double-checks the
    /// authenticated copy embedded in the encrypted payload.
    Info {
        /// Backup `.aeroftp-keystore` path
        #[arg(long, short = 'i')]
        input: String,
        /// Output a JSON summary on stdout
        #[arg(long)]
        json: bool,
    },
    /// Health check of the credential vault: reports the key mode and whether
    /// the vault can be opened right now. Detects a lost or overwritten keyring
    /// entry (zero-password vault that no longer unlocks). Read-only; exits 0
    /// when healthy, 1 when the vault cannot be opened.
    Status {
        /// Output a JSON summary on stdout
        #[arg(long)]
        json: bool,
    },
    /// Recover a credential vault that can no longer be unlocked (e.g. its
    /// system-keyring entry was lost or overwritten). Snapshots and resets
    /// `vault.db` + `vault.key`, re-initialises a fresh vault, then imports the
    /// given `.aeroftp-keystore` backup. The pre-reset state is preserved in a
    /// timestamped snapshot under the config directory (reversible).
    Repair {
        /// Backup `.aeroftp-keystore` to restore from
        #[arg(long, short = 'i')]
        input: String,
        /// Decryption password (same resolution order as `import`)
        #[arg(long)]
        password: Option<String>,
        #[arg(long = "password-stdin")]
        password_stdin: bool,
        /// Override the destination config directory
        #[arg(long = "config-dir")]
        config_dir: Option<String>,
        /// Skip the destructive-action confirmation prompt
        #[arg(long, short = 'y')]
        yes: bool,
        /// Output a JSON summary on stdout
        #[arg(long)]
        json: bool,
    },
}

#[derive(Subcommand)]
enum AerorsyncCommands {
    /// Get or set the AeroRsync mode (auto / classic / native)
    ///
    /// The mode is persisted in the same TOML file the GUI uses
    /// (`Settings > Native Rsync`), so changes survive across CLI
    /// invocations and are picked up by the GUI on its next launch.
    Mode {
        #[command(subcommand)]
        command: AerorsyncModeCommands,
    },
    /// Live probe of the russh password transport against an SSH endpoint
    ///
    /// Opens a russh session with `userauth password`, runs `rsync
    /// --version` over a channel exec, and reports the remote banner.
    /// This is the minimal end-to-end smoke for the password transport
    /// without requiring a full provider integration. Useful to verify
    /// that an rsync-over-SSH endpoint (Hetzner Storage Box or any
    /// password-auth SSH+rsync host) accepts a password login from
    /// AeroFTP before committing to a profile.
    ///
    /// Two invocation modes:
    ///
    /// 1. **Explicit args**: `aerorsync probe host.example.com user
    ///    --port 2222 --password-env SSH_PW --accept-any-host-key`.
    ///    Pass HOST and USER positionally; resolve the password from
    ///    --password-env, --password-stdin, or a TTY prompt.
    ///
    /// 2. **Profile-backed**: `aerorsync probe --profile-rsync "My SSH
    ///    Server"` reads host / port / user from the saved profile and
    ///    pulls the password from the matching vault credential
    ///    (`server_<id>`). HOST and USER positionals are then optional
    ///    overrides; --port overrides the profile's port. If a vault
    ///    credential is missing the command falls back to the prompt /
    ///    --password-* sources.
    ///
    /// The password is NEVER echoed, NEVER logged, NEVER printed in
    /// error messages. The remote banner IS printed on success: it is
    /// public information from the server.
    Probe {
        /// Remote host (e.g. `host.example.com`, `127.0.0.1`).
        /// Optional when `--profile-rsync` is set; the profile's host is used.
        host: Option<String>,
        /// SSH user.
        /// Optional when `--profile-rsync` is set; the profile's username is used.
        user: Option<String>,
        /// SSH port (default 22; overridden by `--profile-rsync` when set).
        #[arg(long, default_value_t = 22)]
        port: u16,
        /// Read the password from the named environment variable
        #[arg(long, value_name = "ENV_VAR")]
        password_env: Option<String>,
        /// Read one password line from stdin
        #[arg(long = "password-stdin")]
        password_stdin: bool,
        /// Use a saved server profile to resolve host / port / user /
        /// password. The credential is looked up in vault key
        /// `server_<id>` exactly like the rest of the CLI. Use a
        /// distinct flag name (`--profile-rsync`) to avoid clashing
        /// with the global `--profile / -P` flag that the entire CLI
        /// surface forwards through `clap`.
        #[arg(long, value_name = "PROFILE")]
        profile_rsync: Option<String>,
        /// Skip TOFU host-key verification (dev/CI only). Production
        /// pinning lives in the provider; the probe is a smoke test
        /// and lets the operator inspect the fingerprint manually.
        #[arg(long)]
        accept_any_host_key: bool,
        /// Override the remote command to exec instead of `rsync --version`
        #[arg(long, default_value = "rsync --version")]
        remote_command: String,
        /// Connect timeout in seconds (default 10)
        #[arg(long, default_value_t = 10)]
        connect_timeout_secs: u64,
    },
}

#[derive(Subcommand)]
enum AerorsyncModeCommands {
    /// Print the current mode (auto / classic / native)
    Get,
    /// Set the mode. Accepts: auto, classic, native
    Set {
        /// New mode value (case-insensitive)
        mode: String,
    },
}

