async fn cmd_cp(url: &str, from: &str, to: &str, cli: &Cli, format: OutputFormat) -> i32 {
    let (mut provider, initial_path) = match create_and_connect(url, cli, format).await {
        Ok(v) => v,
        Err(code) => return code,
    };

    let from = &resolve_cli_remote_path(&initial_path, from);
    let to = &resolve_cli_remote_path(&initial_path, to);
    if let Some(code) = reject_restricted_target(provider.as_mut(), to, "cp", format).await {
        return code;
    }

    // Goes through `server_side_copy_with_fallback` so the CLI exits 0
    // even when the provider does not advertise server-side copy or
    // rejects this specific operation (S3 cross-bucket without IAM,
    // WebDAV 501, Nextcloud cross-share). Hard errors (auth, source not
    // found, quota) still surface with their original exit code.
    match ftp_client_gui_lib::copy_fallback::server_side_copy_with_fallback(
        provider.as_mut(),
        from,
        to,
    )
    .await
    {
        Ok(outcome) => {
            let suffix = match outcome {
                ftp_client_gui_lib::copy_fallback::CopyOutcome::ServerSide => "",
                ftp_client_gui_lib::copy_fallback::CopyOutcome::Fallback { .. } => {
                    " (fallback: download→upload)"
                }
            };
            match format {
                OutputFormat::Text => {
                    if !cli.quiet {
                        eprintln!("{} ⇒ {}{}", from, to, suffix);
                    }
                }
                OutputFormat::Json => print_json(&CliOk {
                    status: "ok",
                    message: format!("{} ⇒ {}{}", from, to, suffix),
                }),
            }
            let _ = provider.disconnect().await;
            0
        }
        Err(e) => {
            print_error(
                format,
                &format!("cp failed: {}", e),
                provider_error_to_exit_code(&e),
            );
            let _ = provider.disconnect().await;
            provider_error_to_exit_code(&e)
        }
    }
}

/// Parse a human-friendly duration string into seconds.
/// Accepts: "1h", "24h", "7d", "30d", or raw seconds like "3600".
fn parse_expires(s: &str) -> Option<u64> {
    let s = s.trim();
    if let Some(h) = s.strip_suffix('h') {
        h.parse::<u64>().ok().map(|v| v * 3600)
    } else if let Some(d) = s.strip_suffix('d') {
        d.parse::<u64>().ok().map(|v| v * 86400)
    } else {
        s.parse::<u64>().ok()
    }
}

#[allow(clippy::too_many_arguments)]
async fn cmd_link(
    url: &str,
    path: &str,
    expires: Option<&str>,
    password: Option<&str>,
    permissions: &str,
    verify: bool,
    cli: &Cli,
    format: OutputFormat,
) -> i32 {
    let (mut provider, initial_path) = match create_and_connect(url, cli, format).await {
        Ok(v) => v,
        Err(code) => return code,
    };

    let path = &resolve_cli_remote_path(&initial_path, path);
    if !provider.supports_share_links() {
        print_error(format, "Share links are not supported by this provider", 7);
        let _ = provider.disconnect().await;
        return 7;
    }

    let expires_in_secs = expires.and_then(parse_expires);
    if expires.is_some() && expires_in_secs.is_none() {
        print_error(
            format,
            "Invalid --expires format. Use: 1h, 24h, 7d, 30d, or seconds",
            1,
        );
        let _ = provider.disconnect().await;
        return 1;
    }

    let options = ShareLinkOptions {
        expires_in_secs,
        password: password.map(|s| s.to_string()),
        permissions: if permissions == "view" {
            None
        } else {
            Some(permissions.to_string())
        },
    };

    match provider.create_share_link(path, options).await {
        Ok(result) => {
            // Optional reachability probe so callers (and CI smoke tests) can
            // detect silent regressions where we build a URL that does not
            // actually resolve (e.g. wrong public handle, stale signature).
            // We use GET, not HEAD: SigV4 presigned URLs are signed for a
            // specific method and HEAD typically returns 403 against them.
            let probe_status = if verify {
                match probe_share_link(&result.url).await {
                    Ok(code) => Some(code),
                    Err(e) => {
                        print_error(format, &format!("link verify failed: {}", e), 4);
                        let _ = provider.disconnect().await;
                        return 4;
                    }
                }
            } else {
                None
            };
            if verify {
                if let Some(code) = probe_status {
                    if !(200..400).contains(&code) {
                        print_error(
                            format,
                            &format!("link verify failed: HTTP {} from generated URL", code),
                            4,
                        );
                        let _ = provider.disconnect().await;
                        return 4;
                    }
                }
            }
            match format {
                OutputFormat::Text => {
                    println!("{}", result.url);
                    if let Some(ref pw) = result.password {
                        eprintln!("Password: {}", pw);
                    }
                    if let Some(ref exp) = result.expires_at {
                        eprintln!("Expires: {}", exp);
                    }
                    if let Some(code) = probe_status {
                        eprintln!("Verified: HTTP {}", code);
                    }
                }
                OutputFormat::Json => {
                    let mut payload = serde_json::json!({
                        "status": "ok",
                        "path": path,
                        "url": result.url,
                        "password": result.password,
                        "expires_at": result.expires_at,
                    });
                    if let Some(code) = probe_status {
                        payload["verified"] = serde_json::json!({
                            "http_status": code,
                            "ok": (200..400).contains(&code),
                        });
                    }
                    print_json(&payload);
                }
            }
            let _ = provider.disconnect().await;
            0
        }
        Err(e) => {
            print_error(
                format,
                &format!("link failed: {}", e),
                provider_error_to_exit_code(&e),
            );
            let _ = provider.disconnect().await;
            provider_error_to_exit_code(&e)
        }
    }
}

/// Probe a generated share-link URL with an HTTP GET (no body download) and
/// return the resulting status code. We use GET because SigV4 presigned URLs
/// reject HEAD when only `host` is in `SignedHeaders`. We follow up to 5
/// redirects and use a short timeout so CI does not hang on a misconfigured
/// provider.
async fn probe_share_link(url: &str) -> Result<u16, String> {
    let client = reqwest::Client::builder()
        .redirect(reqwest::redirect::Policy::limited(5))
        .timeout(std::time::Duration::from_secs(15))
        .build()
        .map_err(|e| format!("HTTP client init failed: {}", e))?;

    let resp = client
        .get(url)
        .send()
        .await
        .map_err(|e| format!("GET {}: {}", url, e))?;

    Ok(resp.status().as_u16())
}

async fn cmd_edit(
    url: &str,
    path: &str,
    find: &str,
    replace: &str,
    replace_all: bool,
    cli: &Cli,
    format: OutputFormat,
) -> i32 {
    if path.is_empty() {
        print_error(format, "edit requires a remote path", 5);
        return 5;
    }
    if find.is_empty() {
        print_error(format, "edit requires a non-empty find string", 5);
        return 5;
    }

    let (mut provider, initial_path) = match create_and_connect(url, cli, format).await {
        Ok(v) => v,
        Err(code) => return code,
    };

    let path = &resolve_cli_remote_path(&initial_path, path);
    let data = match provider.download_to_bytes(path).await {
        Ok(data) => data,
        Err(e) => {
            print_error(
                format,
                &format!("edit failed: {}", e),
                provider_error_to_exit_code(&e),
            );
            let _ = provider.disconnect().await;
            return provider_error_to_exit_code(&e);
        }
    };

    let mut content = match String::from_utf8(data) {
        Ok(content) => content,
        Err(_) => {
            print_error(format, "edit supports only UTF-8 text files", 5);
            let _ = provider.disconnect().await;
            return 5;
        }
    };
    content = content
        .strip_prefix('\u{FEFF}')
        .unwrap_or(&content)
        .to_string();

    let occurrences = content.matches(find).count();
    if occurrences == 0 {
        match format {
            OutputFormat::Text => {
                if !cli.quiet {
                    eprintln!("No matches found in {}", path);
                }
            }
            OutputFormat::Json => {
                print_json(&serde_json::json!({
                    "status": "ok",
                    "path": path,
                    "occurrences": 0,
                    "replaced": 0,
                    "message": "No matches found",
                }));
            }
        }
        let _ = provider.disconnect().await;
        return 0;
    }

    let new_content = if replace_all {
        content.replace(find, replace)
    } else {
        content.replacen(find, replace, 1)
    };
    let replaced = if replace_all { occurrences } else { 1 };

    let mut temp_file = match NamedTempFile::new() {
        Ok(file) => file,
        Err(e) => {
            print_error(
                format,
                &format!("edit failed: cannot create temp file: {}", e),
                99,
            );
            let _ = provider.disconnect().await;
            return 99;
        }
    };

    if let Err(e) = temp_file.write_all(new_content.as_bytes()) {
        print_error(
            format,
            &format!("edit failed: cannot write temp file: {}", e),
            99,
        );
        let _ = provider.disconnect().await;
        return 99;
    }

    let temp_path = temp_file.path().to_string_lossy().to_string();
    match provider.upload(&temp_path, path, None).await {
        Ok(()) => {
            match format {
                OutputFormat::Text => {
                    if !cli.quiet {
                        eprintln!("Replaced {} occurrence(s) in {}", replaced, path);
                    }
                }
                OutputFormat::Json => {
                    print_json(&serde_json::json!({
                        "status": "ok",
                        "path": path,
                        "occurrences": occurrences,
                        "replaced": replaced,
                        "message": format!("Replaced {} occurrence(s) in {}", replaced, path),
                    }));
                }
            }
            let _ = provider.disconnect().await;
            0
        }
        Err(e) => {
            print_error(
                format,
                &format!("edit failed: {}", e),
                provider_error_to_exit_code(&e),
            );
            let _ = provider.disconnect().await;
            provider_error_to_exit_code(&e)
        }
    }
}

/// Shared "provider has no versioning" path for the three `versions`
/// subcommands: print the error once and return the NotSupported exit code
/// (computed a single time, not rebuilt per call site).
fn versions_unsupported(format: OutputFormat) -> i32 {
    let code = provider_error_to_exit_code(&ProviderError::NotSupported("versions".to_string()));
    print_error(
        format,
        "This provider does not expose file versioning",
        code,
    );
    code
}

/// Render a file's version list (newest first) as text or JSON.
fn print_versions(versions: &[FileVersion], path: &str, format: OutputFormat) {
    match format {
        OutputFormat::Json => {
            #[derive(Serialize)]
            struct VersionsResult<'a> {
                status: &'static str,
                path: &'a str,
                count: usize,
                versions: &'a [FileVersion],
            }
            print_json(&VersionsResult {
                status: "ok",
                path,
                count: versions.len(),
                versions,
            });
        }
        OutputFormat::Text => {
            if versions.is_empty() {
                println!("No previous versions for {}", path);
                return;
            }
            println!("{} version(s) of {} (newest first):", versions.len(), path);
            for (i, v) in versions.iter().enumerate() {
                let modified = v.modified.as_deref().unwrap_or("-");
                let by = v
                    .modified_by
                    .as_deref()
                    .map(|m| format!("  by {}", m))
                    .unwrap_or_default();
                println!(
                    "  {:>3}. {}  {:>10}  {}{}",
                    i + 1,
                    v.id,
                    format_size(v.size),
                    modified,
                    by
                );
            }
        }
    }
}

/// `versions list`: list previous versions of a remote file.
async fn cmd_versions_list(url: &str, path: &str, cli: &Cli, format: OutputFormat) -> i32 {
    if path.trim().is_empty() {
        print_error(format, "Missing remote file path for 'versions list'", 5);
        return 5;
    }
    let (mut provider, initial_path) = match create_and_connect(url, cli, format).await {
        Ok(v) => v,
        Err(code) => return code,
    };
    if !provider.supports_versions() {
        let _ = provider.disconnect().await;
        return versions_unsupported(format);
    }
    let path = resolve_cli_remote_path(&initial_path, path);
    let code = match provider.list_versions(&path).await {
        Ok(versions) => {
            print_versions(&versions, &path, format);
            0
        }
        Err(e) => {
            print_error(
                format,
                &format!("versions list failed: {}", e),
                provider_error_to_exit_code(&e),
            );
            provider_error_to_exit_code(&e)
        }
    };
    let _ = provider.disconnect().await;
    code
}

/// `versions get`: download a specific previous version to a local path.
async fn cmd_versions_get(
    url: &str,
    path: &str,
    version_id: &str,
    local: &str,
    cli: &Cli,
    format: OutputFormat,
) -> i32 {
    if path.trim().is_empty() {
        print_error(format, "Missing remote file path for 'versions get'", 5);
        return 5;
    }
    if version_id.trim().is_empty() {
        print_error(
            format,
            "Missing version id for 'versions get' (run 'versions list' first)",
            5,
        );
        return 5;
    }
    if local.trim().is_empty() {
        print_error(
            format,
            "Missing local destination path for 'versions get'",
            5,
        );
        return 5;
    }
    let (mut provider, initial_path) = match create_and_connect(url, cli, format).await {
        Ok(v) => v,
        Err(code) => return code,
    };
    if !provider.supports_versions() {
        let _ = provider.disconnect().await;
        return versions_unsupported(format);
    }
    let rpath = resolve_cli_remote_path(&initial_path, path);
    // Mirror `get`: when the local destination is a directory (trailing slash
    // or an existing dir), write into it under the remote file's basename
    // instead of trying to create a file at the directory path (which fails).
    let local_owned;
    let local_dest = if local.ends_with('/') || std::path::Path::new(local).is_dir() {
        let filename = rpath.rsplit('/').next().unwrap_or("download");
        local_owned = format!(
            "{}{}{}",
            local,
            if local.ends_with('/') { "" } else { "/" },
            filename
        );
        local_owned.as_str()
    } else {
        local
    };
    let code = match provider
        .download_version(&rpath, version_id, local_dest)
        .await
    {
        Ok(()) => {
            let msg = format!(
                "Downloaded version {} of {} to {}",
                version_id, rpath, local_dest
            );
            match format {
                OutputFormat::Json => print_json(&CliOk {
                    status: "ok",
                    message: msg,
                }),
                OutputFormat::Text => println!("{}", msg),
            }
            0
        }
        Err(e) => {
            print_error(
                format,
                &format!("versions get failed: {}", e),
                provider_error_to_exit_code(&e),
            );
            provider_error_to_exit_code(&e)
        }
    };
    let _ = provider.disconnect().await;
    code
}

