/// `versions purge`: permanently delete one version or delete marker of a file.
/// Irreversible; prompts for confirmation on a TTY unless `--yes` is given.
async fn cmd_versions_purge(
    url: &str,
    path: &str,
    version_id: &str,
    yes: bool,
    cli: &Cli,
    format: OutputFormat,
) -> i32 {
    if path.trim().is_empty() {
        print_error(format, "Missing remote file path for 'versions purge'", 5);
        return 5;
    }
    if version_id.trim().is_empty() {
        print_error(
            format,
            "Missing version id for 'versions purge' (run 'versions list' first)",
            5,
        );
        return 5;
    }
    // Confirm the irreversible purge before connecting.
    use std::io::IsTerminal;
    if !yes && std::io::stdin().is_terminal() {
        eprintln!(
            "Permanently delete version '{}' of '{}'? This cannot be undone. [y/N]",
            version_id, path
        );
        let mut buf = String::new();
        if std::io::stdin().read_line(&mut buf).is_err() {
            print_error(format, "Aborted (stdin error).", 5);
            return 5;
        }
        let ans = buf.trim().to_lowercase();
        if ans != "y" && ans != "yes" {
            print_error(format, "Aborted by user.", 0);
            return 0;
        }
    }
    let (mut provider, initial_path) = match create_and_connect(url, cli, format).await {
        Ok(v) => v,
        Err(code) => return code,
    };
    if !provider.supports_versions() {
        let _ = provider.disconnect().await;
        return versions_unsupported(format);
    }
    let rpath = resolve_cli_remote_path(&initial_path, path);
    let code = match provider.delete_version(&rpath, version_id).await {
        Ok(()) => {
            let msg = format!("Purged version {} of {}", version_id, rpath);
            match format {
                OutputFormat::Json => print_json(&CliOk {
                    status: "ok",
                    message: msg,
                }),
                OutputFormat::Text => println!("{}", msg),
            }
            0
        }
        Err(e) => {
            print_error(
                format,
                &format!("versions purge failed: {}", e),
                provider_error_to_exit_code(&e),
            );
            provider_error_to_exit_code(&e)
        }
    };
    let _ = provider.disconnect().await;
    code
}

/// Render an S3 trash listing (versions + delete markers) as text or JSON.
fn print_trash(entries: &[TrashEntry], prefix: &str, format: OutputFormat) {
    match format {
        OutputFormat::Json => {
            #[derive(Serialize)]
            struct TrashResult<'a> {
                status: &'static str,
                prefix: &'a str,
                count: usize,
                entries: &'a [TrashEntry],
            }
            print_json(&TrashResult {
                status: "ok",
                prefix,
                count: entries.len(),
                entries,
            });
        }
        OutputFormat::Text => {
            if entries.is_empty() {
                println!("Trash is empty under '{}'", prefix);
                return;
            }
            println!(
                "{} trash entr{} under '{}':",
                entries.len(),
                if entries.len() == 1 { "y" } else { "ies" },
                prefix
            );
            for e in entries {
                let kind = if e.is_delete_marker {
                    "delete-marker"
                } else {
                    "version"
                };
                let latest = if e.is_latest { " (latest)" } else { "" };
                let modified = e.last_modified.as_deref().unwrap_or("-");
                println!(
                    "  {} [{}]{} {}  {}  vid={}",
                    e.display_key,
                    kind,
                    latest,
                    format_size(e.size),
                    modified,
                    e.version_id
                );
            }
        }
    }
}

/// `versions trash`: list soft-deleted objects and delete markers under a prefix.
async fn cmd_versions_trash(
    url: &str,
    prefix: &str,
    all: bool,
    cli: &Cli,
    format: OutputFormat,
) -> i32 {
    let (mut provider, _initial_path) = match create_and_connect(url, cli, format).await {
        Ok(v) => v,
        Err(code) => return code,
    };
    let rprefix = prefix.trim().to_string();
    let code = match provider.list_object_versions(&rprefix, all).await {
        Ok(entries) => {
            print_trash(&entries, &rprefix, format);
            0
        }
        Err(e) => {
            print_error(
                format,
                &format!("versions trash failed: {}", e),
                provider_error_to_exit_code(&e),
            );
            provider_error_to_exit_code(&e)
        }
    };
    let _ = provider.disconnect().await;
    code
}

/// `versions empty-trash`: purge every trashed version and delete marker under a
/// prefix. Irreversible; `--dry-run` previews the count and bytes, and without
/// `--yes` a real sweep prompts for confirmation on a TTY.
async fn cmd_versions_empty_trash(
    url: &str,
    prefix: &str,
    all: bool,
    dry_run: bool,
    yes: bool,
    cli: &Cli,
    format: OutputFormat,
) -> i32 {
    let rprefix = prefix.trim().to_string();
    // Confirm the irreversible sweep before connecting (dry runs never prompt).
    if !dry_run {
        use std::io::IsTerminal;
        if !yes && std::io::stdin().is_terminal() {
            let scope = if rprefix.is_empty() {
                "the entire bucket".to_string()
            } else {
                format!("prefix '{}'", rprefix)
            };
            eprintln!(
                "Permanently purge ALL trashed versions under {}? This cannot be undone. [y/N]",
                scope
            );
            let mut buf = String::new();
            if std::io::stdin().read_line(&mut buf).is_err() {
                print_error(format, "Aborted (stdin error).", 5);
                return 5;
            }
            let ans = buf.trim().to_lowercase();
            if ans != "y" && ans != "yes" {
                print_error(format, "Aborted by user.", 0);
                return 0;
            }
        }
    }
    let (mut provider, _initial_path) = match create_and_connect(url, cli, format).await {
        Ok(v) => v,
        Err(code) => return code,
    };
    let code = match provider.empty_object_versions(&rprefix, all, dry_run).await {
        Ok((count, bytes)) => {
            #[derive(Serialize)]
            struct EmptyTrashResult<'a> {
                status: &'static str,
                dry_run: bool,
                prefix: &'a str,
                count: u64,
                bytes: u64,
            }
            match format {
                OutputFormat::Json => print_json(&EmptyTrashResult {
                    status: "ok",
                    dry_run,
                    prefix: &rprefix,
                    count,
                    bytes,
                }),
                OutputFormat::Text => {
                    if dry_run {
                        println!(
                            "Dry run: {} trashed object(s) ({}) would be purged under '{}'",
                            count,
                            format_size(bytes),
                            rprefix
                        );
                    } else {
                        println!(
                            "Purged {} trashed object(s) ({}) under '{}'",
                            count,
                            format_size(bytes),
                            rprefix
                        );
                    }
                }
            }
            0
        }
        Err(e) => {
            print_error(
                format,
                &format!("versions empty-trash failed: {}", e),
                provider_error_to_exit_code(&e),
            );
            provider_error_to_exit_code(&e)
        }
    };
    let _ = provider.disconnect().await;
    code
}

async fn cmd_cat(url: &str, path: &str, cli: &Cli, format: OutputFormat) -> i32 {
    const MAX_CAT_SIZE: u64 = 256 * 1024 * 1024; // 256 MB

    let (mut provider, initial_path) = match create_and_connect(url, cli, format).await {
        Ok(v) => v,
        Err(code) => return code,
    };

    let path = &resolve_cli_remote_path(&initial_path, path);
    // Guard: reject files larger than MAX_CAT_SIZE to prevent OOM
    if let Ok(size) = provider.size(path).await {
        if size > MAX_CAT_SIZE {
            print_error(
                format,
                &format!(
                    "File too large for cat ({}). Use 'get' instead.",
                    format_size(size)
                ),
                5,
            );
            let _ = provider.disconnect().await;
            return 5;
        }
    }

    match provider.download_to_bytes(path).await {
        Ok(data) => {
            match format {
                OutputFormat::Text => {
                    // Warn if binary content is being sent to a terminal
                    if io::stdout().is_terminal()
                        && data
                            .iter()
                            .take(8192)
                            .any(|&b| b == 0 || (b < 32 && b != b'\n' && b != b'\r' && b != b'\t'))
                    {
                        eprintln!("Warning: binary content detected. Pipe to file: aeroftp-cli cat ... > output.bin");
                    }
                    let stdout = io::stdout();
                    let mut handle = stdout.lock();
                    let _ = handle.write_all(&data);
                    let _ = handle.flush();
                }
                OutputFormat::Json => {
                    // For JSON, encode as UTF-8 string or base64 for binary
                    if let Ok(text) = String::from_utf8(data.clone()) {
                        print_json(&CliOk {
                            status: "ok",
                            message: text,
                        });
                    } else {
                        #[derive(Serialize)]
                        struct CatBinaryResult {
                            status: &'static str,
                            content: String,
                            encoding: &'static str,
                            size: usize,
                        }
                        print_json(&CatBinaryResult {
                            status: "ok",
                            content: base64::engine::general_purpose::STANDARD.encode(&data),
                            encoding: "base64",
                            size: data.len(),
                        });
                    }
                }
            }
            let _ = provider.disconnect().await;
            0
        }
        Err(e) => {
            print_error(
                format,
                &format!("cat failed: {}", e),
                provider_error_to_exit_code(&e),
            );
            let _ = provider.disconnect().await;
            provider_error_to_exit_code(&e)
        }
    }
}

async fn cmd_rcat(url: &str, remote: &str, cli: &Cli, format: OutputFormat) -> i32 {
    if remote.trim().is_empty() {
        print_error(format, "Missing remote path for rcat", 5);
        return 5;
    }

    let (mut provider, initial_path) = match create_and_connect(url, cli, format).await {
        Ok(v) => v,
        Err(code) => return code,
    };

    let remote = &resolve_cli_remote_path(&initial_path, remote);

    let mut temp = match tempfile::NamedTempFile::new() {
        Ok(file) => file,
        Err(e) => {
            print_error(
                format,
                &format!("Cannot create temporary file for stdin upload: {}", e),
                5,
            );
            let _ = provider.disconnect().await;
            return 5;
        }
    };

    let bytes = match io::copy(&mut io::stdin().lock(), &mut temp) {
        Ok(bytes) => bytes,
        Err(e) => {
            print_error(format, &format!("Cannot read stdin: {}", e), 2);
            let _ = provider.disconnect().await;
            return 2;
        }
    };

    if let Err(e) = temp.flush() {
        print_error(
            format,
            &format!("Cannot flush temporary stdin file: {}", e),
            5,
        );
        let _ = provider.disconnect().await;
        return 5;
    }

    let start = Instant::now();
    match provider
        .upload(temp.path().to_string_lossy().as_ref(), remote, None)
        .await
    {
        Ok(()) => {
            let elapsed = start.elapsed();
            let speed = if elapsed.as_secs_f64() > 0.0 {
                (bytes as f64 / elapsed.as_secs_f64()) as u64
            } else {
                0
            };
            match format {
                OutputFormat::Text => {
                    if !cli.quiet {
                        println!(
                            "stdin → {} ({}, {}, {:.1}s)",
                            remote,
                            format_size(bytes),
                            format_speed(speed),
                            elapsed.as_secs_f64()
                        );
                    }
                }
                OutputFormat::Json => {
                    print_json(&CliTransferResult {
                        status: "ok",
                        operation: "upload-stdin".to_string(),
                        path: remote.to_string(),
                        bytes,
                        elapsed_secs: elapsed.as_secs_f64(),
                        speed_bps: speed,
                    });
                }
            }
            let _ = provider.disconnect().await;
            0
        }
        Err(e) => {
            print_error(
                format,
                &format!("stdin upload failed: {}", e),
                provider_error_to_exit_code(&e),
            );
            let _ = provider.disconnect().await;
            provider_error_to_exit_code(&e)
        }
    }
}

async fn cmd_import_rclone(path: Option<String>, json: bool, apply: bool, cli: &Cli) -> i32 {
    use ftp_client_gui_lib::rclone_import;

    let config_path = match path {
        Some(p) => std::path::PathBuf::from(p),
        None => match rclone_import::default_rclone_config_path() {
            Some(p) => p,
            None => {
                if json {
                    println!(
                        "{}",
                        serde_json::json!({"error": "rclone configuration not found. Specify path manually."})
                    );
                } else {
                    eprintln!("Error: rclone configuration not found.");
                    eprintln!(
                        "Specify the path manually: aeroftp import rclone /path/to/rclone.conf"
                    );
                }
                return 1;
            }
        },
    };

    if !config_path.exists() {
        if json {
            println!(
                "{}",
                serde_json::json!({"error": format!("File not found: {}", config_path.display())})
            );
        } else {
            eprintln!("Error: file not found: {}", config_path.display());
        }
        return 1;
    }

    match rclone_import::import_rclone(&config_path) {
        Ok(result) => {
            // Issue #214: --apply mirrors the GUI `import_rclone_config` Tauri
            // command end-to-end: write the per-profile password under
            // `server_<id>`, the OAuth blob under `oauth_<slug>_<id>`, the
            // Jotta refresh under `jottacloud_refresh_<id>`, and append the
            // saved profiles to the GUI-shared `config_server_profiles`
            // entry. Without `--apply` the call is dry-run, preserving the
            // previous CLI behaviour.
            let mut applied_summary: Option<RcloneApplySummary> = None;
            if apply {
                match apply_rclone_import_to_vault(cli, &result).await {
                    Ok(summary) => applied_summary = Some(summary),
                    Err(err) => {
                        if json {
                            println!(
                                "{}",
                                serde_json::json!({"error": format!("Failed to apply import: {}", err)})
                            );
                        } else {
                            eprintln!("Error: failed to apply import: {}", err);
                        }
                        return 1;
                    }
                }
            }

            if json {
                // Redact credentials: never output plaintext passwords to stdout
                let mut redacted = serde_json::json!({
                    "servers": result.servers.iter().map(|s| serde_json::json!({
                        "id": s.id,
                        "name": s.name,
                        "host": s.host,
                        "port": s.port,
                        "username": s.username,
                        "protocol": s.protocol,
                        "initialPath": s.initial_path,
                        "options": s.options,
                        "hasCredential": s.credential.is_some(),
                    })).collect::<Vec<_>>(),
                    "skipped": serde_json::to_value(&result.skipped).unwrap_or_default(),
                    "sourcePath": result.source_path,
                    "totalRemotes": result.total_remotes,
                    "applied": apply,
                });
                if let Some(summary) = &applied_summary {
                    redacted["appliedSummary"] = serde_json::json!({
                        "passwordsStored": summary.passwords_stored,
                        "oauthTokensStored": summary.oauth_tokens_stored,
                        "jottaRefreshStored": summary.jotta_refresh_stored,
                        "profilesAppended": summary.profiles_appended,
                    });
                }
                println!(
                    "{}",
                    serde_json::to_string_pretty(&redacted).unwrap_or_default()
                );
            } else {
                println!(
                    "Scanned {} remotes from {}",
                    result.total_remotes, result.source_path
                );
                println!();

                if !result.servers.is_empty() {
                    println!("Importable ({}):", result.servers.len());
                    for s in &result.servers {
                        let proto = s.protocol.as_deref().unwrap_or("?");
                        let cred = if s.credential.is_some() {
                            " [credentials]"
                        } else {
                            ""
                        };
                        println!(
                            "  {} - {}://{}@{}:{}{}",
                            s.name, proto, s.username, s.host, s.port, cred
                        );
                    }
                    println!();
                }

                if !result.skipped.is_empty() {
                    println!("Skipped ({}):", result.skipped.len());
                    for s in &result.skipped {
                        println!("  {} - {} ({})", s.name, s.rclone_type, s.reason);
                    }
                    println!();
                }

                if let Some(summary) = &applied_summary {
                    println!(
                        "Applied to vault: {} profiles, {} passwords, {} OAuth tokens, {} Jotta refresh tokens",
                        summary.profiles_appended,
                        summary.passwords_stored,
                        summary.oauth_tokens_stored,
                        summary.jotta_refresh_stored,
                    );
                } else {
                    println!(
                        "Dry-run: re-run with --apply to write profiles + OAuth tokens into the vault."
                    );
                }
            }
            0
        }
        Err(e) => {
            if json {
                println!("{}", serde_json::json!({"error": e}));
            } else {
                eprintln!("Error: {}", e);
            }
            1
        }
    }
}

/// Tally of vault-side side effects performed by `--apply`. Reported back
/// through both the text and JSON output of `aeroftp-cli import rclone
/// --apply`. Issue #214.
struct RcloneApplySummary {
    passwords_stored: usize,
    oauth_tokens_stored: usize,
    jotta_refresh_stored: usize,
    profiles_appended: usize,
}

/// Map a saved-server protocol identifier to the `OAuthProvider` slug used
/// in the vault key (`oauth_<slug>_<profile_id>`). Mirrors
/// `oauth_vault_slug_for_protocol` in `lib.rs` so the CLI `--apply` path
/// writes the same vault layout the GUI flow produces. Issue #214.
fn cli_oauth_vault_slug_for_protocol(protocol: &str) -> Option<&'static str> {
    match protocol.to_lowercase().as_str() {
        "googledrive" | "google_drive" | "google" => Some("google"),
        "googlephotos" | "google_photos" => Some("googlephotos"),
        "dropbox" => Some("dropbox"),
        "onedrive" | "microsoft" => Some("onedrive"),
        "box" => Some("box"),
        "pcloud" => Some("pcloud"),
        "zohoworkdrive" | "zoho_workdrive" | "zoho" => Some("zohoworkdrive"),
        "yandexdisk" | "yandex_disk" | "yandex" => Some("yandexdisk"),
        _ => None,
    }
}

/// Write the imported rclone profiles, passwords and OAuth / Jotta token
/// blobs into the AeroFTP vault, then append the new profiles to
/// `config_server_profiles` so the GUI lists them on next launch. Mirrors
/// the `import_rclone_config` Tauri command in `lib.rs`. Issue #214.
async fn apply_rclone_import_to_vault(
    cli: &Cli,
    result: &ftp_client_gui_lib::rclone_import::RcloneImportResult,
) -> Result<RcloneApplySummary, String> {
    let store = open_vault(cli)?;

    let mut passwords_stored = 0usize;
    let mut oauth_tokens_stored = 0usize;
    let mut jotta_refresh_stored = 0usize;

    // MUV-3: dual-write each imported credential (vault + the scoped user's
    // partition). The vault write stays authoritative (hard error on failure).
    let scoped_uid = scoped_credential_user_id(cli, &store);
    for server in &result.servers {
        if let Some(ref cred) = server.credential {
            dual_store_server_cred_checked(
                &store,
                scoped_uid,
                &format!("server_{}", server.id),
                cred,
            )
            .map_err(|e| format!("vault write failed for {}: {}", server.id, e))?;
            passwords_stored += 1;
        }
    }

    let protocol_by_id: std::collections::HashMap<&str, String> = result
        .servers
        .iter()
        .map(|s| {
            (
                s.id.as_str(),
                s.protocol.clone().unwrap_or_default().to_lowercase(),
            )
        })
        .collect();
    for (profile_id, secrets) in &result.provider_secrets {
        let protocol = match protocol_by_id.get(profile_id.as_str()) {
            Some(p) => p,
            None => continue,
        };
        if let Some(ref oauth_json) = secrets.oauth {
            if let Some(slug) = cli_oauth_vault_slug_for_protocol(protocol) {
                // MUV-4: dual-write into vault + the scoped user's partition.
                dual_store_typed_cred_checked(
                    &store,
                    scoped_uid,
                    &format!("oauth_{}_{}", slug, profile_id),
                    "oauth",
                    oauth_json,
                )
                .map_err(|e| format!("vault write failed for oauth {}: {}", profile_id, e))?;
                oauth_tokens_stored += 1;
            }
        }
        if let Some(ref jotta_json) = secrets.jotta_refresh {
            if protocol == "jottacloud" {
                dual_store_typed_cred_checked(
                    &store,
                    scoped_uid,
                    &format!("jottacloud_refresh_{}", profile_id),
                    "jottacloud_refresh",
                    jotta_json,
                )
                .map_err(|e| format!("vault write failed for jotta {}: {}", profile_id, e))?;
                jotta_refresh_stored += 1;
            }
        }
    }

    // Append the imported profiles to the active user's partition. Existing
    // entries are preserved; new ids that already exist in the list are
    // skipped to keep the operation idempotent on retry. Falls back to the
    // legacy blob when the partition layer is unavailable (downgrade).
    let mut profiles: Vec<serde_json::Value> =
        load_active_user_profiles(cli, &store).unwrap_or_default();
    let existing_ids: std::collections::HashSet<String> = profiles
        .iter()
        .filter_map(|p| p.get("id").and_then(|v| v.as_str()).map(String::from))
        .collect();
    let mut profiles_appended = 0usize;
    for server in &result.servers {
        if existing_ids.contains(&server.id) {
            continue;
        }
        profiles.push(serde_json::json!({
            "id": server.id,
            "name": server.name,
            "host": server.host,
            "port": server.port,
            "username": server.username,
            "protocol": server.protocol,
            "initialPath": server.initial_path,
            "color": server.color,
            "lastConnected": server.last_connected,
            "options": server.options,
            "providerId": server.provider_id,
        }));
        profiles_appended += 1;
    }
    save_active_user_profiles(cli, &store, &profiles)
        .map_err(|e| format!("vault write failed for server profiles: {}", e))?;

    Ok(RcloneApplySummary {
        passwords_stored,
        oauth_tokens_stored,
        jotta_refresh_stored,
        profiles_appended,
    })
}

/// Shared text/JSON printer for every bridge importer. `v` is the
/// `serde_json::Value` produced by `serde_json::to_value(&<Src>ImportResult)`,
/// so its keys are the camelCase serde shape: `servers`, `skipped`,
/// `sourcePath`, `totalRemotes`. This reproduces the exact output of
/// `cmd_import_rclone`: credentials are NEVER printed; every server reports
/// `hasCredential` (bool) instead of the secret, both in text and JSON.
fn print_bridge_import(v: &serde_json::Value, json: bool, source_label: &str) -> i32 {
    let servers = v
        .get("servers")
        .and_then(|s| s.as_array())
        .cloned()
        .unwrap_or_default();
    let skipped = v
        .get("skipped")
        .and_then(|s| s.as_array())
        .cloned()
        .unwrap_or_default();
    let source_path = v
        .get("sourcePath")
        .and_then(|s| s.as_str())
        .unwrap_or("")
        .to_string();
    let total_remotes = v
        .get("totalRemotes")
        .and_then(|s| s.as_u64())
        .unwrap_or(servers.len() as u64);

    if json {
        // Redact credentials: never echo plaintext secrets to stdout.
        let redacted_servers: Vec<serde_json::Value> = servers
            .iter()
            .map(|s| {
                serde_json::json!({
                    "id": s.get("id").cloned().unwrap_or(serde_json::Value::Null),
                    "name": s.get("name").cloned().unwrap_or(serde_json::Value::Null),
                    "host": s.get("host").cloned().unwrap_or(serde_json::Value::Null),
                    "port": s.get("port").cloned().unwrap_or(serde_json::Value::Null),
                    "username": s.get("username").cloned().unwrap_or(serde_json::Value::Null),
                    "protocol": s.get("protocol").cloned().unwrap_or(serde_json::Value::Null),
                    "initialPath": s.get("initialPath").cloned().unwrap_or(serde_json::Value::Null),
                    "options": s.get("options").cloned().unwrap_or(serde_json::Value::Null),
                    "hasCredential": s
                        .get("credential")
                        .map(|c| !c.is_null())
                        .unwrap_or(false),
                })
            })
            .collect();
        let envelope = serde_json::json!({
            "servers": redacted_servers,
            "skipped": skipped,
            "sourcePath": source_path,
            "totalRemotes": total_remotes,
        });
        println!(
            "{}",
            serde_json::to_string_pretty(&envelope).unwrap_or_default()
        );
    } else {
        println!("Scanned {} remotes from {}", total_remotes, source_path);
        println!();

        if !servers.is_empty() {
            println!("Importable ({}):", servers.len());
            for s in &servers {
                let name = s.get("name").and_then(|x| x.as_str()).unwrap_or("?");
                let proto = s.get("protocol").and_then(|x| x.as_str()).unwrap_or("?");
                let user = s.get("username").and_then(|x| x.as_str()).unwrap_or("");
                let host = s.get("host").and_then(|x| x.as_str()).unwrap_or("");
                let port = s.get("port").and_then(|x| x.as_u64()).unwrap_or(0);
                let cred = if s.get("credential").map(|c| !c.is_null()).unwrap_or(false) {
                    " [credentials]"
                } else {
                    ""
                };
                println!(
                    "  {} - {}://{}@{}:{}{}",
                    name, proto, user, host, port, cred
                );
            }
            println!();
        }

        if !skipped.is_empty() {
            println!("Skipped ({}):", skipped.len());
            for s in &skipped {
                let name = s.get("name").and_then(|x| x.as_str()).unwrap_or("?");
                let kind = s.get("kind").and_then(|x| x.as_str()).unwrap_or("?");
                let reason = s.get("reason").and_then(|x| x.as_str()).unwrap_or("?");
                println!("  {} - {} ({})", name, kind, reason);
            }
            println!();
        }

        println!(
            "To import into the GUI, use Settings > Export/Import > Import from {}",
            source_label
        );
    }
    0
}

/// Generic importer for the 12 profile-bridge sources. Resolves the source
/// config path via the matching `default_*_config_path` when `path` is
/// `None`, calls the matching `import_*`, then serializes the result and
/// hands off to the shared `print_bridge_import` printer. Credentials are
/// never written to stdout (see `print_bridge_import`). For `restic`, `path`
/// is interpreted as a RESTIC_REPOSITORY_FILE; when absent the resolver
/// falls back to the RESTIC_REPOSITORY / RESTIC_REPOSITORY_FILE environment
/// variables via `restic_import::import_restic_from_env`.
async fn cmd_import_bridge(src: &str, path: Option<String>, json: bool) -> i32 {
    use ftp_client_gui_lib::{
        aws_credentials_import, cyberduck_import, dreamweaver_import, duplicacy_import,
        kopia_import, lftp_import, mc_import, mobaxterm_import, putty_import, restic_import,
        s3cmd_import, ssh_config_import,
    };

    // Resolve the config path. `restic` has its own env-aware path:
    // a missing path is legitimate (env fallback), so it skips the
    // generic "config not found / file not found" guards below.
    let resolved: Option<std::path::PathBuf> = match path {
        Some(p) => Some(std::path::PathBuf::from(p)),
        None => match src {
            "aws" => aws_credentials_import::default_aws_credentials_config_path(),
            "ssh" => ssh_config_import::default_ssh_config_path(),
            "mc" => mc_import::default_mc_config_path(),
            "cyberduck" => cyberduck_import::default_cyberduck_config_path(),
            "s3cmd" => s3cmd_import::default_s3cmd_config_path(),
            "lftp" => lftp_import::default_lftp_config_path(),
            "putty" => putty_import::default_putty_config_path(),
            "mobaxterm" => mobaxterm_import::default_mobaxterm_config_path(),
            "dreamweaver" => dreamweaver_import::default_dreamweaver_config_path(),
            "kopia" => kopia_import::default_kopia_config_path(),
            "duplicacy" => duplicacy_import::default_duplicacy_config_path(),
            "restic" => restic_import::default_restic_config_path(),
            _ => None,
        },
    };

    if src != "restic" {
        let cfg = match &resolved {
            Some(p) => p.clone(),
            None => {
                let msg = format!(
                    "{} configuration not found. Specify the path manually: aeroftp import {} /path/to/config",
                    src, src
                );
                if json {
                    eprintln!("{}", serde_json::json!({ "error": msg }));
                } else {
                    eprintln!("Error: {}", msg);
                }
                return 1;
            }
        };
        if !cfg.exists() {
            let msg = format!("File not found: {}", cfg.display());
            if json {
                eprintln!("{}", serde_json::json!({ "error": msg }));
            } else {
                eprintln!("Error: {}", msg);
            }
            return 1;
        }
    }

    // Each arm returns `Result<serde_json::Value, String>` so the typed
    // `<Src>ImportResult` is collapsed to the shared camelCase shape.
    let outcome: Result<serde_json::Value, String> = match src {
        "aws" => aws_credentials_import::import_aws_credentials(resolved.as_deref().unwrap())
            .and_then(|r| serde_json::to_value(r).map_err(|e| e.to_string())),
        "ssh" => ssh_config_import::import_ssh_config(resolved.as_deref().unwrap())
            .and_then(|r| serde_json::to_value(r).map_err(|e| e.to_string())),
        "mc" => mc_import::import_mc(resolved.as_deref().unwrap())
            .and_then(|r| serde_json::to_value(r).map_err(|e| e.to_string())),
        "cyberduck" => cyberduck_import::import_cyberduck(resolved.as_deref().unwrap())
            .and_then(|r| serde_json::to_value(r).map_err(|e| e.to_string())),
        "s3cmd" => s3cmd_import::import_s3cmd(resolved.as_deref().unwrap())
            .and_then(|r| serde_json::to_value(r).map_err(|e| e.to_string())),
        "lftp" => lftp_import::import_lftp(resolved.as_deref().unwrap())
            .and_then(|r| serde_json::to_value(r).map_err(|e| e.to_string())),
        "putty" => putty_import::import_putty(resolved.as_deref().unwrap())
            .and_then(|r| serde_json::to_value(r).map_err(|e| e.to_string())),
        "mobaxterm" => mobaxterm_import::import_mobaxterm(resolved.as_deref().unwrap())
            .and_then(|r| serde_json::to_value(r).map_err(|e| e.to_string())),
        "dreamweaver" => dreamweaver_import::import_dreamweaver(resolved.as_deref().unwrap())
            .and_then(|r| serde_json::to_value(r).map_err(|e| e.to_string())),
        "kopia" => kopia_import::import_kopia(resolved.as_deref().unwrap())
            .and_then(|r| serde_json::to_value(r).map_err(|e| e.to_string())),
        "duplicacy" => duplicacy_import::import_duplicacy(resolved.as_deref().unwrap())
            .and_then(|r| serde_json::to_value(r).map_err(|e| e.to_string())),
        "restic" => {
            let r = match resolved.as_deref() {
                Some(p) => restic_import::import_restic(p),
                None => restic_import::import_restic_from_env(&|k| std::env::var(k).ok()),
            };
            r.and_then(|r| serde_json::to_value(r).map_err(|e| e.to_string()))
        }
        other => Err(format!("unknown import source: {}", other)),
    };

    match outcome {
        Ok(v) => print_bridge_import(&v, json, src),
        Err(e) => {
            if json {
                eprintln!("{}", serde_json::json!({ "error": e }));
            } else {
                eprintln!("Error: {}", e);
            }
            1
        }
    }
}

/// Shared scaffold for the three `Commands::Export` subcommands. Reads
/// the GUI-managed profile list from the vault, resolves credentials
/// against the same `server_<id>` keys used by the connect path, and
/// hands off to the per-format `pub fn export_*` functions in
/// `rclone_import` / `winscp_import` / `filezilla_import` (the same
/// functions called by the GUI Export modal).
struct ProfileExportScaffold {
    id: String,
    name: String,
    host: String,
    port: u32,
    username: String,
    protocol: String,
    options: Option<serde_json::Value>,
    provider_id: Option<String>,
    initial_path: Option<String>,
    secret: String,
}

#[derive(Default)]
struct ExportCollected {
    profiles: Vec<ProfileExportScaffold>,
    passwords: std::collections::HashMap<String, String>,
    skipped: Vec<(String, String)>,
}

/// Pull every profile that matches `name_filter` (or all profiles if `None`)
/// from the vault, decoding `server_<id>` credentials. `oauth_protocols` are
/// always recorded as skipped because rclone/WinSCP/FileZilla all need their
/// own OAuth flow for those.
fn collect_export_scaffold(
    store: &ftp_client_gui_lib::credential_store::CredentialStore,
    servers_json: &serde_json::Value,
    name_filter: Option<&[String]>,
    supported_protocols: &[&str],
    oauth_protocols: &[&str],
) -> Result<ExportCollected, String> {
    let arr = servers_json
        .as_array()
        .ok_or_else(|| "vault profiles payload is not an array".to_string())?;
    let mut out = ExportCollected::default();

    for entry in arr {
        let name = entry.get("name").and_then(|v| v.as_str()).unwrap_or("");
        if name.is_empty() {
            continue;
        }
        if let Some(filter) = name_filter {
            if !filter.iter().any(|n| n == name) {
                continue;
            }
        }

        let id = entry.get("id").and_then(|v| v.as_str()).unwrap_or("");
        let protocol = entry
            .get("protocol")
            .and_then(|v| v.as_str())
            .unwrap_or("ftp")
            .to_string();
        let host = entry
            .get("host")
            .and_then(|v| v.as_str())
            .unwrap_or("")
            .to_string();
        let username = entry
            .get("username")
            .and_then(|v| v.as_str())
            .unwrap_or("")
            .to_string();
        let port = entry.get("port").and_then(|v| v.as_u64()).unwrap_or(0) as u32;
        let provider_id = entry
            .get("providerId")
            .and_then(|v| v.as_str())
            .map(str::to_string);
        let options = entry.get("options").cloned();
        let initial_path = entry
            .get("initialPath")
            .and_then(|v| v.as_str())
            .map(str::to_string);

        // MUV-3: active user's partition with fallback to the legacy vault.
        let secret = if id.is_empty() {
            String::new()
        } else if protocol == "jottacloud" {
            // Jotta authenticates via its OIDC refresh blob ({refresh_token,
            // token_endpoint, username}), not a `server_<id>` password. The
            // provider persists it under the per-profile key
            // `jottacloud_refresh_<id>` when a profile id is set, or the
            // singleton `jottacloud_refresh` otherwise (see
            // `JottacloudProvider::refresh_token_account`). Try per-profile
            // first, then fall back to the singleton, so export_rclone can
            // rebuild the rclone `token` line from it.
            let uid = active_credential_user_id(store);
            read_server_cred(store, uid, &format!("jottacloud_refresh_{}", id))
                .or_else(|| read_server_cred(store, uid, "jottacloud_refresh"))
                .unwrap_or_default()
        } else {
            match read_server_cred(
                store,
                active_credential_user_id(store),
                &format!("server_{}", id),
            ) {
                Some(stored) => {
                    if let Ok(v) = serde_json::from_str::<serde_json::Value>(&stored) {
                        v.get("password")
                            .and_then(|x| x.as_str())
                            .unwrap_or(stored.trim_matches('"'))
                            .to_string()
                    } else {
                        stored
                    }
                }
                None => String::new(),
            }
        };

        let proto_supported = supported_protocols.contains(&protocol.as_str());
        let proto_oauth = oauth_protocols.contains(&protocol.as_str());

        if proto_oauth {
            out.skipped.push((
                name.to_string(),
                format!(
                    "{} requires a provider-issued OAuth client (run the target tool's interactive setup)",
                    protocol
                ),
            ));
            continue;
        }
        if !proto_supported {
            out.skipped.push((
                name.to_string(),
                format!("protocol {} not exportable", protocol),
            ));
            continue;
        }
        // SFTP profiles authenticate by SSH key (path in
        // `options.private_key_path`), so an empty vault password is
        // legitimate for them. Everything else genuinely needs a stored
        // secret. Key-auth SFTP must still reach export_rclone, which emits
        // the `key_file` reference from `options`.
        let has_sftp_key = protocol == "sftp"
            && options
                .as_ref()
                .and_then(|o| o.get("private_key_path"))
                .and_then(|v| v.as_str())
                .map(|s| !s.trim().is_empty())
                .unwrap_or(false);

        // #128-D: OAuth-token providers (Drive/Dropbox/OneDrive/Box/pCloud/
        // Yandex) carry no `server_<id>` password; their token + BYO
        // client_id/secret are injected from the vault at export time, so an
        // empty vault password is legitimate (like key-auth SFTP).
        let is_rclone_oauth =
            ftp_client_gui_lib::bridge_commands::rclone_oauth_client_cred_key(&protocol).is_some();

        if secret.is_empty() && !has_sftp_key && !is_rclone_oauth {
            out.skipped
                .push((name.to_string(), "no credential in vault".to_string()));
            continue;
        }

        if !secret.is_empty() {
            out.passwords.insert(name.to_string(), secret.clone());
        }
        out.profiles.push(ProfileExportScaffold {
            id: id.to_string(),
            name: name.to_string(),
            host,
            port,
            username,
            protocol,
            options,
            provider_id,
            initial_path,
            secret,
        });
    }

    Ok(out)
}

/// Parse the comma-separated --profiles filter into a Vec.
fn parse_profile_name_filter(arg: Option<String>) -> Option<Vec<String>> {
    arg.map(|s| {
        s.split(',')
            .map(|tok| tok.trim().to_string())
            .filter(|tok| !tok.is_empty())
            .collect()
    })
}

/// Export saved profiles to rclone.conf. Reuses the same Rust function the
/// GUI Export modal calls. The vault unlocks automatically when the OS
/// keyring is available; the resulting rclone.conf contains rclone-obscured
/// passwords (AES-256-CTR) so it can be consumed directly by
/// `rclone --config <file> ...`.
async fn cmd_export_rclone(
    output: Option<String>,
    profiles: Option<String>,
    json: bool,
    cli: &Cli,
    format: OutputFormat,
) -> i32 {
    use ftp_client_gui_lib::rclone_import::{export_rclone, RcloneExportServer};

    let store = match open_vault(cli) {
        Ok(s) => s,
        Err(e) => {
            print_error(format, &format!("vault unlock failed: {}", e), 5);
            return 5;
        }
    };
    let servers_json = match read_vault_profiles(cli, &store) {
        Ok(v) => v,
        Err(e) => {
            print_error(format, &format!("read profiles: {}", e), 4);
            return 4;
        }
    };
    let filter = parse_profile_name_filter(profiles);

    // Single source of truth shared with the GUI bridge: the credential
    // backends (FTP/SFTP/WebDAV/S3/Filen/Mega/Azure/Swift/Koofr/OpenDrive/
    // Backblaze) plus the #128-D OAuth-token providers (Drive/Dropbox/
    // OneDrive/Box/pCloud/Yandex), whose token + BYO client_id/secret are
    // injected below. Jottacloud is appended CLI-only: its rclone export
    // rebuilds the persisted OIDC refresh token into a working token (verified
    // end-to-end against a live account; `collect_export_scaffold` loads the
    // refresh blob). The GUI bridge has no refresh-blob injection so it gates
    // Jottacloud, hence it is not in `bridge_supported_protocols`.
    let mut supported: Vec<&str> =
        ftp_client_gui_lib::bridge_shared::bridge_supported_protocols("rclone").to_vec();
    supported.push("jottacloud");
    let oauth: [&str; 0] = [];

    let collected =
        match collect_export_scaffold(&store, &servers_json, filter.as_deref(), &supported, &oauth)
        {
            Ok(c) => c,
            Err(e) => {
                print_error(format, &e, 4);
                return 4;
            }
        };

    if collected.profiles.is_empty() {
        emit_empty_export(json, format, &collected.skipped);
        return 4;
    }

    let exportable: Vec<RcloneExportServer> = collected
        .profiles
        .iter()
        .map(|p| {
            // #128-D: inject the vaulted OAuth token + BYO client_id/secret so
            // OAuth remotes export usable (refreshable) from the CLI too, using
            // the exact same helper the GUI bridge calls.
            let mut options = p.options.clone();
            ftp_client_gui_lib::bridge_commands::inject_rclone_oauth_export_options(
                &mut options,
                &store,
                &p.protocol,
                &p.id,
            );
            // #128-D: same for the vaulted Filen CLI API key (issue #230), which
            // rclone's `filen` backend requires and cannot derive from the
            // password.
            ftp_client_gui_lib::bridge_commands::inject_rclone_filen_export_options(
                &mut options,
                &store,
                &p.protocol,
                &p.id,
            );
            // #128-D: and the vaulted OneDrive Graph drive_id/drive_type, which
            // rclone's `onedrive` backend needs and AeroFTP captures at connect.
            ftp_client_gui_lib::bridge_commands::inject_rclone_onedrive_export_options(
                &mut options,
                &store,
                &p.protocol,
                &p.id,
            );
            RcloneExportServer {
                name: p.name.clone(),
                host: p.host.clone(),
                port: p.port,
                username: p.username.clone(),
                protocol: Some(p.protocol.clone()),
                options,
                provider_id: p.provider_id.clone(),
            }
        })
        .collect();

    let target_path = match output {
        Some(p) => std::path::PathBuf::from(p),
        None => std::env::temp_dir().join("aeroftp-rclone-export.conf"),
    };

    match export_rclone(&exportable, &collected.passwords, &target_path) {
        Ok(count) => {
            emit_export_success(json, "rclone.conf", count, &target_path, &collected.skipped);
            0
        }
        Err(e) => {
            print_error(format, &format!("export failed: {}", e), 4);
            4
        }
    }
}

async fn cmd_export_winscp(
    output: Option<String>,
    profiles: Option<String>,
    json: bool,
    cli: &Cli,
    format: OutputFormat,
) -> i32 {
    use ftp_client_gui_lib::winscp_import::{export_winscp, WinScpExportServer};

    let store = match open_vault(cli) {
        Ok(s) => s,
        Err(e) => {
            print_error(format, &format!("vault unlock failed: {}", e), 5);
            return 5;
        }
    };
    let servers_json = match read_vault_profiles(cli, &store) {
        Ok(v) => v,
        Err(e) => {
            print_error(format, &format!("read profiles: {}", e), 4);
            return 4;
        }
    };
    let filter = parse_profile_name_filter(profiles);

    // WinSCP only handles FTP/FTPS/SFTP. Everything else is skipped.
    let supported = ["ftp", "ftps", "sftp"];
    let oauth: [&str; 0] = [];

    let collected =
        match collect_export_scaffold(&store, &servers_json, filter.as_deref(), &supported, &oauth)
        {
            Ok(c) => c,
            Err(e) => {
                print_error(format, &e, 4);
                return 4;
            }
        };
    if collected.profiles.is_empty() {
        emit_empty_export(json, format, &collected.skipped);
        return 4;
    }

    let exportable: Vec<WinScpExportServer> = collected
        .profiles
        .iter()
        .map(|p| WinScpExportServer {
            name: p.name.clone(),
            host: p.host.clone(),
            port: p.port,
            username: p.username.clone(),
            protocol: Some(p.protocol.clone()),
            options: p.options.clone(),
            initial_path: p.initial_path.clone(),
        })
        .collect();

    let target_path = match output {
        Some(p) => std::path::PathBuf::from(p),
        None => std::env::temp_dir().join("aeroftp-winscp-export.ini"),
    };

    match export_winscp(&exportable, &collected.passwords, &target_path) {
        Ok(count) => {
            emit_export_success(json, "WinSCP.ini", count, &target_path, &collected.skipped);
            0
        }
        Err(e) => {
            print_error(format, &format!("export failed: {}", e), 4);
            4
        }
    }
}

