// ── Crypt Overlay - Transparent Encryption Layer ─────────────────

/// Maximum directory recursion depth for native AeroCrypt folder-tree
/// traversal. Kept at the historical crypt-overlay bound (64) so the CLI
/// refuses pathologically deep trees identically to the GUI browser.
const CRYPT_OVERLAY_MAX_DEPTH: usize = 64;

/// Reduce a decrypted name to a single safe local path component, so a tampered
/// or malformed obfuscated name can never escape the destination directory via
/// embedded separators or `.`/`..` (defense in depth: a name is attacker
/// influenced only by someone who already holds the overlay password).
fn crypt_sanitize_component(name: &str) -> String {
    let cleaned: String = name
        .chars()
        .map(|c| {
            if c == '/' || c == '\\' || c == '\0' {
                '_'
            } else {
                c
            }
        })
        .collect();
    if cleaned.is_empty() || cleaned == "." || cleaned == ".." {
        "_".to_string()
    } else {
        cleaned
    }
}

/// Encrypt a plaintext relative path to its obfuscated remote form by
/// encrypting each component independently with AES-256-SIV. Deterministic, so
/// the same tree always maps to the same remote layout (what keeps an encrypted
/// scope listable and syncable object by object). Empty and `.` segments are
/// dropped; `..` is rejected to forbid traversal in crypt paths.
fn crypt_encrypt_rel_path(master_key: &[u8; 32], rel: &str) -> Result<String, String> {
    use ftp_client_gui_lib::aerocrypt::names;
    let mut parts: Vec<String> = Vec::new();
    for comp in rel.split('/') {
        if comp.is_empty() || comp == "." {
            continue;
        }
        if comp == ".." {
            return Err("path traversal ('..') is not allowed in crypt paths".to_string());
        }
        parts.push(names::encrypt_filename(master_key, comp)?);
    }
    Ok(parts.join("/"))
}

/// CLI commands for crypt overlay operations.
/// Read a keyfile from disk and return its digest, or `None` when no path was
/// given. Canonicalizes structured keyfiles so line-ending mangling is safe.
fn read_keyfile_digest(keyfile: &Option<String>) -> Result<Option<[u8; 32]>, String> {
    match keyfile {
        None => Ok(None),
        Some(path) => {
            let bytes =
                std::fs::read(path).map_err(|e| format!("cannot read keyfile '{path}': {e}"))?;
            ftp_client_gui_lib::aerocrypt::keyfile_digest_from_file(&bytes).map(Some)
        }
    }
}

/// Resolve the keyfile digest for `crypt init`, generating a fresh transfer-safe
/// keyfile first when `--keyfile-gen` was given (refuses to overwrite).
fn resolve_init_keyfile(
    keyfile: &Option<String>,
    keyfile_gen: &Option<String>,
) -> Result<Option<[u8; 32]>, String> {
    if let Some(path) = keyfile_gen {
        if std::path::Path::new(path).exists() {
            return Err(format!(
                "keyfile '{path}' already exists; refusing to overwrite"
            ));
        }
        let content = ftp_client_gui_lib::aerocrypt::generate_keyfile_v1();
        std::fs::write(path, content.as_bytes())
            .map_err(|e| format!("cannot write keyfile '{path}': {e}"))?;
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            let _ = std::fs::set_permissions(path, std::fs::Permissions::from_mode(0o600));
        }
        eprintln!(
            "Generated keyfile at '{path}'. Back it up: losing it makes the vault unopenable."
        );
        return ftp_client_gui_lib::aerocrypt::keyfile_digest_from_file(content.as_bytes())
            .map(Some);
    }
    read_keyfile_digest(keyfile)
}

async fn cmd_crypt_init(
    url: &str,
    path: &str,
    password: &str,
    keyfile_digest: Option<&[u8; 32]>,
    force: bool,
    cli: &Cli,
    format: OutputFormat,
) -> i32 {
    use ftp_client_gui_lib::aerocrypt::overlay;
    // New overlays are created as AECR v3 (length-bound content + key-bound
    // config MAC). Derive the master key first so we can both validate the
    // password and bind the config MAC. An optional keyfile is mixed into the
    // KDF and recorded in the config (kdf_inputs + a fresh vault_id).
    let salt = overlay::random_salt_v3();
    let cfg = overlay::OverlayConfig::v3_bootstrap(salt);
    let master_key = match overlay::derive_master_key_with_keyfile(&cfg, password, keyfile_digest) {
        Ok(k) => k,
        Err(e) => {
            print_error(format, &format!("Invalid password: {}", e), 6);
            return 6;
        }
    };
    let config_json = if keyfile_digest.is_some() {
        // F5: no keyfile_hint on the remote by default.
        let vault_id = overlay::random_vault_id();
        match overlay::init_config_v3_with_keyfile(&salt, &master_key, &vault_id, None) {
            Ok(j) => j,
            Err(e) => {
                print_error(format, &format!("Failed to build crypt config: {}", e), 5);
                return 5;
            }
        }
    } else {
        match overlay::init_config_v3(&salt, &master_key) {
            Ok(j) => j,
            Err(e) => {
                print_error(format, &format!("Failed to build crypt config: {}", e), 5);
                return 5;
            }
        }
    };

    let (mut provider, initial_path) = match create_and_connect(url, cli, format).await {
        Ok(v) => v,
        Err(code) => return code,
    };

    let base_path = normalize_remote_path(&resolve_cli_remote_path(&initial_path, path));
    let config_path = format!("{}/.aeroftp-crypt.json", base_path.trim_end_matches('/'));

    // C4: never silently clobber an existing overlay. Re-init rotates the salt,
    // which permanently orphans every file already encrypted under it.
    if !force && provider.size(&config_path).await.is_ok() {
        print_error(
            format,
            &format!(
                "an AeroCrypt overlay already exists at {} (existing files would become \
                 permanently undecryptable). Re-run with --force to overwrite.",
                base_path
            ),
            9,
        );
        return 9;
    }

    // Stage the config to a tempfile, then upload.
    let tmp = match tempfile::NamedTempFile::new() {
        Ok(t) => t,
        Err(e) => {
            print_error(format, &format!("Failed to create temp file: {}", e), 11);
            return 11;
        }
    };
    if let Err(e) = std::fs::write(tmp.path(), &config_json) {
        print_error(format, &format!("Failed to stage crypt config: {}", e), 11);
        return 11;
    }

    match provider
        .upload(&tmp.path().to_string_lossy(), &config_path, None)
        .await
    {
        Ok(()) => {
            if matches!(format, OutputFormat::Json) {
                print_json(&serde_json::json!({"status": "ok", "path": config_path}));
            } else if !cli.quiet {
                println!("Crypt overlay initialized at {}", base_path);
                println!("Config: {}", config_path);
                println!(
                    "Cipher: AES-256-GCM-SIV (content) + AES-256-KW (key wrap) + AES-256-SIV (filenames)"
                );
                println!("KDF: Argon2id (128 MB, 4 iterations)");
                if keyfile_digest.is_some() {
                    println!(
                        "Second factor: keyfile required (keep both the password and the keyfile)"
                    );
                }
            }
            0
        }
        Err(e) => {
            print_error(format, &format!("Failed to init crypt: {}", e), 4);
            4
        }
    }
}

/// Reconcile the supplied keyfile against what the overlay config requires, so a
/// mismatch is a clear error instead of a confusing "wrong password" from a
/// silently-wrong derived key.
fn reconcile_keyfile<'a>(
    cfg: &ftp_client_gui_lib::aerocrypt::overlay::OverlayConfig,
    keyfile_digest: Option<&'a [u8; 32]>,
) -> Result<Option<&'a [u8; 32]>, String> {
    match (cfg.requires_keyfile(), keyfile_digest) {
        (true, None) => Err("this overlay requires a keyfile; pass --keyfile <file>".to_string()),
        (false, Some(_)) => {
            Err("this overlay was not created with a keyfile; omit --keyfile".to_string())
        }
        (true, kd) => Ok(kd),
        (false, _) => Ok(None),
    }
}

async fn cmd_crypt_ls(
    url: &str,
    path: &str,
    password: &str,
    keyfile_digest: Option<&[u8; 32]>,
    recursive: bool,
    cli: &Cli,
    format: OutputFormat,
) -> i32 {
    use ftp_client_gui_lib::aerocrypt::{names, overlay};
    let (mut provider, initial_path) = match create_and_connect(url, cli, format).await {
        Ok(v) => v,
        Err(code) => return code,
    };

    let base_path = normalize_remote_path(&resolve_cli_remote_path(&initial_path, path));

    // Read crypt config
    let config_path = format!("{}/.aeroftp-crypt.json", base_path.trim_end_matches('/'));
    let config_data = match provider.download_to_bytes(&config_path).await {
        Ok(d) => d,
        Err(_) => {
            print_error(format, "No crypt overlay found. Run 'crypt init' first.", 5);
            return 5;
        }
    };
    let config_str = String::from_utf8_lossy(&config_data);
    let cfg = match overlay::parse_config(&config_str) {
        Ok(c) => c,
        Err(e) => {
            print_error(format, &format!("Invalid crypt config: {}", e), 5);
            return 5;
        }
    };

    let keyfile_digest = match reconcile_keyfile(&cfg, keyfile_digest) {
        Ok(kd) => kd,
        Err(e) => {
            print_error(format, &e, 6);
            return 6;
        }
    };
    let master_key = match overlay::derive_master_key_with_keyfile(&cfg, password, keyfile_digest) {
        Ok(k) => k,
        Err(e) => {
            print_error(format, &format!("Key derivation failed: {}", e), 6);
            return 6;
        }
    };
    if let Err(e) = overlay::verify_config_mac(&cfg, &master_key) {
        print_error(format, &format!("Crypt unlock failed: {}", e), 6);
        return 6;
    }

    if recursive {
        // Walk the encrypted tree (depth-bounded like the rclone-crypt overlay),
        // decrypting each path component, and print the decrypted relative paths.
        let mut stack: Vec<(String, String, usize)> = vec![(base_path.clone(), String::new(), 0)];
        let mut rows: Vec<(String, bool, u64)> = Vec::new(); // (rel_path, is_dir, size)
        let mut entries_seen = 0usize;
        let mut truncated = false;
        while let Some((abs_dir, rel_prefix, depth)) = stack.pop() {
            if depth >= CRYPT_OVERLAY_MAX_DEPTH {
                truncated = true;
                continue;
            }
            let entries = match provider.list(&abs_dir).await {
                Ok(e) => e,
                Err(e) => {
                    let code = provider_error_to_exit_code(&e);
                    print_error(format, &format!("List failed for {}: {}", abs_dir, e), code);
                    let _ = provider.disconnect().await;
                    return code;
                }
            };
            for entry in entries {
                if entry.name == ".aeroftp-crypt.json" {
                    continue;
                }
                // Skip foreign / undecryptable names rather than aborting the walk.
                let plain = match names::decrypt_filename(&master_key, &entry.name) {
                    Some(p) => p,
                    None => continue,
                };
                if entries_seen >= MAX_SCAN_ENTRIES {
                    truncated = true;
                    break;
                }
                entries_seen += 1;
                let rel = if rel_prefix.is_empty() {
                    plain
                } else {
                    format!("{}/{}", rel_prefix, plain)
                };
                if entry.is_dir {
                    rows.push((rel.clone(), true, 0));
                    // Listed, never walked (GAP-A02).
                    if entry.is_walkable_dir() {
                        stack.push((entry.path.clone(), rel, depth + 1));
                    }
                } else {
                    rows.push((rel, false, entry.size));
                }
            }
            if truncated {
                break;
            }
        }
        // Sort so a directory sorts immediately before its children.
        rows.sort_by(|a, b| a.0.cmp(&b.0));

        match format {
            OutputFormat::Text => {
                for (rel, is_dir, size) in &rows {
                    if *is_dir {
                        println!("{}/", rel);
                    } else {
                        println!("{:<48} {}", rel, format_size(*size));
                    }
                }
                if !cli.quiet {
                    eprintln!(
                        "\n{} entries (encrypted on remote){}",
                        rows.len(),
                        if truncated { ", listing truncated" } else { "" }
                    );
                }
            }
            OutputFormat::Json => {
                let items: Vec<serde_json::Value> = rows
                    .iter()
                    .map(|(rel, is_dir, size)| {
                        serde_json::json!({"path": rel, "is_dir": is_dir, "size": size})
                    })
                    .collect();
                print_json(&serde_json::json!({
                    "items": items,
                    "summary": {"count": rows.len(), "truncated": truncated}
                }));
            }
        }
        let _ = provider.disconnect().await;
        return 0;
    }

    // List directory and decrypt filenames
    let entries = match provider.list(&base_path).await {
        Ok(e) => e,
        Err(e) => {
            print_error(
                format,
                &format!("List failed: {}", e),
                provider_error_to_exit_code(&e),
            );
            return provider_error_to_exit_code(&e);
        }
    };

    let mut decrypted: Vec<(String, String, bool, u64)> = Vec::new(); // (decrypted_name, encrypted_name, is_dir, size)
    for entry in &entries {
        if entry.name == ".aeroftp-crypt.json" {
            continue;
        }
        let decrypted_name = names::decrypt_filename(&master_key, &entry.name)
            .unwrap_or_else(|| format!("[encrypted: {}]", entry.name));
        decrypted.push((decrypted_name, entry.name.clone(), entry.is_dir, entry.size));
    }

    match format {
        OutputFormat::Text => {
            for (name, _enc, is_dir, size) in &decrypted {
                if *is_dir {
                    println!("{}/ ", name);
                } else {
                    println!("{:<40} {}", name, format_size(*size));
                }
            }
            if !cli.quiet {
                eprintln!("\n{} items (encrypted on remote)", decrypted.len());
            }
        }
        OutputFormat::Json => {
            let items: Vec<serde_json::Value> = decrypted.iter().map(|(name, enc, is_dir, size)| {
                serde_json::json!({"name": name, "encrypted_name": enc, "is_dir": is_dir, "size": size})
            }).collect();
            print_json(&serde_json::json!({"items": items}));
        }
    }

    let _ = provider.disconnect().await;
    0
}

#[allow(clippy::too_many_arguments)]
async fn cmd_crypt_put(
    url: &str,
    local_file: &str,
    remote_path: &str,
    password: &str,
    keyfile_digest: Option<&[u8; 32]>,
    recursive: bool,
    cli: &Cli,
    format: OutputFormat,
) -> i32 {
    use ftp_client_gui_lib::aerocrypt::{names, overlay};
    let (mut provider, initial_path) = match create_and_connect(url, cli, format).await {
        Ok(v) => v,
        Err(code) => return code,
    };

    let base_path = normalize_remote_path(&resolve_cli_remote_path(&initial_path, remote_path));

    // Read crypt config
    let config_path = format!("{}/.aeroftp-crypt.json", base_path.trim_end_matches('/'));
    let config_data = match provider.download_to_bytes(&config_path).await {
        Ok(d) => d,
        Err(_) => {
            print_error(format, "No crypt overlay found. Run 'crypt init' first.", 5);
            return 5;
        }
    };
    let cfg = match overlay::parse_config(&String::from_utf8_lossy(&config_data)) {
        Ok(c) => c,
        Err(e) => {
            print_error(format, &e, 5);
            return 5;
        }
    };

    let keyfile_digest = match reconcile_keyfile(&cfg, keyfile_digest) {
        Ok(kd) => kd,
        Err(e) => {
            print_error(format, &e, 6);
            return 6;
        }
    };
    let master_key = match overlay::derive_master_key_with_keyfile(&cfg, password, keyfile_digest) {
        Ok(k) => k,
        Err(e) => {
            print_error(format, &format!("Key derivation failed: {}", e), 6);
            return 6;
        }
    };
    if let Err(e) = overlay::verify_config_mac(&cfg, &master_key) {
        print_error(format, &format!("Crypt unlock failed: {}", e), 6);
        return 6;
    }
    let start = Instant::now();

    // Directory upload: encrypt and mirror the whole local tree under the
    // overlay, creating encrypted-named subdirectories as we descend (the
    // folder is recreated as a named subdirectory of the overlay, like the
    // rclone-crypt overlay's upload_folder).
    let local_meta = match std::fs::symlink_metadata(local_file) {
        Ok(m) => m,
        Err(e) => {
            print_error(format, &format!("Cannot read '{}': {}", local_file, e), 2);
            let _ = provider.disconnect().await;
            return 2;
        }
    };
    if local_meta.is_dir() {
        if !recursive {
            print_error(
                format,
                &format!("'{}' is a directory; pass --recursive/-r", local_file),
                2,
            );
            let _ = provider.disconnect().await;
            return 2;
        }
        let quiet = cli.quiet || matches!(format, OutputFormat::Json);
        let root_name = match Path::new(local_file)
            .file_name()
            .map(|s| s.to_string_lossy().to_string())
            .filter(|s| !s.is_empty())
        {
            Some(n) => n,
            None => {
                print_error(format, "Cannot determine folder name to encrypt", 2);
                let _ = provider.disconnect().await;
                return 2;
            }
        };
        let root_enc = match names::encrypt_filename(&master_key, &root_name) {
            Ok(n) => n,
            Err(e) => {
                print_error(format, &format!("Filename encryption failed: {}", e), 99);
                let _ = provider.disconnect().await;
                return 99;
            }
        };
        let root_remote = format!("{}/{}", base_path.trim_end_matches('/'), root_enc);
        let _ = provider.mkdir(&root_remote).await; // best-effort: may already exist

        // (local dir, remote encrypted dir, decrypted rel path for display, depth)
        let mut stack: Vec<(std::path::PathBuf, String, String, usize)> = vec![(
            Path::new(local_file).to_path_buf(),
            root_remote,
            root_name,
            0,
        )];
        let mut files_uploaded = 0u64;
        let mut bytes_plain = 0u64;
        let mut entries_seen = 0usize;
        let mut errors: Vec<String> = Vec::new();
        let mut immutable_conflicts = 0u64;

        while let Some((ldir, rdir, rel, depth)) = stack.pop() {
            if depth >= CRYPT_OVERLAY_MAX_DEPTH {
                print_error(
                    format,
                    &format!(
                        "directory depth exceeds {} at '{}'",
                        CRYPT_OVERLAY_MAX_DEPTH, rel
                    ),
                    4,
                );
                let _ = provider.disconnect().await;
                return 4;
            }
            let rd = match std::fs::read_dir(&ldir) {
                Ok(r) => r,
                Err(e) => {
                    errors.push(format!("read {}: {}", ldir.display(), e));
                    continue;
                }
            };
            for ent in rd.flatten() {
                let meta = match ent.metadata() {
                    Ok(m) => m,
                    Err(_) => continue,
                };
                if meta.file_type().is_symlink() {
                    continue;
                }
                let name = ent.file_name().to_string_lossy().to_string();
                if name.is_empty() {
                    continue;
                }
                if entries_seen >= MAX_SCAN_ENTRIES {
                    print_error(
                        format,
                        &format!("tree exceeds the {} entry cap", MAX_SCAN_ENTRIES),
                        4,
                    );
                    let _ = provider.disconnect().await;
                    return 4;
                }
                entries_seen += 1;
                let enc = match names::encrypt_filename(&master_key, &name) {
                    Ok(n) => n,
                    Err(e) => {
                        errors.push(format!("encrypt name {}: {}", name, e));
                        continue;
                    }
                };
                let child_remote = format!("{}/{}", rdir, enc);
                let child_rel = format!("{}/{}", rel, name);
                if meta.is_dir() {
                    let _ = provider.mkdir(&child_remote).await; // best-effort
                    stack.push((ent.path(), child_remote, child_rel, depth + 1));
                } else if meta.is_file() {
                    if cli.immutable && provider.stat(&child_remote).await.is_ok() {
                        immutable_conflicts += 1;
                        errors.push(format!("{} already exists (--immutable)", child_rel));
                        continue;
                    }
                    let plaintext = match std::fs::read(ent.path()) {
                        Ok(d) => d,
                        Err(e) => {
                            errors.push(format!("read {}: {}", child_rel, e));
                            continue;
                        }
                    };
                    let ciphertext = match overlay::encrypt_data(&cfg, &master_key, &plaintext) {
                        Ok(c) => c,
                        Err(e) => {
                            errors.push(format!("encrypt {}: {}", child_rel, e));
                            continue;
                        }
                    };
                    let tmp = match tempfile::NamedTempFile::new() {
                        Ok(t) => t,
                        Err(e) => {
                            errors.push(format!("stage {}: {}", child_rel, e));
                            continue;
                        }
                    };
                    if let Err(e) = std::fs::write(tmp.path(), &ciphertext) {
                        errors.push(format!("stage {}: {}", child_rel, e));
                        continue;
                    }
                    match provider
                        .upload(&tmp.path().to_string_lossy(), &child_remote, None)
                        .await
                    {
                        Ok(()) => {
                            files_uploaded += 1;
                            bytes_plain += plaintext.len() as u64;
                            if !quiet {
                                println!("  {} -> {}", child_rel, enc);
                            }
                        }
                        Err(e) => errors.push(format!("upload {}: {}", child_rel, e)),
                    }
                }
            }
        }

        let elapsed = start.elapsed();
        let _ = provider.disconnect().await;
        match format {
            OutputFormat::Json => {
                print_json(&serde_json::json!({
                    "status": if errors.is_empty() { "ok" } else { "partial" },
                    "files": files_uploaded,
                    "bytes": bytes_plain,
                    "immutable_conflicts": immutable_conflicts,
                    "errors": errors,
                }));
            }
            OutputFormat::Text => {
                if !cli.quiet {
                    println!(
                        "\nEncrypted and uploaded {} files ({}) in {:.1}s",
                        files_uploaded,
                        format_size(bytes_plain),
                        elapsed.as_secs_f64()
                    );
                    for err in &errors {
                        eprintln!("  Error: {}", err);
                    }
                }
            }
        }
        return if errors.is_empty() {
            0
        } else if immutable_conflicts > 0 && errors.len() as u64 == immutable_conflicts {
            9
        } else {
            4
        };
    }

    // Read local file
    let plaintext = match std::fs::read(local_file) {
        Ok(d) => d,
        Err(e) => {
            print_error(format, &format!("Cannot read '{}': {}", local_file, e), 2);
            return 2;
        }
    };

    // Encrypt content
    let ciphertext = match overlay::encrypt_data(&cfg, &master_key, &plaintext) {
        Ok(c) => c,
        Err(e) => {
            print_error(format, &format!("Encryption failed: {}", e), 99);
            return 99;
        }
    };

    // Encrypt filename
    let filename = Path::new(local_file)
        .file_name()
        .map(|f| f.to_string_lossy().to_string())
        .unwrap_or_else(|| local_file.to_string());
    let encrypted_name = match names::encrypt_filename(&master_key, &filename) {
        Ok(n) => n,
        Err(e) => {
            print_error(format, &format!("Filename encryption failed: {}", e), 99);
            return 99;
        }
    };
    let remote_file = format!("{}/{}", base_path.trim_end_matches('/'), encrypted_name);

    if cli.immutable && provider.stat(&remote_file).await.is_ok() {
        print_error(
            format,
            &format!("{} already exists (--immutable)", filename),
            9,
        );
        let _ = provider.disconnect().await;
        return 9;
    }

    // Write encrypted data to tempfile, upload
    let tmp = match tempfile::NamedTempFile::new() {
        Ok(t) => t,
        Err(e) => {
            print_error(format, &format!("Failed to create temp file: {}", e), 11);
            return 11;
        }
    };
    if let Err(e) = std::fs::write(tmp.path(), &ciphertext) {
        print_error(
            format,
            &format!("Failed to stage encrypted file: {}", e),
            11,
        );
        return 11;
    }

    match provider
        .upload(&tmp.path().to_string_lossy(), &remote_file, None)
        .await
    {
        Ok(()) => {
            let elapsed = start.elapsed();
            if !cli.quiet {
                println!(
                    "{} → {} ({} → {}, {:.1}s)",
                    filename,
                    encrypted_name,
                    format_size(plaintext.len() as u64),
                    format_size(ciphertext.len() as u64),
                    elapsed.as_secs_f64()
                );
            }
            0
        }
        Err(e) => {
            print_error(format, &format!("Upload failed: {}", e), 4);
            4
        }
    }
}

#[allow(clippy::too_many_arguments)]
async fn cmd_crypt_get(
    url: &str,
    file_name: &str,
    path: &str,
    local_dest: &str,
    password: &str,
    keyfile_digest: Option<&[u8; 32]>,
    recursive: bool,
    cli: &Cli,
    format: OutputFormat,
) -> i32 {
    use ftp_client_gui_lib::aerocrypt::{names, overlay};
    let (mut provider, initial_path) = match create_and_connect(url, cli, format).await {
        Ok(v) => v,
        Err(code) => return code,
    };

    let base_path = normalize_remote_path(&resolve_cli_remote_path(&initial_path, path));

    // Read crypt config
    let config_path = format!("{}/.aeroftp-crypt.json", base_path.trim_end_matches('/'));
    let config_data = match provider.download_to_bytes(&config_path).await {
        Ok(d) => d,
        Err(_) => {
            print_error(format, "No crypt overlay found.", 5);
            return 5;
        }
    };
    let cfg = match overlay::parse_config(&String::from_utf8_lossy(&config_data)) {
        Ok(c) => c,
        Err(e) => {
            print_error(format, &e, 5);
            return 5;
        }
    };

    let keyfile_digest = match reconcile_keyfile(&cfg, keyfile_digest) {
        Ok(kd) => kd,
        Err(e) => {
            print_error(format, &e, 6);
            return 6;
        }
    };
    let master_key = match overlay::derive_master_key_with_keyfile(&cfg, password, keyfile_digest) {
        Ok(k) => k,
        Err(e) => {
            print_error(format, &format!("Key derivation failed: {}", e), 6);
            return 6;
        }
    };
    if let Err(e) = overlay::verify_config_mac(&cfg, &master_key) {
        print_error(format, &format!("Crypt unlock failed: {}", e), 6);
        return 6;
    }
    let start = Instant::now();

    if recursive {
        // Download an encrypted subdirectory tree, decrypting names and content
        // and rebuilding the plaintext tree locally (rclone-crypt overlay
        // download_folder parity, depth-bounded). The named folder is recreated
        // under the local destination directory.
        let quiet = cli.quiet || matches!(format, OutputFormat::Json);
        let trimmed = file_name.trim_matches('/');
        let enc_rel = match crypt_encrypt_rel_path(&master_key, trimmed) {
            Ok(r) => r,
            Err(e) => {
                print_error(format, &e, 99);
                let _ = provider.disconnect().await;
                return 99;
            }
        };
        let remote_root = if enc_rel.is_empty() {
            base_path.clone()
        } else {
            format!("{}/{}", base_path.trim_end_matches('/'), enc_rel)
        };
        let basename = trimmed
            .rsplit('/')
            .find(|s| !s.is_empty())
            .map(crypt_sanitize_component);
        let local_root: std::path::PathBuf = match (&basename, local_dest) {
            (Some(b), d) if d.is_empty() || d == "." => std::path::PathBuf::from(b),
            (Some(b), d) => Path::new(d).join(b),
            (None, d) if d.is_empty() || d == "." => std::path::PathBuf::from("."),
            (None, d) => std::path::PathBuf::from(d),
        };

        let mut stack: Vec<(String, std::path::PathBuf, usize)> =
            vec![(remote_root, local_root.clone(), 0)];
        let mut files_done = 0u64;
        let mut bytes_plain = 0u64;
        let mut entries_seen = 0usize;
        let mut errors: Vec<String> = Vec::new();
        let mut first = true;

        while let Some((rdir, ldir, depth)) = stack.pop() {
            if depth >= CRYPT_OVERLAY_MAX_DEPTH {
                errors.push(format!(
                    "directory depth exceeds {}",
                    CRYPT_OVERLAY_MAX_DEPTH
                ));
                continue;
            }
            if let Err(e) = std::fs::create_dir_all(&ldir) {
                errors.push(format!("create {}: {}", ldir.display(), e));
                continue;
            }
            let entries = match provider.list(&rdir).await {
                Ok(e) => e,
                Err(e) => {
                    // A failure on the root path is fatal (wrong name / not a
                    // directory); deeper failures are collected and the walk
                    // continues over the rest of the tree.
                    if first {
                        let code = provider_error_to_exit_code(&e);
                        print_error(format, &format!("List failed for {}: {}", rdir, e), code);
                        let _ = provider.disconnect().await;
                        return code;
                    }
                    errors.push(format!("list {}: {}", rdir, e));
                    continue;
                }
            };
            first = false;
            for entry in entries {
                if entry.name == ".aeroftp-crypt.json" {
                    continue;
                }
                let plain = match names::decrypt_filename(&master_key, &entry.name) {
                    Some(p) => p,
                    None => continue,
                };
                if entries_seen >= MAX_SCAN_ENTRIES {
                    errors.push(format!("tree exceeds the {} entry cap", MAX_SCAN_ENTRIES));
                    break;
                }
                entries_seen += 1;
                let ltarget = ldir.join(crypt_sanitize_component(&plain));
                if entry.is_dir {
                    // Never follow a symlink-to-dir into the local tree: the
                    // target's plaintext would be written twice (GAP-A02).
                    if entry.is_walkable_dir() {
                        stack.push((entry.path.clone(), ltarget, depth + 1));
                    }
                    continue;
                }
                let ciphertext = match provider.download_to_bytes(&entry.path).await {
                    Ok(d) => d,
                    Err(e) => {
                        errors.push(format!("download {}: {}", plain, e));
                        continue;
                    }
                };
                let plaintext = match overlay::decrypt_data(&master_key, &ciphertext) {
                    Ok(p) => p,
                    Err(e) => {
                        errors.push(format!("decrypt {}: {}", plain, e));
                        continue;
                    }
                };
                if let Err(e) = std::fs::write(&ltarget, &plaintext) {
                    errors.push(format!("write {}: {}", ltarget.display(), e));
                    continue;
                }
                files_done += 1;
                bytes_plain += plaintext.len() as u64;
                if !quiet {
                    println!(
                        "  {} ({})",
                        ltarget.display(),
                        format_size(plaintext.len() as u64)
                    );
                }
            }
        }

        let elapsed = start.elapsed();
        let _ = provider.disconnect().await;
        match format {
            OutputFormat::Json => {
                print_json(&serde_json::json!({
                    "status": if errors.is_empty() { "ok" } else { "partial" },
                    "files": files_done,
                    "bytes": bytes_plain,
                    "dest": local_root.to_string_lossy(),
                    "errors": errors,
                }));
            }
            OutputFormat::Text => {
                if !cli.quiet {
                    println!(
                        "\nDecrypted and downloaded {} files ({}) into {} in {:.1}s",
                        files_done,
                        format_size(bytes_plain),
                        local_root.display(),
                        elapsed.as_secs_f64()
                    );
                    for err in &errors {
                        eprintln!("  Error: {}", err);
                    }
                }
            }
        }
        return if errors.is_empty() { 0 } else { 4 };
    }

    // Encrypt the decrypted name (component by component, so nested names from a
    // folder tree resolve too) to find the remote file.
    let enc = match crypt_encrypt_rel_path(&master_key, file_name) {
        Ok(n) => n,
        Err(e) => {
            print_error(format, &format!("Filename encryption failed: {}", e), 99);
            return 99;
        }
    };
    let remote_file = format!("{}/{}", base_path.trim_end_matches('/'), enc);

    // Download
    let ciphertext = match provider.download_to_bytes(&remote_file).await {
        Ok(d) => d,
        Err(e) => {
            print_error(
                format,
                &format!("Download failed: {}", e),
                provider_error_to_exit_code(&e),
            );
            return provider_error_to_exit_code(&e);
        }
    };

    // Decrypt
    let plaintext = match overlay::decrypt_data(&master_key, &ciphertext) {
        Ok(p) => p,
        Err(e) => {
            print_error(format, &format!("Decryption failed: {}", e), 99);
            return 99;
        }
    };

    // Write to local file
    let dest = if local_dest.is_empty() || local_dest == "." {
        // Use decrypted original filename
        let enc_basename = remote_file.rsplit('/').next().unwrap_or("decrypted");
        names::decrypt_filename(&master_key, enc_basename)
            .unwrap_or_else(|| "decrypted".to_string())
    } else {
        local_dest.to_string()
    };

    if let Err(e) = std::fs::write(&dest, &plaintext) {
        print_error(format, &format!("Cannot write '{}': {}", dest, e), 4);
        return 4;
    }

    let elapsed = start.elapsed();
    if !cli.quiet {
        println!(
            "{} → {} ({} → {}, {:.1}s)",
            remote_file.rsplit('/').next().unwrap_or("?"),
            dest,
            format_size(ciphertext.len() as u64),
            format_size(plaintext.len() as u64),
            elapsed.as_secs_f64()
        );
    }

    let _ = provider.disconnect().await;
    0
}

#[allow(clippy::too_many_arguments)]
async fn cmd_rclone_crypt_put(
    url: &str,
    local_file: &str,
    remote_path: &str,
    password: &str,
    salt: &str,
    filename_encryption: RcloneFilenameEncryption,
    dir_iv_base64: Option<&str>,
    remote_name: Option<&str>,
    suffix: Option<&str>,
    cli: &Cli,
    format: OutputFormat,
) -> i32 {
    let (mut provider, initial_path) = match create_and_connect(url, cli, format).await {
        Ok(v) => v,
        Err(code) => return code,
    };

    let base_path = normalize_remote_path(&resolve_cli_remote_path(&initial_path, remote_path));

    let (name_key, data_key, name_tweak) =
        match ftp_client_gui_lib::rclone_crypt::derive_keys_with_tweak(password, salt) {
            Ok(keys) => keys,
            Err(e) => {
                print_error(format, &format!("rclone key derivation failed: {}", e), 5);
                return 5;
            }
        };

    let plaintext = match std::fs::read(local_file) {
        Ok(d) => d,
        Err(e) => {
            print_error(format, &format!("Cannot read '{}': {}", local_file, e), 2);
            return 2;
        }
    };

    let encrypted =
        match ftp_client_gui_lib::rclone_crypt::encrypt_file_content(&plaintext, &data_key) {
            Ok(d) => d,
            Err(e) => {
                print_error(
                    format,
                    &format!("rclone content encryption failed: {}", e),
                    99,
                );
                return 99;
            }
        };

    let plain_name = remote_name
        .map(|s| s.to_string())
        .or_else(|| {
            Path::new(local_file)
                .file_name()
                .map(|f| f.to_string_lossy().to_string())
        })
        .unwrap_or_else(|| local_file.to_string());

    let encrypted_name = match filename_encryption {
        RcloneFilenameEncryption::Off => {
            // rclone tags name-encryption-off objects with a suffix (default
            // ".bin") so it recognizes them as encrypted; without it rclone
            // skips the file ("does not match suffix"). Append it for drop-in
            // interop; "none"/empty disables it (rclone `suffix = none`).
            let suf = ftp_client_gui_lib::rclone_crypt::resolve_off_suffix(suffix);
            if suf.is_empty() {
                plain_name.clone()
            } else {
                format!("{}{}", plain_name, suf)
            }
        }
        RcloneFilenameEncryption::Standard => {
            if dir_iv_base64.is_some() && cli.verbose > 0 {
                eprintln!("Note: --dir-iv-base64 is ignored for rclone-compatible standard names; the EME tweak is derived from the password.");
            }
            match ftp_client_gui_lib::rclone_crypt::encrypt_name(
                &name_key,
                &name_tweak,
                &plain_name,
            ) {
                Ok(name) => name,
                Err(e) => {
                    print_error(
                        format,
                        &format!("rclone filename encryption failed: {}", e),
                        99,
                    );
                    return 99;
                }
            }
        }
        RcloneFilenameEncryption::Obfuscate => {
            if dir_iv_base64.is_some() && cli.verbose > 0 {
                eprintln!("Note: --dir-iv-base64 is ignored for rclone-compatible obfuscated names; the tweak is derived from the password.");
            }
            match ftp_client_gui_lib::rclone_crypt::obfuscate_name(&name_tweak, &plain_name) {
                Ok(name) => name,
                Err(e) => {
                    print_error(
                        format,
                        &format!("rclone filename obfuscation failed: {}", e),
                        99,
                    );
                    return 99;
                }
            }
        }
    };

    let remote_file = format!("{}/{}", base_path.trim_end_matches('/'), encrypted_name);
    let start = Instant::now();

    if cli.immutable && provider.stat(&remote_file).await.is_ok() {
        print_error(
            format,
            &format!("{} already exists (--immutable)", plain_name),
            9,
        );
        let _ = provider.disconnect().await;
        return 9;
    }

    let tmp = match NamedTempFile::new() {
        Ok(v) => v,
        Err(e) => {
            print_error(format, &format!("Cannot create temporary file: {}", e), 11);
            return 11;
        }
    };
    if let Err(e) = std::fs::write(tmp.path(), &encrypted) {
        print_error(
            format,
            &format!("Cannot write encrypted temp file: {}", e),
            11,
        );
        return 11;
    }

    let upload_result = provider
        .upload(&tmp.path().to_string_lossy(), &remote_file, None)
        .await;
    let _ = provider.disconnect().await;

    match upload_result {
        Ok(()) => {
            if matches!(format, OutputFormat::Json) {
                print_json(&serde_json::json!({
                    "status": "ok",
                    "local": local_file,
                    "remote": remote_file,
                    "filename": {
                        "plaintext": plain_name,
                        "encrypted": encrypted_name,
                        "mode": match filename_encryption {
                            RcloneFilenameEncryption::Standard => "standard",
                            RcloneFilenameEncryption::Obfuscate => "obfuscate",
                            RcloneFilenameEncryption::Off => "off",
                        }
                    },
                    "size": {
                        "plaintext": plaintext.len(),
                        "encrypted": encrypted.len(),
                    },
                    "elapsed_ms": start.elapsed().as_millis()
                }));
            } else if !cli.quiet {
                println!(
                    "{} -> {} ({}, {:.1}s)",
                    plain_name,
                    remote_file,
                    format_size(plaintext.len() as u64),
                    start.elapsed().as_secs_f64()
                );
                println!(
                    "filename mode: {}",
                    match filename_encryption {
                        RcloneFilenameEncryption::Standard => "standard",
                        RcloneFilenameEncryption::Obfuscate => "obfuscate",
                        RcloneFilenameEncryption::Off => "off",
                    }
                );
                println!("encrypted name: {}", encrypted_name);
            }
            0
        }
        Err(e) => {
            let code = provider_error_to_exit_code(&e);
            print_error(format, &format!("Upload failed: {}", e), code);
            code
        }
    }
}

async fn cmd_put_glob(
    url: &str,
    local_pattern: &str,
    remote_base: Option<&str>,
    cli: &Cli,
    format: OutputFormat,
    cancelled: Arc<AtomicBool>,
) -> i32 {
    let raw_remote_base = remote_base.unwrap_or("/");

    // Resolve remote_base against profile's initial_path
    let (mut probe_provider, initial_path) = match create_and_connect(url, cli, format).await {
        Ok(v) => v,
        Err(code) => return code,
    };
    let glob_provider_type = probe_provider.provider_type();
    let _ = probe_provider.disconnect().await;
    let remote_base = resolve_cli_remote_path(&initial_path, raw_remote_base);
    let remote_base = remote_base.as_str();

    // Split pattern into directory + glob
    let pattern_path = Path::new(local_pattern);
    let (dir, glob_pattern) = if let Some(parent) = pattern_path.parent() {
        let parent_str = parent.to_string_lossy();
        let parent_dir = if parent_str.is_empty() {
            "."
        } else {
            &*parent_str
        };
        (
            parent_dir.to_string(),
            pattern_path
                .file_name()
                .map(|f| f.to_string_lossy().to_string())
                .unwrap_or_default(),
        )
    } else {
        (".".to_string(), local_pattern.to_string())
    };

    let matcher = match globset::Glob::new(&glob_pattern) {
        Ok(g) => g.compile_matcher(),
        Err(e) => {
            print_error(format, &format!("Invalid glob pattern: {}", e), 5);
            return 5;
        }
    };

    // Read local directory and match
    let read_dir = match std::fs::read_dir(&dir) {
        Ok(rd) => rd,
        Err(e) => {
            print_error(
                format,
                &format!("Cannot read directory '{}': {}", dir, e),
                2,
            );
            return 2;
        }
    };

    let mut matched: Vec<(String, String, u64)> = Vec::new(); // (local_path, filename, size)
    for entry in read_dir.flatten() {
        let meta = match entry.metadata() {
            Ok(m) => m,
            Err(_) => continue,
        };
        if !meta.is_file() {
            continue;
        }
        let name = entry.file_name().to_string_lossy().to_string();
        if matcher.is_match(&name) {
            matched.push((entry.path().to_string_lossy().to_string(), name, meta.len()));
        }
    }

    if matched.is_empty() {
        match format {
            OutputFormat::Text => eprintln!("No local files matching glob '{}'", glob_pattern),
            OutputFormat::Json => print_error(
                format,
                &format!("No local files matching glob '{}'", glob_pattern),
                2,
            ),
        }
        return 2;
    }

    matched.sort_by(|a, b| a.1.cmp(&b.1));

    let start = Instant::now();
    let total = matched.len();
    let total_bytes: u64 = matched.iter().map(|(_, _, size)| *size).sum();
    let aggregate = Arc::new(AtomicU64::new(0));
    let overall_pb = if !cli.quiet && matches!(format, OutputFormat::Text) && total_bytes > 0 {
        Some(create_overall_progress_bar(total, total_bytes))
    } else {
        None
    };

    let files: Vec<(String, String, u64)> = matched
        .into_iter()
        .map(|(local_path, filename, size)| {
            let remote_path = format!("{}/{}", remote_base.trim_end_matches('/'), filename);
            (local_path, remote_path, size)
        })
        .collect();

    // Pre-flight: reject the batch if any matched file's target name contains a
    // character this provider's backend forbids (mirrors single-file `put`).
    for (_, remote_path, _) in &files {
        if let Err(e) =
            ftp_client_gui_lib::restricted_chars::validate_path(glob_provider_type, remote_path)
        {
            let code = provider_error_to_exit_code(&e);
            print_error(format, &format!("put failed: {}", e), code);
            return code;
        }
    }

    let mut uploaded: u32 = 0;
    let mut errors: Vec<String> = Vec::new();

    // PD-CLI-CONV-C: converge the glob upload batch on the SAME shared
    // provider executor + orchestrator (PD-CLI-CONV-B), sink-agnostic.
    // The probe connection was only used to resolve `initial_path`; the
    // shared engine needs a live base whose connection spec backs the
    // clone-pool workers, so a base provider is (re)connected here. The
    // single remote parent (`remote_base`) is pre-created idempotently
    // because the shared executor does not mkdir. `--immutable` and
    // non-pool-backed providers (FTP, single-conn APIs) stay on the
    // legacy independent-connection batch: honest fallback, no overclaim.
    let use_legacy = if cli.immutable {
        if !cli.quiet {
            eprintln!(
                "Note: --immutable uses the single-stream upload path \
                 (the pooled uploader has no remote-existence check)"
            );
        }
        true
    } else {
        match create_and_connect(url, cli, format).await {
            Ok((mut provider, _)) => {
                let _ = provider.mkdir(remote_base).await;
                match run_shared_provider_upload_batch(
                    provider,
                    &files,
                    cli,
                    overall_pb.clone(),
                    cancelled.clone(),
                )
                .await
                {
                    Ok(outcome) => {
                        uploaded = outcome.uploaded;
                        errors = outcome.errors;
                        false
                    }
                    Err(mut base) => {
                        let _ = base.disconnect().await;
                        true
                    }
                }
            }
            Err(_) => true,
        }
    };

    if use_legacy {
        let results = futures_util::stream::iter(files.into_iter().map(
            |(local_path, remote_path, _size)| {
                let cancelled = cancelled.clone();
                let aggregate = aggregate.clone();
                let overall_pb = overall_pb.clone();
                async move {
                    if cancelled.load(Ordering::Relaxed) {
                        return Err("Cancelled by user".to_string());
                    }
                    upload_transfer_task(
                        url,
                        local_path.clone(),
                        remote_path,
                        cli,
                        format,
                        Some(aggregate),
                        overall_pb,
                        resolve_max_transfer(cli),
                    )
                    .await
                    .map(|_| local_path)
                }
            },
        ))
        .buffer_unordered(effective_parallel_workers(cli))
        .collect::<Vec<_>>()
        .await;

        for result in results {
            match result {
                Ok(_) => uploaded += 1,
                Err(err) => errors.push(err),
            }
        }
    }

    if let Some(pb) = overall_pb {
        pb.finish_and_clear();
    }

    let elapsed = start.elapsed();

    match format {
        OutputFormat::Text => {
            if !cli.quiet {
                println!(
                    "\n{}/{} files uploaded in {:.1}s",
                    uploaded,
                    total,
                    elapsed.as_secs_f64()
                );
            }
        }
        OutputFormat::Json => {
            print_json(&CliSyncResult {
                status: if errors.is_empty() { "ok" } else { "partial" },
                uploaded,
                downloaded: 0,
                deleted: 0,
                skipped: 0,
                ec_generated: None,
                ec_skipped_too_large: None,
                ec_skipped_low_benefit: None,
                ec_generate_failed: None,
                ec_sidecar_deleted: None,
                ec_sidecar_delete_failed: None,
                errors,
                elapsed_secs: elapsed.as_secs_f64(),
                plan: Vec::new(),
            });
        }
    }
    if uploaded == total as u32 {
        0
    } else if session_transfer_exceeded(resolve_max_transfer(cli)) {
        // Intentional --max-transfer cap (honest note already emitted),
        // not a transfer failure: the dedicated exit code, consistent
        // with the legacy path.
        8
    } else {
        4
    }
}

// ---------------------------------------------------------------------------
// sync --watch: continuous sync with filesystem watcher
// ---------------------------------------------------------------------------

/// Returns true if a path should be excluded from watcher events (temp files, VCS dirs, OS metadata).
fn should_exclude_watch_path(path: &std::path::Path) -> bool {
    let name = match path.file_name().and_then(|n| n.to_str()) {
        Some(n) => n,
        None => return false,
    };
    let ext = path.extension().and_then(|e| e.to_str()).unwrap_or("");
    // OS metadata
    if matches!(
        name,
        ".DS_Store" | "Thumbs.db" | "desktop.ini" | ".directory"
    ) {
        return true;
    }
    // VCS / heavy dirs (will never be a leaf event worth syncing)
    if matches!(
        name,
        ".git" | ".svn" | ".hg" | "node_modules" | "__pycache__"
    ) {
        return true;
    }
    // Temp/editor artifacts by extension
    if matches!(
        ext,
        "swp" | "swo" | "swx" | "tmp" | "temp" | "bak" | "crdownload" | "part"
    ) {
        return true;
    }
    // Temp artifacts by name pattern
    if name.starts_with('~')
        || name.starts_with(".#")
        || name.ends_with('~')
        || name.ends_with(".aerotmp")
    {
        return true;
    }
    // Vim swap: .filename.swp (already caught by ext, but be safe for .swpx etc.)
    if name.starts_with('.') && name.ends_with(".swp") {
        return true;
    }
    false
}

/// Build a local entry list incrementally: refresh metadata only for watcher-reported paths,
/// and merge with the previous full snapshot for everything else.
/// This avoids a full walkdir when only a few files changed.
fn incremental_local_scan(
    base: &std::path::Path,
    changed_paths: &[std::path::PathBuf],
    previous_entries: &std::collections::HashMap<String, (u64, Option<String>)>,
    exclude_matchers: &[globset::GlobMatcher],
) -> Vec<(String, u64, Option<String>)> {
    let mut result: std::collections::HashMap<String, (u64, Option<String>)> =
        previous_entries.clone();

    for changed in changed_paths {
        // Compute relative path
        let relative = match changed.strip_prefix(base) {
            Ok(r) => r.to_string_lossy().replace('\\', "/"),
            Err(_) => continue,
        };
        if relative.is_empty() || relative == BISYNC_SNAPSHOT_FILE {
            continue;
        }
        // Check excludes
        let fname = changed.file_name().and_then(|n| n.to_str()).unwrap_or("");
        if exclude_matchers
            .iter()
            .any(|m| m.is_match(&relative) || m.is_match(fname))
        {
            result.remove(&relative);
            continue;
        }
        // Read current metadata: if file was deleted, remove from snapshot
        match std::fs::metadata(changed) {
            Ok(meta) if meta.is_file() => {
                let size = meta.len();
                let mtime = meta.modified().ok().map(|t| {
                    let dt: chrono::DateTime<chrono::Utc> = t.into();
                    dt.format("%Y-%m-%dT%H:%M:%S").to_string()
                });
                result.insert(relative, (size, mtime));
            }
            _ => {
                // File deleted or not a regular file
                result.remove(&relative);
            }
        }
    }

    result
        .into_iter()
        .map(|(path, (size, mtime))| (path, size, mtime))
        .collect()
}

/// Start a filesystem watcher and return a boxed handle (dropped to stop).
/// Filtered, debounced paths are sent on `tx`.
fn start_watch_watcher(
    watch_path: &std::path::Path,
    mode: &str,
    debounce_ms: u64,
    tx: std::sync::mpsc::Sender<Vec<std::path::PathBuf>>,
) -> Result<Box<dyn std::any::Any + Send>, String> {
    let debounce_dur = std::time::Duration::from_millis(debounce_ms);
    match mode {
        "poll" => {
            use notify::PollWatcher;
            let config =
                notify::Config::default().with_poll_interval(std::time::Duration::from_secs(5));
            let watcher = PollWatcher::new(
                move |res: Result<notify::Event, notify::Error>| {
                    if let Ok(event) = res {
                        let paths: Vec<_> = event
                            .paths
                            .into_iter()
                            .filter(|p| !should_exclude_watch_path(p))
                            .collect();
                        if !paths.is_empty() {
                            let _ = tx.send(paths);
                        }
                    }
                },
                config,
            )
            .map_err(|e| format!("Failed to create poll watcher: {}", e))?;
            // PollWatcher with notify 8 doesn't need explicit watch call for config,
            // but we do need to add the path:
            let mut w = watcher;
            notify::Watcher::watch(&mut w, watch_path, notify::RecursiveMode::Recursive)
                .map_err(|e| format!("Failed to watch path: {}", e))?;
            Ok(Box::new(w))
        }
        _ => {
            // native or auto: use debounced watcher
            use notify_debouncer_full::new_debouncer;

            let (dtx, drx) = std::sync::mpsc::channel();
            let mut debouncer = new_debouncer(debounce_dur, None, dtx)
                .map_err(|e| format!("Failed to create watcher: {}", e))?;
            debouncer
                .watch(watch_path, notify::RecursiveMode::Recursive)
                .map_err(|e| format!("Failed to watch path: {}", e))?;

            // Spawn thread to drain debouncer events and forward filtered paths
            std::thread::spawn(move || {
                while let Ok(result) = drx.recv() {
                    if let Ok(events) = result {
                        let mut all_paths = Vec::new();
                        for event in &events {
                            for p in &event.paths {
                                if !should_exclude_watch_path(p) && !all_paths.contains(p) {
                                    all_paths.push(p.clone());
                                }
                            }
                        }
                        if !all_paths.is_empty() && tx.send(all_paths).is_err() {
                            break; // receiver dropped
                        }
                    }
                }
            });

            Ok(Box::new(debouncer))
        }
    }
}

#[allow(clippy::too_many_arguments)]
async fn cmd_sync_watch(
    url: &str,
    local: &str,
    remote: &str,
    direction: &str,
    dry_run: bool,
    delete: bool,
    exclude: &[String],
    error_correction_pct: Option<u32>,
    error_correction_max_overhead_pct: u32,
    track_renames: bool,
    max_delete: Option<&str>,
    backup_dir: Option<&str>,
    backup_suffix: &str,
    suffix_keep_extension: bool,
    compare_dest: Option<&str>,
    copy_dest: Option<&str>,
    from_reconcile: Option<&str>,
    conflict_mode: &str,
    skip_matching: bool,
    resync: bool,
    watch_mode: &str,
    watch_debounce_ms: u64,
    watch_cooldown: u64,
    watch_rescan: u64,
    watch_no_initial: bool,
    cli: &Cli,
    format: OutputFormat,
    cancelled: Arc<AtomicBool>,
) -> i32 {
    let quiet = cli.quiet || matches!(format, OutputFormat::Json);
    if from_reconcile.is_some() {
        print_error(
            format,
            "--from-reconcile cannot be combined with --watch",
            5,
        );
        return 5;
    }
    let local_path = std::path::Path::new(local);
    if !local_path.is_dir() {
        if matches!(format, OutputFormat::Json) {
            print_json(
                &serde_json::json!({"error": "Local path is not a directory", "path": local}),
            );
        } else {
            eprintln!("Error: local path is not a directory: {}", local);
        }
        return 5;
    }

    // Start filesystem watcher
    let (std_tx, std_rx) = std::sync::mpsc::channel::<Vec<std::path::PathBuf>>();
    let _watcher_handle =
        match start_watch_watcher(local_path, watch_mode, watch_debounce_ms, std_tx) {
            Ok(h) => h,
            Err(e) => {
                if matches!(format, OutputFormat::Json) {
                    print_json(
                        &serde_json::json!({"error": format!("Failed to start watcher: {}", e)}),
                    );
                } else {
                    eprintln!("Error: failed to start filesystem watcher: {}", e);
                }
                return 5;
            }
        };

    // Bridge std mpsc to tokio mpsc so we can use tokio::select!
    let (async_tx, mut async_rx) = tokio::sync::mpsc::channel::<Vec<std::path::PathBuf>>(64);
    std::thread::spawn(move || {
        while let Ok(paths) = std_rx.recv() {
            if async_tx.blocking_send(paths).is_err() {
                break;
            }
        }
    });

    if !quiet {
        eprintln!(
            "Watching {} -> {} (direction: {}, cooldown: {}s, rescan: {}s)",
            local,
            if url == "_" { "(profile)" } else { url },
            direction,
            watch_cooldown,
            watch_rescan,
        );
    }

    let syncing = Arc::new(AtomicBool::new(false));
    let mut cycle_count: u64 = 0;
    let cooldown_dur = std::time::Duration::from_secs(watch_cooldown);
    let rescan_dur = if watch_rescan > 0 {
        std::time::Duration::from_secs(watch_rescan)
    } else {
        std::time::Duration::from_secs(86400) // effectively disabled
    };
    let mut shutdown_tick = tokio::time::interval(std::time::Duration::from_millis(200));
    shutdown_tick.set_missed_tick_behavior(tokio::time::MissedTickBehavior::Delay);
    shutdown_tick.tick().await;
    let mut rescan_tick = tokio::time::interval(rescan_dur);
    rescan_tick.set_missed_tick_behavior(tokio::time::MissedTickBehavior::Delay);
    rescan_tick.tick().await;
    let mut last_sync_completed = std::time::Instant::now()
        .checked_sub(std::time::Duration::from_secs(watch_cooldown + 1))
        .unwrap_or_else(std::time::Instant::now);

    // Helper macro to run one sync cycle.
    // Usage: run_sync_cycle!("trigger")           : full walkdir scan (None)
    //        run_sync_cycle!("trigger", entries)   : incremental (Some(entries))
    macro_rules! run_sync_cycle {
        ($trigger:expr) => {
            run_sync_cycle!($trigger, None)
        };
        ($trigger:expr, $precomputed:expr) => {{
            cycle_count += 1;
            let cycle = cycle_count;
            let trigger_label: &str = $trigger;
            syncing.store(true, Ordering::SeqCst);
            let cycle_start = std::time::Instant::now();

            let stats: SyncCycleStats = cmd_sync(
                url,
                local,
                remote,
                direction,
                dry_run,
                delete,
                exclude,
                error_correction_pct,
                error_correction_max_overhead_pct,
                track_renames,
                max_delete,
                backup_dir,
                backup_suffix,
                suffix_keep_extension,
                compare_dest,
                copy_dest,
                from_reconcile,
                conflict_mode,
                skip_matching,
                resync && cycle == 1, // resync only on first cycle
                cli,
                format,
                cancelled.clone(),
                $precomputed,
                false, // Z.1.2: watch loops keep classic path until --delta plumbing is wired through watch flags
            )
            .await;

            syncing.store(false, Ordering::SeqCst);
            last_sync_completed = std::time::Instant::now();
            let elapsed = cycle_start.elapsed();
            let total_changes = stats.uploaded + stats.downloaded + stats.deleted;

            // Emit cycle status with detailed stats
            if matches!(format, OutputFormat::Json) {
                let ts = chrono::Utc::now().to_rfc3339_opts(chrono::SecondsFormat::Secs, true);
                let mut payload = serde_json::json!({
                    "cycle": cycle,
                    "trigger": trigger_label,
                    "exit_code": stats.exit_code,
                    "uploaded": stats.uploaded,
                    "downloaded": stats.downloaded,
                    "deleted": stats.deleted,
                    "skipped": stats.skipped,
                    "errors": stats.error_count,
                    "elapsed_secs": (elapsed.as_millis() as f64) / 1000.0,
                    "timestamp": ts,
                });
                if error_correction_pct.is_some() {
                    payload["ec_generated"] = serde_json::json!(stats.ec_generated);
                    payload["ec_skipped_too_large"] =
                        serde_json::json!(stats.ec_skipped_too_large);
                    payload["ec_skipped_low_benefit"] =
                        serde_json::json!(stats.ec_skipped_low_benefit);
                    payload["ec_generate_failed"] = serde_json::json!(stats.ec_generate_failed);
                    payload["ec_sidecar_deleted"] =
                        serde_json::json!(stats.ec_sidecar_deleted);
                    payload["ec_sidecar_delete_failed"] =
                        serde_json::json!(stats.ec_sidecar_delete_failed);
                }
                print_json(&payload);
            } else if !quiet {
                let ts = chrono::Local::now().format("%H:%M:%S");
                if total_changes == 0 && stats.error_count == 0 {
                    eprintln!(
                        "[{}] Sync #{} ({}) -- no changes ({}s)",
                        ts, cycle, trigger_label,
                        format!("{:.1}", elapsed.as_secs_f64()),
                    );
                } else {
                    eprintln!(
                        "[{}] Sync #{} ({}) -- {} up, {} down, {} del{} ({}s)",
                        ts, cycle, trigger_label,
                        stats.uploaded, stats.downloaded, stats.deleted,
                        if stats.error_count > 0 {
                            format!(", {} errors", stats.error_count)
                        } else {
                            String::new()
                        },
                        format!("{:.1}", elapsed.as_secs_f64()),
                    );
                }
            }

            // Drain any watcher events accumulated during the sync
            while async_rx.try_recv().is_ok() {}

            stats.exit_code
        }};
    }

    // Pre-compile exclude matchers for incremental scan
    let effective_exclude =
        sync_effective_exclude_patterns(exclude, error_correction_pct.is_some());
    let exclude_matchers: Vec<globset::GlobMatcher> = effective_exclude
        .iter()
        .filter_map(|pat| globset::Glob::new(pat).ok().map(|g| g.compile_matcher()))
        .collect();

    // Incremental scan is only safe when:
    // - direction is not download-only (local scan is irrelevant)
    // - track_renames is off (needs full file set for hash matching)
    let use_incremental = direction != "download" && !track_renames;

    // Local snapshot: populated after each full scan for incremental merging
    let mut local_snapshot: std::collections::HashMap<String, (u64, Option<String>)> =
        std::collections::HashMap::new();

    // Helper: build snapshot from a full local walkdir scan
    let build_snapshot =
        |local_dir: &str| -> std::collections::HashMap<String, (u64, Option<String>)> {
            let mut snap = std::collections::HashMap::new();
            let walker = walkdir::WalkDir::new(local_dir)
                .follow_links(false)
                .max_depth(100);
            for entry in walker {
                let entry = match entry {
                    Ok(e) => e,
                    Err(_) => continue,
                };
                if !entry.file_type().is_file() {
                    continue;
                }
                let relative = match entry.path().strip_prefix(local_dir) {
                    Ok(r) => r.to_string_lossy().replace('\\', "/"),
                    Err(_) => continue,
                };
                if relative.is_empty() || relative == BISYNC_SNAPSHOT_FILE {
                    continue;
                }
                if let Ok(meta) = entry.metadata() {
                    let size = meta.len();
                    let mtime = meta.modified().ok().map(|t| {
                        let dt: chrono::DateTime<chrono::Utc> = t.into();
                        dt.format("%Y-%m-%dT%H:%M:%S").to_string()
                    });
                    snap.insert(relative, (size, mtime));
                }
            }
            snap
        };

    // Initial sync
    if !watch_no_initial {
        let code = run_sync_cycle!("initial");
        if cancelled.load(Ordering::SeqCst) {
            return code;
        }
    }

    // Build initial snapshot after first sync (or immediately if --watch-no-initial)
    if use_incremental {
        local_snapshot = build_snapshot(local);
    }

    // Watch loop
    loop {
        tokio::select! {
            biased; // prioritize ctrl_c

            _ = shutdown_tick.tick() => {
                if cancelled.load(Ordering::SeqCst) {
                    if syncing.load(Ordering::SeqCst) {
                        continue;
                    }
                    if !quiet {
                        eprintln!("\nWatch mode stopped. {} sync cycles completed.", cycle_count);
                    }
                    return 0;
                }
            }

            Some(changed_paths) = async_rx.recv() => {
                // Suppress if sync in progress
                if syncing.load(Ordering::SeqCst) {
                    while async_rx.try_recv().is_ok() {}
                    continue;
                }
                // Cooldown check
                if last_sync_completed.elapsed() < cooldown_dur {
                    while async_rx.try_recv().is_ok() {}
                    continue;
                }
                let path_count = changed_paths.len();
                let trigger = format!("watcher: {} paths", path_count);

                if use_incremental {
                    let entries = incremental_local_scan(
                        local_path,
                        &changed_paths,
                        &local_snapshot,
                        &exclude_matchers,
                    );
                    // Update snapshot with changes
                    for (ref rel, size, ref mtime) in &entries {
                        local_snapshot.insert(rel.clone(), (*size, mtime.clone()));
                    }
                    // Remove deleted files from snapshot
                    for p in &changed_paths {
                        if let Ok(rel) = p.strip_prefix(local_path) {
                            let rel_str = rel.to_string_lossy().replace('\\', "/");
                            if !entries.iter().any(|(r, _, _)| r == &rel_str) {
                                local_snapshot.remove(&rel_str);
                            }
                        }
                    }
                    run_sync_cycle!(trigger.as_str(), Some(entries));
                    if cancelled.load(Ordering::SeqCst) {
                        if !quiet {
                            eprintln!("\nWatch mode stopped. {} sync cycles completed.", cycle_count);
                        }
                        return 0;
                    }
                } else {
                    run_sync_cycle!(trigger.as_str());
                    if cancelled.load(Ordering::SeqCst) {
                        if !quiet {
                            eprintln!("\nWatch mode stopped. {} sync cycles completed.", cycle_count);
                        }
                        return 0;
                    }
                }
            }

            _ = rescan_tick.tick() => {
                if syncing.load(Ordering::SeqCst) {
                    continue;
                }
                run_sync_cycle!("rescan");
                // Rebuild snapshot after full rescan
                if use_incremental {
                    local_snapshot = build_snapshot(local);
                }
                if cancelled.load(Ordering::SeqCst) {
                    if !quiet {
                        eprintln!("\nWatch mode stopped. {} sync cycles completed.", cycle_count);
                    }
                    return 0;
                }
            }
        }
    }
}

#[allow(clippy::too_many_arguments)]
async fn cmd_sync_doctor(
    url: &str,
    local: &str,
    remote: &str,
    direction: &str,
    delete: bool,
    exclude: &[String],
    error_correction_pct: Option<u32>,
    error_correction_max_overhead_pct: u32,
    track_renames: bool,
    conflict_mode: &str,
    resync: bool,
    checksum: bool,
    cli: &Cli,
    format: OutputFormat,
) -> i32 {
    if !is_valid_sync_direction(direction) {
        print_error(
            format,
            &format!(
                "Invalid sync direction '{}'. Expected one of: upload, download, both",
                direction
            ),
            5,
        );
        return 5;
    }

    let doctor_cfg = if let Some(profile_name) = cli.profile.as_deref() {
        match profile_to_provider_config(profile_name, cli, format) {
            Ok((cfg, _)) => Some(cfg),
            Err(code) => return code,
        }
    } else {
        None
    };

    let (mut provider, initial_path) = match create_and_connect(url, cli, format).await {
        Ok(v) => v,
        Err(code) => return code,
    };
    let remote = resolve_cli_remote_path(&initial_path, remote);

    let local_dir = Path::new(local);
    if !local_dir.is_dir() {
        print_error(
            format,
            &format!("Local path is not a directory: {}", local),
            5,
        );
        let _ = provider.disconnect().await;
        return 5;
    }

    let error_correction_enabled = error_correction_pct.is_some();
    let effective_exclude = sync_effective_exclude_patterns(exclude, error_correction_enabled);
    let exclude_matchers: Vec<globset::GlobMatcher> = effective_exclude
        .iter()
        .filter_map(|pat| globset::Glob::new(pat).ok().map(|g| g.compile_matcher()))
        .collect();

    let mut local_entries: HashMap<String, (u64, Option<String>)> = HashMap::new();
    for entry in walkdir::WalkDir::new(local)
        .follow_links(false)
        .max_depth(100)
    {
        let Ok(entry) = entry else { continue };
        if !entry.file_type().is_file() {
            continue;
        }
        let relative = entry
            .path()
            .strip_prefix(local)
            .unwrap_or(entry.path())
            .to_string_lossy()
            .replace('\\', "/");
        if relative.is_empty() || relative == BISYNC_SNAPSHOT_FILE {
            continue;
        }
        let fname = entry.file_name().to_string_lossy();
        let fname_ref: &str = fname.as_ref();
        if exclude_matchers
            .iter()
            .any(|m| m.is_match(&relative) || m.is_match(fname_ref))
        {
            continue;
        }
        let meta = entry.metadata().ok();
        let size = meta.as_ref().map(|m| m.len()).unwrap_or(0);
        let mtime = meta.and_then(|m| {
            m.modified().ok().map(|t| {
                let dt: chrono::DateTime<chrono::Utc> = t.into();
                dt.format("%Y-%m-%dT%H:%M:%S").to_string()
            })
        });
        local_entries.insert(relative, (size, mtime));
    }
    let local_files = local_entries.len();
    let local_bytes = local_entries.values().map(|(size, _)| *size).sum::<u64>();

    let remote_root_ok = provider.list(&remote).await.is_ok();
    let mut remote_entries: HashMap<String, (u64, Option<String>)> = HashMap::new();
    if remote_root_ok {
        let mut queue: Vec<(String, usize)> = vec![(remote.to_string(), 0)];
        while let Some((dir, depth)) = queue.pop() {
            if depth >= MAX_SCAN_DEPTH || remote_entries.len() >= MAX_SCAN_ENTRIES {
                break;
            }
            if let Ok(entries) = provider.list(&dir).await {
                for e in entries {
                    if e.is_dir {
                        if e.is_walkable_dir() {
                            queue.push((e.path.clone(), depth + 1));
                        }
                    } else {
                        let relative = e
                            .path
                            .strip_prefix(&remote)
                            .unwrap_or(&e.path)
                            .trim_start_matches('/')
                            .to_string();
                        if relative.is_empty() || relative == BISYNC_SNAPSHOT_FILE {
                            continue;
                        }
                        if exclude_matchers
                            .iter()
                            .any(|m| m.is_match(&relative) || m.is_match(&e.name))
                        {
                            continue;
                        }
                        remote_entries.insert(relative, (e.size, e.modified));
                    }
                }
            }
        }
    }
    let remote_files = remote_entries.len();
    let remote_bytes = remote_entries.values().map(|(size, _)| *size).sum::<u64>();

    let ec_max_file_size = ftp_client_gui_lib::sync::AEROSYNC_EC_MAX_FILE_SIZE_BYTES;
    let default_time_val = resolve_default_time(cli);
    let default_time_ref = default_time_val.as_deref();
    let ec_estimate = error_correction_pct.map(|pct| {
        let upload_sizes = sync_doctor_planned_upload_sizes(
            direction,
            conflict_mode,
            &local_entries,
            &remote_entries,
            default_time_ref,
        );
        estimate_sync_doctor_ec_for_uploads(
            upload_sizes,
            pct,
            ec_max_file_size,
            error_correction_max_overhead_pct,
        )
    });

    let mut checks = vec![
        serde_json::json!({"name": "local_path_exists", "ok": true, "path": local}),
        serde_json::json!({"name": "remote_path_reachable", "ok": remote_root_ok, "path": remote}),
    ];
    if !effective_exclude.is_empty() {
        checks.push(
            serde_json::json!({"name": "exclude_patterns", "ok": true, "count": effective_exclude.len()}),
        );
    }

    let mut risks = Vec::new();
    if let Some(cfg) = doctor_cfg.as_ref() {
        push_s3_doctor_checks(&mut checks, &mut risks, "remote", cfg);
    }
    if delete {
        risks.push("delete is enabled; sync may remove orphaned files".to_string());
    }
    if direction == "both" {
        risks.push(format!(
            "bidirectional sync can resolve conflicts automatically using conflict_mode={}",
            conflict_mode
        ));
    }
    if resync {
        risks.push("resync is enabled; previous bisync snapshot will be ignored".to_string());
    }
    if !track_renames && direction == "both" {
        risks.push("track-renames is disabled; moved files may be recopied".to_string());
    }
    if checksum {
        risks
            .push("checksum is enabled; later verification may be slower but stricter".to_string());
    }
    if let (Some(pct), Some(estimate)) = (error_correction_pct, ec_estimate) {
        risks.push(format!(
            "error-correction is enabled; sync will create up to {} .aerocorrect sidecar(s) at about {} overhead",
            estimate.estimated_sidecars,
            format_size(estimate.estimated_overhead_bytes)
        ));
        if estimate.skipped_too_large > 0 {
            risks.push(format!(
                "{} planned upload(s) exceed the EC size cap and will not get sidecars",
                estimate.skipped_too_large
            ));
        }
        checks.push(serde_json::json!({
            "name": "error_correction_estimate",
            "ok": true,
            "level_pct": pct,
            "estimated_sidecars": estimate.estimated_sidecars,
            "estimated_overhead_bytes": estimate.estimated_overhead_bytes,
            "skipped_too_large": estimate.skipped_too_large,
            "skipped_low_benefit": estimate.skipped_low_benefit,
            "max_overhead_pct": error_correction_max_overhead_pct,
            "max_file_size": ec_max_file_size,
        }));
    }
    if !remote_root_ok {
        risks.push("remote path could not be listed".to_string());
    }

    let suggested_next_command =
        format!(
        "aeroftp-cli sync --profile \"{}\" \"{}\" \"{}\" --direction {} --dry-run --json{}{}{}{}{}",
        profile_or_placeholder(cli),
        shell_double_quote(local),
        shell_double_quote(&remote),
        shell_double_quote(direction),
        if delete { " --delete" } else { "" },
        if track_renames { " --track-renames" } else { "" },
        if resync { " --resync" } else { "" },
        error_correction_pct
            .map(|pct| format!(" --error-correction={pct}"))
            .unwrap_or_default(),
        if exclude.is_empty() {
            String::new()
        } else {
            format!(
                " {}",
                exclude
                    .iter()
                    .map(|pattern| format!("--exclude \"{}\"", shell_double_quote(pattern)))
                    .collect::<Vec<_>>()
                    .join(" ")
            )
        }
    );

    let result = CliDoctorResult {
        status: if remote_root_ok { "ok" } else { "attention" },
        doctor: "sync".to_string(),
        summary: serde_json::json!({
            "direction": direction,
            "local_files": local_files,
            "local_bytes": local_bytes,
            "remote_files": remote_files,
            "remote_bytes": remote_bytes,
            "delete": delete,
            "track_renames": track_renames,
            "conflict_mode": conflict_mode,
            "resync": resync,
        }),
        checks,
        risks,
        suggested_next_command,
        ec_enabled: error_correction_pct.map(|_| true),
        ec_level_pct: error_correction_pct,
        ec_estimated_sidecars: ec_estimate.map(|estimate| estimate.estimated_sidecars),
        ec_estimated_overhead_bytes: ec_estimate.map(|estimate| estimate.estimated_overhead_bytes),
        ec_skipped_too_large: ec_estimate.map(|estimate| estimate.skipped_too_large),
        ec_skipped_low_benefit: ec_estimate.map(|estimate| estimate.skipped_low_benefit),
        ec_max_file_size: error_correction_pct.map(|_| ec_max_file_size),
    };

    match format {
        OutputFormat::Json => print_json(&result),
        OutputFormat::Text => {
            println!("Sync doctor");
            println!(
                "  Local:  {} file(s), {}",
                local_files,
                format_size(local_bytes)
            );
            println!(
                "  Remote: {} file(s), {}",
                remote_files,
                format_size(remote_bytes)
            );
            println!("  Direction: {}", direction);
            if let (Some(pct), Some(estimate)) = (error_correction_pct, ec_estimate) {
                println!("  AeroSync EC:");
                println!("    Level: {}%", pct);
                println!("    Estimated sidecars: {}", estimate.estimated_sidecars);
                println!(
                    "    Estimated overhead: {}",
                    format_size(estimate.estimated_overhead_bytes)
                );
                println!(
                    "    Skipped too large: {} (cap {})",
                    estimate.skipped_too_large,
                    format_size(ec_max_file_size)
                );
                if error_correction_max_overhead_pct > 0 {
                    println!(
                        "    Skipped low benefit: {} (max overhead {}%)",
                        estimate.skipped_low_benefit, error_correction_max_overhead_pct
                    );
                }
            }
            if !result.risks.is_empty() {
                println!("  Risks:");
                for risk in &result.risks {
                    println!("    - {}", risk);
                }
            }
            if !cli.quiet {
                eprintln!("Next: {}", result.suggested_next_command);
            }
        }
    }

    let _ = provider.disconnect().await;
    if remote_root_ok {
        0
    } else {
        4
    }
}

// ── Head / Tail / Touch / Hashsum / Check ─────────────────────────

async fn cmd_head(
    url: &str,
    path: &str,
    lines: usize,
    bytes: Option<u64>,
    cli: &Cli,
    format: OutputFormat,
) -> i32 {
    let (mut provider, initial_path) = match create_and_connect(url, cli, format).await {
        Ok(v) => v,
        Err(code) => return code,
    };
    let path = &resolve_cli_remote_path(&initial_path, path);
    match provider.download_to_bytes(path).await {
        Ok(data) => {
            // --bytes: byte-range mode. Doesn't require UTF-8; works
            // for binaries. Returns base64 in JSON when content is not
            // valid UTF-8 to keep the JSON envelope clean. Surfaced by
            // the agent audit (P7, Battery A).
            if let Some(n) = bytes {
                let take = (n as usize).min(data.len());
                let truncated = data.len() > take;
                let slice = &data[..take];
                if matches!(format, OutputFormat::Json) {
                    let (content, encoding) = match std::str::from_utf8(slice) {
                        Ok(s) => (s.to_string(), "utf8"),
                        Err(_) => (
                            base64::engine::general_purpose::STANDARD.encode(slice),
                            "base64",
                        ),
                    };
                    print_json(&serde_json::json!({
                        "status": "ok",
                        "path": path,
                        "bytes_returned": take,
                        "total_size": data.len(),
                        "truncated": truncated,
                        "encoding": encoding,
                        "content": content,
                    }));
                } else {
                    let stdout = io::stdout();
                    let mut handle = stdout.lock();
                    let _ = handle.write_all(slice);
                    let _ = handle.flush();
                }
                let _ = provider.disconnect().await;
                return 0;
            }
            // Default: line mode (legacy behaviour).
            match String::from_utf8(data) {
                Ok(text) => {
                    let result: Vec<&str> = text.lines().take(lines).collect();
                    let output = result.join("\n");
                    if matches!(format, OutputFormat::Json) {
                        print_json(&serde_json::json!({
                            "status": "ok",
                            "path": path,
                            "lines": result.len(),
                            "content": output,
                        }));
                    } else {
                        println!("{}", output);
                    }
                    let _ = provider.disconnect().await;
                    0
                }
                Err(_) => {
                    print_error(
                        format,
                        "File is not valid UTF-8 text. Pass --bytes to read raw bytes.",
                        5,
                    );
                    let _ = provider.disconnect().await;
                    5
                }
            }
        }
        Err(e) => {
            let code = provider_error_to_exit_code(&e);
            print_error(format, &format!("head failed: {}", e), code);
            let _ = provider.disconnect().await;
            code
        }
    }
}

async fn cmd_tail(url: &str, path: &str, lines: usize, cli: &Cli, format: OutputFormat) -> i32 {
    let (mut provider, initial_path) = match create_and_connect(url, cli, format).await {
        Ok(v) => v,
        Err(code) => return code,
    };
    let path = &resolve_cli_remote_path(&initial_path, path);
    match provider.download_to_bytes(path).await {
        Ok(data) => match String::from_utf8(data) {
            Ok(text) => {
                let all_lines: Vec<&str> = text.lines().collect();
                let start = all_lines.len().saturating_sub(lines);
                let result = &all_lines[start..];
                let output = result.join("\n");
                if matches!(format, OutputFormat::Json) {
                    print_json(&serde_json::json!({
                        "status": "ok",
                        "path": path,
                        "lines": result.len(),
                        "content": output,
                    }));
                } else {
                    println!("{}", output);
                }
                let _ = provider.disconnect().await;
                0
            }
            Err(_) => {
                print_error(format, "File is not valid UTF-8 text", 5);
                let _ = provider.disconnect().await;
                5
            }
        },
        Err(e) => {
            let code = provider_error_to_exit_code(&e);
            print_error(format, &format!("tail failed: {}", e), code);
            let _ = provider.disconnect().await;
            code
        }
    }
}

async fn cmd_touch(
    url: &str,
    path: &str,
    _timestamp: Option<&str>,
    cli: &Cli,
    format: OutputFormat,
) -> i32 {
    let (mut provider, initial_path) = match create_and_connect(url, cli, format).await {
        Ok(v) => v,
        Err(code) => return code,
    };
    let path = &resolve_cli_remote_path(&initial_path, path);
    if let Some(code) = reject_restricted_target(provider.as_mut(), path, "touch", format).await {
        return code;
    }
    // Check if file exists
    match provider.stat(path).await {
        Ok(_) => {
            // File exists - touch is a no-op for most providers (mtime update not widely supported)
            if matches!(format, OutputFormat::Json) {
                print_json(&serde_json::json!({"status": "ok", "path": path, "action": "exists"}));
            } else {
                eprintln!("File exists: {}", path);
            }
            let _ = provider.disconnect().await;
            0
        }
        Err(_) => {
            // File doesn't exist - create empty file
            let tmp = std::env::temp_dir().join(format!("aeroftp_touch_{}", uuid::Uuid::new_v4()));
            if let Err(e) = std::fs::write(&tmp, b"") {
                print_error(format, &format!("Failed to create temp file: {}", e), 4);
                let _ = provider.disconnect().await;
                return 4;
            }
            let result = provider
                .upload(tmp.to_str().unwrap_or(""), path, None)
                .await;
            let _ = std::fs::remove_file(&tmp);
            match result {
                Ok(()) => {
                    if matches!(format, OutputFormat::Json) {
                        print_json(
                            &serde_json::json!({"status": "ok", "path": path, "action": "created"}),
                        );
                    } else {
                        eprintln!("Created: {}", path);
                    }
                    let _ = provider.disconnect().await;
                    0
                }
                Err(e) => {
                    let code = provider_error_to_exit_code(&e);
                    print_error(format, &format!("touch failed: {}", e), code);
                    let _ = provider.disconnect().await;
                    code
                }
            }
        }
    }
}

fn display_port_for_provider(provider_type: &ProviderType, server_info: Option<&str>) -> u16 {
    if let Some(info) = server_info {
        if let Some((_, port_str)) = info.rsplit_once(':') {
            if !port_str.is_empty() && port_str.chars().all(|c| c.is_ascii_digit()) {
                if let Ok(port) = port_str.parse::<u16>() {
                    return port;
                }
            }
        }
    }

    match provider_type {
        ProviderType::Ftp | ProviderType::Ftps => 21,
        ProviderType::Sftp => 22,
        _ => 443,
    }
}

async fn cmd_hashsum(
    algorithm: HashAlgorithm,
    url: &str,
    path: &str,
    cli: &Cli,
    format: OutputFormat,
) -> i32 {
    let (mut provider, initial_path) = match create_and_connect(url, cli, format).await {
        Ok(v) => v,
        Err(code) => return code,
    };
    let path = &resolve_cli_remote_path(&initial_path, path);

    // Fast-path: prefer a server-side digest (S3 ETag md5, B2 contentSha1,
    // pCloud /checksumfile, SFTP sha256sum) so the file never leaves the
    // server. Falls through to download+digest for sha512/blake3 (never
    // server-side) and for multipart/SSE objects with no usable hash.
    if provider.supports_checksum() {
        if let Ok(map) = provider.checksum(path).await {
            if let Some(h) = map.get(hash_algo_key(algorithm)) {
                let hash = h.trim().to_ascii_lowercase();
                let size = provider.stat(path).await.map(|e| e.size).unwrap_or(0);
                if matches!(format, OutputFormat::Json) {
                    print_json(&CliHashResult {
                        status: "ok",
                        algorithm: hash_algo_key(algorithm).to_string(),
                        hash: hash.clone(),
                        path: path.to_string(),
                        size,
                    });
                } else {
                    println!("{}  {}", hash, path);
                }
                let _ = provider.disconnect().await;
                return 0;
            }
        }
    }

    if algorithm.is_server_only() {
        // quickxor/dropbox cannot be computed locally: if the backend
        // did not expose it above there is no honest fallback. Exit 7
        // (NotSupported), never a misleading download-and-digest.
        print_error(
            format,
            &format!(
                "hashsum failed: {} is server-side only and this backend did not provide it for {}",
                hash_algo_key(algorithm),
                path
            ),
            7,
        );
        let _ = provider.disconnect().await;
        return 7;
    }

    match provider.download_to_bytes(path).await {
        Ok(data) => {
            let hash = match algorithm {
                HashAlgorithm::Md5 => {
                    use md5::Digest;
                    format!("{:x}", md5::Md5::digest(&data))
                }
                HashAlgorithm::Sha1 => {
                    use sha1::Digest;
                    format!("{:x}", sha1::Sha1::digest(&data))
                }
                HashAlgorithm::Sha256 => {
                    use sha2::Digest;
                    format!("{:x}", sha2::Sha256::digest(&data))
                }
                HashAlgorithm::Sha512 => {
                    use sha2::Digest;
                    format!("{:x}", sha2::Sha512::digest(&data))
                }
                HashAlgorithm::Blake3 => blake3::hash(&data).to_hex().to_string(),
                HashAlgorithm::Quickxor | HashAlgorithm::Dropbox => {
                    unreachable!("server-only hashes return before download")
                }
            };
            let algo_name = hash_algo_key(algorithm);
            if matches!(format, OutputFormat::Json) {
                print_json(&CliHashResult {
                    status: "ok",
                    algorithm: algo_name.to_string(),
                    hash: hash.clone(),
                    path: path.to_string(),
                    size: data.len() as u64,
                });
            } else {
                println!("{}  {}", hash, path);
            }
            let _ = provider.disconnect().await;
            0
        }
        Err(e) => {
            let code = provider_error_to_exit_code(&e);
            print_error(format, &format!("hashsum failed: {}", e), code);
            let _ = provider.disconnect().await;
            code
        }
    }
}

/// Resolve the active `--profile`'s crypt overlay (if any) and unlock the
/// compare keys so `check` / `reconcile` see plaintext remote names and sizes,
/// closing the same gap the GUI Compare fix closes (Ehud, discussion #364).
///
/// Returns `Ok(None)` for a URL invocation or a profile without an enabled
/// overlay, leaving the plain compare path byte-identical. When an overlay IS
/// present the unlock must succeed: a missing secret or wrong password returns
/// an error (fail closed) rather than silently comparing ciphertext, which is
/// the very bug this closes. The `provider` is borrowed only to download the
/// AeroCrypt overlay config; rclone-crypt needs no remote round trip.
async fn cli_unlock_crypt_compare_keys(
    provider: &mut dyn StorageProvider,
    remote_path: &str,
    cli: &Cli,
    format: OutputFormat,
) -> Result<Option<ftp_client_gui_lib::crypt_compare::CryptCompareKeys>, i32> {
    let Some(profile_name) = cli.profile.as_deref() else {
        return Ok(None);
    };
    // The connect already opened and matched the profile uniquely; a vault
    // hiccup here must not mask the plain path, so fall through to None.
    let Ok(store) = open_vault(cli) else {
        return Ok(None);
    };
    let Ok(profiles) = load_active_user_profiles(cli, &store) else {
        return Ok(None);
    };
    let profile = match match_profile_by_query(&profiles, profile_name) {
        ProfileMatch::One(p) => p,
        _ => return Ok(None),
    };
    if !profile_has_crypt_overlay(profile) {
        return Ok(None);
    }

    let overlay = profile
        .get("aeroCryptOverlay")
        .cloned()
        .unwrap_or(serde_json::Value::Null);
    let kind = overlay
        .get("kind")
        .and_then(|v| v.as_str())
        .unwrap_or("aerocrypt")
        .to_string();
    let id = profile.get("id").and_then(|v| v.as_str()).unwrap_or("");
    let remote_scope = overlay
        .get("remoteScope")
        .and_then(|v| v.as_str())
        .filter(|s| !s.is_empty())
        .map(|s| s.to_string())
        .unwrap_or_else(|| remote_path.to_string());
    let filename_encryption = overlay
        .get("filenameEncryption")
        .and_then(|v| v.as_str())
        .unwrap_or("standard")
        .to_string();
    let directory_name_encryption = overlay
        .get("directoryNameEncryption")
        .and_then(|v| v.as_bool())
        .unwrap_or(true);

    // Scope the overlay-secret read to the SAME user the profile was loaded for
    // (honor --user), not the persistent active user: otherwise `--user other`
    // reads the wrong partition's overlay password.
    let uid = scoped_credential_user_id(cli, &store);
    // Tier 1 keyfile second factor: the profile-bound keyfile path (same
    // per-profile vault key the GUI stores, honoring --user scoping like the
    // pw/salt reads) resolved fail-closed to its digest, BEFORE the password
    // guard: a keyfile-only AeroCrypt vault legally has an empty password.
    let keyfile_path = read_server_cred(
        &store,
        uid,
        &format!("aerocrypt_overlay_keyfile_path_{}", id),
    )
    .filter(|s| !s.is_empty())
    .or_else(|| {
        std::env::var("AEROFTP_CRYPT_OVERLAY_KEYFILE")
            .ok()
            .filter(|s| !s.is_empty())
    });
    let keyfile_digest = match keyfile_path {
        None => None,
        Some(p) => match ftp_client_gui_lib::crypt_overlay_provider::keyfile_digest_from_path(&p) {
            Ok(d) => Some(d),
            Err(e) => {
                print_error(format, &format!("Crypt overlay unlock failed: {}", e), 6);
                return Err(6);
            }
        },
    };
    let password = read_server_cred(&store, uid, &format!("aerocrypt_overlay_pw_{}", id))
        .or_else(|| std::env::var("AEROFTP_CRYPT_OVERLAY_PASSWORD").ok())
        .unwrap_or_default();
    // Keyfiles do not apply to rclone-crypt, which keeps requiring a password.
    if password.is_empty() && (kind != "aerocrypt" || keyfile_digest.is_none()) {
        print_error(
            format,
            "Crypt overlay profile has no stored password. Store it in the AeroFTP GUI, or set AEROFTP_CRYPT_OVERLAY_PASSWORD.",
            5,
        );
        return Err(5);
    }
    let salt = read_server_cred(&store, uid, &format!("aerocrypt_overlay_salt_{}", id))
        .or_else(|| std::env::var("AEROFTP_CRYPT_OVERLAY_SALT").ok())
        .unwrap_or_default();

    let params = ftp_client_gui_lib::crypt_compare::OverlayUnlockParams {
        kind,
        remote_scope,
        filename_encryption,
        directory_name_encryption,
        off_suffix: None,
    };
    match ftp_client_gui_lib::crypt_compare::unlock_overlay_keys(
        provider,
        &params,
        &password,
        &salt,
        keyfile_digest.as_ref(),
    )
    .await
    {
        Ok(keys) => Ok(Some(keys)),
        Err(e) => {
            print_error(format, &format!("Crypt overlay unlock failed: {}", e), 6);
            Err(6)
        }
    }
}

async fn cmd_check(
    url: &str,
    local_path: &str,
    remote_path: &str,
    checksum: bool,
    one_way: bool,
    cli: &Cli,
    format: OutputFormat,
) -> i32 {
    let start = Instant::now();
    let (mut provider, initial_path) = match create_and_connect(url, cli, format).await {
        Ok(v) => v,
        Err(code) => return code,
    };
    let remote_path = &resolve_cli_remote_path(&initial_path, remote_path);

    let local_dir = Path::new(local_path);
    if !local_dir.is_dir() {
        print_error(
            format,
            &format!("Local path is not a directory: {}", local_path),
            5,
        );
        let _ = provider.disconnect().await;
        return 5;
    }

    // Delegate scan + comparison to sync_core. Both CLI and MCP now share
    // the same implementation, so a fix in one propagates to the other.
    use ftp_client_gui_lib::sync_core::{
        compare_trees, scan_local_tree, scan_remote_tree, ScanOptions,
    };
    // When the profile carries a crypt overlay, unlock the compare keys before
    // the scan so the remote tree is decrypted (names + rclone sizes) to match
    // the plaintext local tree. Fail closed if the overlay cannot be unlocked.
    let provider_is_crypt_overlay =
        ftp_client_gui_lib::crypt_overlay_provider::is_crypt_overlay_provider(provider.as_mut());
    let crypt_keys = if provider_is_crypt_overlay {
        None
    } else {
        match cli_unlock_crypt_compare_keys(provider.as_mut(), remote_path, cli, format).await {
            Ok(keys) => keys,
            Err(code) => {
                let _ = provider.disconnect().await;
                return code;
            }
        }
    };
    let crypt_active = crypt_keys.is_some() || provider_is_crypt_overlay;
    let scan_opts = ScanOptions {
        compute_checksum: checksum && !crypt_active,
        disable_recursive_fastpath: crypt_active,
        max_depth: Some(MAX_SCAN_DEPTH),
        ..Default::default()
    };
    let locals = scan_local_tree(local_path, &scan_opts);
    let mut remotes = scan_remote_tree(&mut provider, remote_path, &scan_opts).await;
    if let Some(keys) = &crypt_keys {
        let raw_len = remotes.len();
        remotes = ftp_client_gui_lib::crypt_compare::normalize_remote_entries(remotes, keys);
        if keys.wrong_key_suspected(raw_len, remotes.len()) {
            print_error(
                format,
                "Crypt overlay decrypted no remote entries: wrong overlay password or non-crypt remote.",
                6,
            );
            let _ = provider.disconnect().await;
            return 6;
        }
    }
    let diff = compare_trees(&locals, &remotes, one_way);

    let match_count = diff.match_count() as u32;
    let differ_count = diff.differ_count() as u32;
    let missing_local = diff.missing_local_count() as u32;
    let missing_remote = diff.missing_remote_count() as u32;

    let mut details: Vec<CliCheckEntry> = Vec::new();
    for entry in &diff.differ {
        details.push(CliCheckEntry {
            path: entry.rel_path.clone(),
            status: "differ".to_string(),
            local_size: entry.local_size,
            remote_size: entry.remote_size,
        });
    }
    for entry in &diff.missing_remote {
        details.push(CliCheckEntry {
            path: entry.rel_path.clone(),
            status: "missing_remote".to_string(),
            local_size: entry.local_size,
            remote_size: None,
        });
    }
    for entry in &diff.missing_local {
        details.push(CliCheckEntry {
            path: entry.rel_path.clone(),
            status: "missing_local".to_string(),
            local_size: None,
            remote_size: entry.remote_size,
        });
    }

    let elapsed = start.elapsed().as_secs_f64();

    if matches!(format, OutputFormat::Json) {
        print_json(&serde_json::json!({
            "status": if differ_count == 0 && missing_local == 0 && missing_remote == 0 {
                "ok"
            } else {
                "differences_found"
            },
            "match_count": match_count,
            "differ_count": differ_count,
            "missing_local": missing_local,
            "missing_remote": missing_remote,
            "elapsed_secs": elapsed,
            "details": details,
            "suggested_next_command": format!(
                "aeroftp-cli sync --profile \"{}\" \"{}\" \"{}\" --dry-run --json",
                profile_or_placeholder(cli),
                shell_double_quote(local_path),
                shell_double_quote(remote_path)
            ),
        }));
    } else {
        eprintln!(
            "\n  Match: {}  Differ: {}  Missing local: {}  Missing remote: {}  ({:.1}s)",
            match_count, differ_count, missing_local, missing_remote, elapsed
        );
        eprintln!(
            "Next: aeroftp-cli sync --profile \"{}\" \"{}\" \"{}\" --dry-run --json",
            profile_or_placeholder(cli),
            shell_double_quote(local_path),
            shell_double_quote(remote_path)
        );
        for d in &details {
            let icon = match d.status.as_str() {
                "differ" => "~",
                "missing_local" => "-",
                "missing_remote" => "+",
                _ => "?",
            };
            eprintln!("  {} {}", icon, d.path);
        }
    }

    let _ = provider.disconnect().await;
    if differ_count > 0 || missing_local > 0 || missing_remote > 0 {
        4
    } else {
        0
    }
}

fn decrypt_rclone_crypt_rel_path(
    name_key: &[u8; 32],
    name_tweak: &[u8; 16],
    encrypted_rel_path: &str,
    filename_encryption: &str,
    off_suffix: &str,
) -> Result<String, String> {
    let components: Vec<&str> = encrypted_rel_path.split('/').collect();
    let last_idx = components.len().saturating_sub(1);
    let mut decrypted = String::new();

    for (idx, comp) in components.iter().enumerate() {
        if comp.is_empty() {
            return Err("empty path component".to_string());
        }

        let dec_comp = match filename_encryption {
            "off" => {
                // Only the leaf carries the suffix; directory names do not.
                if idx == last_idx && !off_suffix.is_empty() {
                    comp.strip_suffix(off_suffix).unwrap_or(comp).to_string()
                } else {
                    comp.to_string()
                }
            }
            "obfuscate" => ftp_client_gui_lib::rclone_crypt::deobfuscate_name(name_tweak, comp)?,
            "standard" => {
                ftp_client_gui_lib::rclone_crypt::decrypt_name(name_key, name_tweak, comp)?
            }
            other => return Err(format!("unsupported filename_encryption={}", other)),
        };

        if !decrypted.is_empty() {
            decrypted.push('/');
        }
        decrypted.push_str(&dec_comp);
    }

    Ok(decrypted)
}

#[allow(clippy::too_many_arguments)]
async fn cmd_cryptcheck(
    url: &str,
    local_path: &str,
    remote_path: &str,
    password: Option<String>,
    password2: Option<String>,
    filename_encryption: &str,
    suffix: Option<&str>,
    one_way: bool,
    _checkfile: Option<String>,
    algorithm: &str,
    cli: &Cli,
    format: OutputFormat,
) -> i32 {
    let start = Instant::now();
    // With name encryption off, AeroFTP/rclone tag objects with a suffix
    // (default ".bin"); strip it from the leaf before comparing to local.
    let off_suffix = ftp_client_gui_lib::rclone_crypt::resolve_off_suffix(suffix);
    let filename_mode = filename_encryption.trim().to_ascii_lowercase();
    if !matches!(filename_mode.as_str(), "standard" | "obfuscate" | "off") {
        print_error(
            format,
            &format!("unsupported filename_encryption={}", filename_encryption),
            5,
        );
        return 5;
    }

    let pwd = password
        .unwrap_or_else(|| std::env::var("AEROFTP_RCLONE_CRYPT_PASSWORD").unwrap_or_default());
    if pwd.is_empty() {
        print_error(
            format,
            "wrong password or non-crypt remote (missing password)",
            5,
        );
        return 5;
    }
    let salt = password2
        .unwrap_or_else(|| std::env::var("AEROFTP_RCLONE_CRYPT_PASSWORD2").unwrap_or_default());

    let (name_key, data_key, name_tweak) =
        match ftp_client_gui_lib::rclone_crypt::derive_keys_with_tweak(&pwd, &salt) {
            Ok(keys) => keys,
            Err(e) => {
                print_error(format, &format!("Key derivation failed: {}", e), 5);
                return 5;
            }
        };

    let (mut provider, initial_path) = match create_and_connect(url, cli, format).await {
        Ok(v) => v,
        Err(code) => return code,
    };
    let remote_path_resolved = resolve_cli_remote_path(&initial_path, remote_path);

    let local_dir = Path::new(local_path);
    if !local_dir.is_dir() {
        print_error(
            format,
            &format!("Local path is not a directory: {}", local_path),
            5,
        );
        let _ = provider.disconnect().await;
        return 5;
    }

    use ftp_client_gui_lib::sync_core::{scan_local_tree, scan_remote_tree, ScanOptions};
    let scan_opts = ScanOptions {
        compute_checksum: false,
        max_depth: Some(MAX_SCAN_DEPTH),
        ..Default::default()
    };

    let locals = scan_local_tree(local_path, &scan_opts);
    let remotes = scan_remote_tree(&mut provider, &remote_path_resolved, &scan_opts).await;

    let mut decrypted_remotes = std::collections::HashMap::new();
    for r in &remotes {
        let is_dir_iv = r.rel_path.ends_with("/dirIV")
            || r.rel_path.ends_with("/diriv")
            || r.rel_path.ends_with("/.diriv")
            || r.rel_path == "dirIV"
            || r.rel_path == "diriv"
            || r.rel_path == ".diriv";
        if is_dir_iv {
            continue;
        }

        if let Ok(current_dec_dir) = decrypt_rclone_crypt_rel_path(
            &name_key,
            &name_tweak,
            &r.rel_path,
            filename_mode.as_str(),
            &off_suffix,
        ) {
            decrypted_remotes.insert(current_dec_dir.clone(), r.clone());
        }
    }

    let mut match_count = 0;
    let mut differ_count = 0;
    let mut missing_local = 0;
    let mut missing_remote = 0;
    let mut details = Vec::new();

    use std::sync::Arc;
    use tokio::sync::{Mutex as AsyncMutex, Semaphore};

    let match_count_safe = Arc::new(AsyncMutex::new(0));
    let differ_count_safe = Arc::new(AsyncMutex::new(0));
    // CRYPT-01: operational failures (unreadable local file, download/connect
    // failure, decrypt failure) are counted separately from content differences
    // so they are not silently reported as data mismatches.
    let error_count_safe = Arc::new(AsyncMutex::new(0u32));

    let details_safe = Arc::new(AsyncMutex::new(Vec::new()));

    let mut checks = Vec::new();
    for local_file in &locals {
        let rel = &local_file.rel_path;
        if let Some(remote_file) = decrypted_remotes.remove(rel) {
            checks.push((local_file.clone(), remote_file.clone()));
        } else {
            missing_remote += 1;
            details.push(CliCheckEntry {
                path: rel.clone(),
                status: "missing_remote".to_string(),
                local_size: Some(local_file.size),
                remote_size: None,
            });
            if matches!(format, OutputFormat::Text) {
                eprintln!("- {}", rel);
            }
        }
    }

    let concurrency = effective_parallel_workers(cli);
    let algorithm = algorithm.to_string();
    let data_key = Arc::new(data_key);
    let local_path = local_path.to_string();
    let remote_path_resolved = remote_path_resolved.to_string();

    let cfg = match resolve_url_or_profile(url, cli, format) {
        Ok(v) => v.0,
        Err(code) => return code,
    };

    let semaphore = Arc::new(Semaphore::new(concurrency));
    let mut join_handles = Vec::new();

    for (local_file, remote_file) in checks {
        let algo = algorithm.clone();
        let dk = Arc::clone(&data_key);
        let lp = local_path.clone();
        let rp = remote_path_resolved.clone();
        let mc = Arc::clone(&match_count_safe);
        let dc = Arc::clone(&differ_count_safe);
        let ec = Arc::clone(&error_count_safe);
        let ds = Arc::clone(&details_safe);
        let c = cfg.clone();
        let permit = Arc::clone(&semaphore).acquire_owned().await.unwrap();

        join_handles.push(tokio::spawn(async move {
            // CRYPT-01: classify each operational failure with a distinct status
            // and counter so a connect/download/decrypt error is never reported as
            // a content `differ`. Helper records the error and emits a text marker.
            async fn record_error(
                ec: &Arc<AsyncMutex<u32>>,
                ds: &Arc<AsyncMutex<Vec<CliCheckEntry>>>,
                rel: &str,
                status: &str,
                local_size: Option<u64>,
                remote_size: Option<u64>,
                text: bool,
            ) {
                *ec.lock().await += 1;
                ds.lock().await.push(CliCheckEntry {
                    path: rel.to_string(),
                    status: status.to_string(),
                    local_size,
                    remote_size,
                });
                if text {
                    eprintln!("! {} ({})", rel, status);
                }
            }
            let is_text = matches!(format, OutputFormat::Text);

            let rel = &local_file.rel_path;
            let local_full = format!("{}/{}", lp, rel);
            let local_bytes = match tokio::fs::read(&local_full).await {
                Ok(b) => b,
                Err(_) => {
                    record_error(
                        &ec,
                        &ds,
                        rel,
                        "local_read_error",
                        Some(local_file.size),
                        Some(remote_file.size),
                        is_text,
                    )
                    .await;
                    drop(permit);
                    return;
                }
            };

            let local_hash = if algo == "md5" {
                use md5::Digest;
                format!("{:x}", md5::Md5::digest(&local_bytes))
            } else {
                use sha2::Digest;
                format!("{:x}", sha2::Sha256::digest(&local_bytes))
            };

            let remote_full = format!("{}/{}", rp, remote_file.rel_path);
            let mut p = match ProviderFactory::create(&c) {
                Ok(p) => p,
                Err(_) => {
                    record_error(
                        &ec,
                        &ds,
                        rel,
                        "connect_error",
                        Some(local_bytes.len() as u64),
                        Some(remote_file.size),
                        is_text,
                    )
                    .await;
                    drop(permit);
                    return;
                }
            };
            if p.connect().await.is_err() {
                record_error(
                    &ec,
                    &ds,
                    rel,
                    "connect_error",
                    Some(local_bytes.len() as u64),
                    Some(remote_file.size),
                    is_text,
                )
                .await;
                drop(permit);
                return;
            }
            let remote_bytes = match p.download_to_bytes(&remote_full).await {
                Ok(b) => b,
                Err(_) => {
                    record_error(
                        &ec,
                        &ds,
                        rel,
                        "remote_download_error",
                        Some(local_bytes.len() as u64),
                        Some(remote_file.size),
                        is_text,
                    )
                    .await;
                    drop(permit);
                    return;
                }
            };
            let decrypted = if algo == "md5" {
                ftp_client_gui_lib::rclone_crypt::decrypt_and_hash::<md5::Md5>(&remote_bytes, &dk)
                    .map(|(h, _)| format!("{:x}", h))
            } else {
                ftp_client_gui_lib::rclone_crypt::decrypt_and_hash::<sha2::Sha256>(
                    &remote_bytes,
                    &dk,
                )
                .map(|(h, _)| format!("{:x}", h))
            };
            let remote_hash = match decrypted {
                Ok(h) => h,
                Err(_) => {
                    record_error(
                        &ec,
                        &ds,
                        rel,
                        "decrypt_error",
                        Some(local_bytes.len() as u64),
                        Some(remote_file.size),
                        is_text,
                    )
                    .await;
                    drop(permit);
                    return;
                }
            };

            if local_hash == remote_hash {
                *mc.lock().await += 1;
                if is_text {
                    eprintln!("= {}", rel);
                }
            } else {
                *dc.lock().await += 1;
                ds.lock().await.push(CliCheckEntry {
                    path: rel.clone(),
                    status: "differ".to_string(),
                    local_size: Some(local_bytes.len() as u64),
                    remote_size: Some(remote_file.size),
                });
                if is_text {
                    eprintln!("* {}", rel);
                }
            }

            drop(permit);
        }));
    }

    for handle in join_handles {
        let _ = handle.await;
    }

    match_count += *match_count_safe.lock().await;
    differ_count += *differ_count_safe.lock().await;
    let error_count = *error_count_safe.lock().await;
    details.append(&mut *details_safe.lock().await);

    if !one_way {
        for (rel, remote_file) in decrypted_remotes {
            missing_local += 1;
            details.push(CliCheckEntry {
                path: rel.clone(),
                status: "missing_local".to_string(),
                local_size: None,
                remote_size: Some(remote_file.size),
            });
            if matches!(format, OutputFormat::Text) {
                eprintln!("+ {}", rel);
            }
        }
    }

    let elapsed = start.elapsed().as_secs_f64();

    if matches!(format, OutputFormat::Json) {
        print_json(&serde_json::json!({
            "status": if error_count > 0 {
                "partial"
            } else if differ_count == 0 && missing_local == 0 && missing_remote == 0 {
                "ok"
            } else {
                "differences_found"
            },
            "match_count": match_count,
            "differ_count": differ_count,
            "error_count": error_count,
            "missing_local": missing_local,
            "missing_remote": missing_remote,
            "elapsed_secs": elapsed,
            "algorithm": algorithm,
            "details": details,
        }));
    } else {
        eprintln!(
            "\n  Match: {}  Differ: {}  Errors: {}  Missing local: {}  Missing remote: {}  ({:.1}s)",
            match_count, differ_count, error_count, missing_local, missing_remote, elapsed
        );
    }

    let _ = provider.disconnect().await;
    // CRYPT-01: an operational error is exit 4 (incomplete check), distinct from a
    // clean run; differences/missing also exit 4. Only a fully clean run is 0.
    if differ_count > 0 || missing_local > 0 || missing_remote > 0 || error_count > 0 {
        4
    } else {
        0
    }
}

#[allow(clippy::too_many_arguments)]
async fn cmd_reconcile(
    url: &str,
    local_path: &str,
    remote_path: &str,
    checksum: bool,
    one_way: bool,
    exclude: &[String],
    reconcile_format: ReconcileFormat,
    cli: &Cli,
    format: OutputFormat,
) -> i32 {
    let (mut provider, initial_path) = match create_and_connect(url, cli, format).await {
        Ok(v) => v,
        Err(code) => return code,
    };
    let remote_path = &resolve_cli_remote_path(&initial_path, remote_path);

    let start = Instant::now();
    let local_dir = Path::new(local_path);
    if !local_dir.is_dir() {
        print_error(
            format,
            &format!("Local path is not a directory: {}", local_path),
            5,
        );
        let _ = provider.disconnect().await;
        return 5;
    }

    // Merge per-command excludes with global `--exclude-global` and any
    // patterns loaded from `--exclude-from` file.
    let mut all_exclude = exclude.to_vec();
    all_exclude.extend(cli.exclude_global.clone());
    if let Some(ref path) = cli.exclude_from {
        if let Ok(patterns) = load_patterns_from_file(path) {
            all_exclude.extend(patterns);
        }
    }

    // Unlock the profile's crypt overlay (if any) before scanning so the remote
    // tree is decrypted to match the plaintext local tree. Fail closed when the
    // overlay cannot be unlocked, instead of reporting every file as drift.
    let provider_is_crypt_overlay =
        ftp_client_gui_lib::crypt_overlay_provider::is_crypt_overlay_provider(provider.as_mut());
    let crypt_keys = if provider_is_crypt_overlay {
        None
    } else {
        match cli_unlock_crypt_compare_keys(provider.as_mut(), remote_path, cli, format).await {
            Ok(keys) => keys,
            Err(code) => {
                let _ = provider.disconnect().await;
                return code;
            }
        }
    };
    let crypt_active = crypt_keys.is_some() || provider_is_crypt_overlay;

    use ftp_client_gui_lib::sync_core::{compare_trees, ScanOptions};
    let scan_opts = ScanOptions {
        exclude_patterns: all_exclude,
        compute_checksum: checksum && !crypt_active,
        compute_remote_checksum: checksum && !crypt_active,
        disable_recursive_fastpath: crypt_active,
        max_depth: Some(MAX_SCAN_DEPTH),
        ..Default::default()
    };
    let local_spinner = maybe_create_scan_spinner(format, cli, "Scanning local...");
    let locals = scan_local_tree_with_progress(local_path, &scan_opts, &local_spinner);
    if let Some(pb) = local_spinner {
        pb.finish_and_clear();
    }

    let remote_spinner = maybe_create_scan_spinner(format, cli, "Scanning remote...");
    let (mut remotes, remote_health) =
        scan_remote_tree_with_progress(&mut provider, remote_path, &scan_opts, &remote_spinner)
            .await;
    if let Some(pb) = remote_spinner {
        pb.finish_and_clear();
    }
    if let Some(keys) = &crypt_keys {
        let raw_len = remotes.len();
        remotes = ftp_client_gui_lib::crypt_compare::normalize_remote_entries(remotes, keys);
        if keys.wrong_key_suspected(raw_len, remotes.len()) {
            print_error(
                format,
                "Crypt overlay decrypted no remote entries: wrong overlay password or non-crypt remote.",
                6,
            );
            let _ = provider.disconnect().await;
            return 6;
        }
    }
    // TX-01: an incomplete remote listing makes "missing_remote" unreliable; if a
    // later `sync --from-reconcile --delete` trusted this file it could delete
    // intact local files. Surface the partial state so a pipeline can stop here.
    if remote_health.is_incomplete() && !cli.quiet {
        eprintln!(
            "Warning: remote scan incomplete ({} list error(s){}); reconcile result is partial and unsafe to feed into `sync --delete`.",
            remote_health.errors,
            if remote_health.truncated { ", truncated" } else { "" }
        );
    }
    let diff = compare_trees(&locals, &remotes, one_way);

    let matches_group: Vec<serde_json::Value> = diff
        .matches
        .iter()
        .map(|e| {
            serde_json::json!({
                "path": e.rel_path,
                "local_size": e.local_size,
                "remote_size": e.remote_size,
                "compare_method": e.compare_method,
            })
        })
        .collect();
    let differ_group: Vec<serde_json::Value> = diff
        .differ
        .iter()
        .map(|e| {
            serde_json::json!({
                "path": e.rel_path,
                "local_size": e.local_size,
                "remote_size": e.remote_size,
                "compare_method": e.compare_method,
            })
        })
        .collect();
    let missing_remote_group: Vec<serde_json::Value> = diff
        .missing_remote
        .iter()
        .map(|e| {
            serde_json::json!({
                "path": e.rel_path,
                "local_size": e.local_size,
            })
        })
        .collect();
    let missing_local_group: Vec<serde_json::Value> = diff
        .missing_local
        .iter()
        .map(|e| {
            serde_json::json!({
                "path": e.rel_path,
                "remote_size": e.remote_size,
            })
        })
        .collect();

    let elapsed = start.elapsed().as_secs_f64();
    let suggested_next_command = format!(
        "aeroftp-cli sync --profile \"{}\" \"{}\" \"{}\" --dry-run --json",
        profile_or_placeholder(cli),
        shell_double_quote(local_path),
        shell_double_quote(remote_path)
    );

    let result = CliReconcileResult {
        status: if remote_health.is_incomplete() {
            "partial"
        } else if differ_group.is_empty()
            && missing_remote_group.is_empty()
            && missing_local_group.is_empty()
        {
            "ok"
        } else {
            "differences_found"
        },
        local_path: local_path.to_string(),
        remote_path: remote_path.to_string(),
        summary: serde_json::json!({
            "match_count": matches_group.len(),
            "differ_count": differ_group.len(),
            "missing_remote_count": missing_remote_group.len(),
            "missing_local_count": missing_local_group.len(),
            "remote_scan_incomplete": remote_health.is_incomplete(),
            "remote_scan_errors": remote_health.errors,
            "remote_scan_truncated": remote_health.truncated,
            "elapsed_secs": elapsed,
        }),
        groups: serde_json::json!({
            "match": matches_group,
            "differ": differ_group,
            "missing_remote": missing_remote_group,
            "missing_local": missing_local_group,
        }),
        suggested_next_command,
    };

    match format {
        OutputFormat::Json => {
            if reconcile_format == ReconcileFormat::Summary {
                print_json(&serde_json::json!({
                    "status": result.status,
                    "local_path": result.local_path,
                    "remote_path": result.remote_path,
                    "summary": result.summary,
                    "suggested_next_command": result.suggested_next_command,
                }));
            } else {
                print_json(&result);
            }
        }
        OutputFormat::Text => {
            println!("Reconcile summary:");
            println!("  Match: {}", result.summary["match_count"]);
            println!("  Differ: {}", result.summary["differ_count"]);
            println!(
                "  Missing remote: {}",
                result.summary["missing_remote_count"]
            );
            println!("  Missing local: {}", result.summary["missing_local_count"]);
            println!("  Elapsed: {:.2}s", elapsed);
            if reconcile_format == ReconcileFormat::Detailed && !cli.quiet {
                for group in &[
                    ("Differ", &differ_group),
                    ("Missing remote", &missing_remote_group),
                    ("Missing local", &missing_local_group),
                ] {
                    if group.1.is_empty() {
                        continue;
                    }
                    eprintln!("{}:", group.0);
                    for entry in group.1 {
                        if let Some(path) = entry.get("path").and_then(|value| value.as_str()) {
                            eprintln!("  - {}", path);
                        }
                    }
                }
            }
            if !cli.quiet {
                eprintln!("Next: {}", result.suggested_next_command);
            }
        }
    }

    let _ = provider.disconnect().await;
    // "ok" -> 0; "differences_found" and "partial" (incomplete remote scan) -> 4.
    if result.status == "ok" {
        0
    } else {
        4
    }
}

// ── Cross-profile transfer ─────────────────────────────────────────────────

#[allow(clippy::too_many_arguments)]
async fn cmd_transfer_doctor(
    source_profile: &str,
    dest_profile: &str,
    source_path: &str,
    dest_path: &str,
    recursive: bool,
    skip_existing: bool,
    cli: &Cli,
    format: OutputFormat,
) -> i32 {
    use ftp_client_gui_lib::cross_profile_transfer::{plan_transfer, CrossProfileTransferRequest};

    let src_cfg = match profile_to_provider_config(source_profile, cli, format) {
        Ok((cfg, _)) => cfg,
        Err(code) => return code,
    };
    let dst_cfg = match profile_to_provider_config(dest_profile, cli, format) {
        Ok((cfg, _)) => cfg,
        Err(code) => return code,
    };

    let mut source = match ProviderFactory::create(&src_cfg) {
        Ok(p) => p,
        Err(e) => {
            print_error(
                format,
                &format!("Failed to create source provider: {}", e),
                provider_error_to_exit_code(&e),
            );
            return provider_error_to_exit_code(&e);
        }
    };
    let mut dest = match ProviderFactory::create(&dst_cfg) {
        Ok(p) => p,
        Err(e) => {
            print_error(
                format,
                &format!("Failed to create dest provider: {}", e),
                provider_error_to_exit_code(&e),
            );
            return provider_error_to_exit_code(&e);
        }
    };

    // KE-B1 / KE-B2 / KE-B3 / KE-B4: per-backend knobs apply symmetrically to source and dest.
    apply_s3_runtime_knobs(&mut source, cli);
    apply_s3_runtime_knobs(&mut dest, cli);
    apply_onedrive_runtime_knobs(&mut source, cli);
    apply_onedrive_runtime_knobs(&mut dest, cli);
    apply_azure_runtime_knobs(&mut source, cli);
    apply_azure_runtime_knobs(&mut dest, cli);
    apply_google_drive_runtime_knobs(&mut source, cli);
    apply_google_drive_runtime_knobs(&mut dest, cli);

    if let Err(e) = source.connect().await {
        print_error(
            format,
            &format!("Source connection failed: {}", e),
            provider_error_to_exit_code(&e),
        );
        return provider_error_to_exit_code(&e);
    }
    if let Err(e) = dest.connect().await {
        print_error(
            format,
            &format!("Dest connection failed: {}", e),
            provider_error_to_exit_code(&e),
        );
        let _ = source.disconnect().await;
        return provider_error_to_exit_code(&e);
    }

    let request = CrossProfileTransferRequest {
        source_profile: source_profile.to_string(),
        dest_profile: dest_profile.to_string(),
        source_path: source_path.to_string(),
        dest_path: dest_path.to_string(),
        recursive,
        dry_run: true,
        skip_existing,
    };

    let plan = match plan_transfer(source.as_mut(), dest.as_mut(), &request).await {
        Ok(plan) => plan,
        Err(e) => {
            print_error(
                format,
                &format!("Transfer doctor failed: {}", e),
                provider_error_to_exit_code(&e),
            );
            let _ = source.disconnect().await;
            let _ = dest.disconnect().await;
            return provider_error_to_exit_code(&e);
        }
    };

    let mut existing_dest_paths = 0u64;
    for entry in &plan.entries {
        if dest.stat(&entry.dest_path).await.is_ok() {
            existing_dest_paths += 1;
        }
    }

    let mut checks = vec![
        serde_json::json!({"name": "source_connected", "ok": true, "profile": source_profile}),
        serde_json::json!({"name": "dest_connected", "ok": true, "profile": dest_profile}),
        serde_json::json!({"name": "plan_created", "ok": true, "planned_files": plan.total_files}),
    ];
    if let Some(first) = plan.entries.first() {
        checks.push(serde_json::json!({
            "name": "sample_mapping",
            "ok": true,
            "source_path": first.source_path,
            "dest_path": first.dest_path
        }));
    }

    let mut risks = Vec::new();
    push_s3_doctor_checks(&mut checks, &mut risks, "source", &src_cfg);
    push_s3_doctor_checks(&mut checks, &mut risks, "destination", &dst_cfg);
    if recursive {
        risks.push("recursive transfer enabled; entire trees may be copied".to_string());
    }
    if existing_dest_paths > 0 && !skip_existing {
        risks.push(format!(
            "{} planned destination path(s) already exist and may be overwritten",
            existing_dest_paths
        ));
    }
    if skip_existing {
        risks.push("skip-existing enabled; matching destination files will be skipped".to_string());
    }
    if plan.total_files == 0 {
        risks.push("plan contains zero files".to_string());
    }

    let result = CliDoctorResult {
        status: if plan.total_files > 0 {
            "ok"
        } else {
            "attention"
        },
        doctor: "transfer".to_string(),
        summary: serde_json::json!({
            "source_profile": source_profile,
            "dest_profile": dest_profile,
            "source_path": source_path,
            "dest_path": dest_path,
            "recursive": recursive,
            "skip_existing": skip_existing,
            "planned_files": plan.total_files,
            "total_bytes": plan.total_bytes,
            "existing_dest_paths": existing_dest_paths,
            "sample_entries": plan.entries.iter().take(5).map(|entry| serde_json::json!({
                "source_path": entry.source_path,
                "dest_path": entry.dest_path,
                "size": entry.size,
            })).collect::<Vec<_>>(),
        }),
        checks,
        risks,
        suggested_next_command: suggest_transfer_apply(
            source_profile,
            dest_profile,
            source_path,
            dest_path,
        ),
        ec_enabled: None,
        ec_level_pct: None,
        ec_estimated_sidecars: None,
        ec_estimated_overhead_bytes: None,
        ec_skipped_too_large: None,
        ec_skipped_low_benefit: None,
        ec_max_file_size: None,
    };

    match format {
        OutputFormat::Json => print_json(&result),
        OutputFormat::Text => {
            println!("Transfer doctor");
            println!("  Planned files: {}", plan.total_files);
            println!("  Total bytes: {}", format_size(plan.total_bytes));
            println!("  Existing destination paths: {}", existing_dest_paths);
            if !result.risks.is_empty() {
                println!("  Risks:");
                for risk in &result.risks {
                    println!("    - {}", risk);
                }
            }
            if !cli.quiet {
                eprintln!("Next: {}", result.suggested_next_command);
            }
        }
    }

    let _ = source.disconnect().await;
    let _ = dest.disconnect().await;
    if plan.total_files > 0 {
        0
    } else {
        4
    }
}

#[allow(clippy::too_many_arguments)]
async fn cmd_transfer_profiles(
    source_profile: &str,
    dest_profile: &str,
    source_path: &str,
    dest_path: &str,
    recursive: bool,
    dry_run: bool,
    skip_existing: bool,
    cli: &Cli,
    format: OutputFormat,
    cancelled: Arc<AtomicBool>,
) -> i32 {
    use ftp_client_gui_lib::cross_profile_transfer::{plan_transfer, CrossProfileTransferRequest};

    let quiet = cli.quiet || matches!(format, OutputFormat::Json);

    // Resolve source profile
    let src_cfg = match profile_to_provider_config(source_profile, cli, format) {
        Ok((cfg, _)) => cfg,
        Err(code) => return code,
    };
    // Resolve destination profile
    let dst_cfg = match profile_to_provider_config(dest_profile, cli, format) {
        Ok((cfg, _)) => cfg,
        Err(code) => return code,
    };

    // Create providers
    let mut source = match ProviderFactory::create(&src_cfg) {
        Ok(p) => p,
        Err(e) => {
            print_error(
                format,
                &format!("Failed to create source provider: {}", e),
                provider_error_to_exit_code(&e),
            );
            return provider_error_to_exit_code(&e);
        }
    };
    let mut dest = match ProviderFactory::create(&dst_cfg) {
        Ok(p) => p,
        Err(e) => {
            print_error(
                format,
                &format!("Failed to create dest provider: {}", e),
                provider_error_to_exit_code(&e),
            );
            return provider_error_to_exit_code(&e);
        }
    };

    // KE-B1 / KE-B2 / KE-B3 / KE-B4: per-backend knobs apply symmetrically to source and dest.
    apply_s3_runtime_knobs(&mut source, cli);
    apply_s3_runtime_knobs(&mut dest, cli);
    apply_onedrive_runtime_knobs(&mut source, cli);
    apply_onedrive_runtime_knobs(&mut dest, cli);
    apply_azure_runtime_knobs(&mut source, cli);
    apply_azure_runtime_knobs(&mut dest, cli);
    apply_google_drive_runtime_knobs(&mut source, cli);
    apply_google_drive_runtime_knobs(&mut dest, cli);

    // Connect source
    if !quiet {
        eprintln!("Connecting to source profile '{}'...", source_profile);
    }
    if let Err(e) = source.connect().await {
        print_error(
            format,
            &format!("Source connection failed: {}", e),
            provider_error_to_exit_code(&e),
        );
        return provider_error_to_exit_code(&e);
    }

    // Connect destination
    if !quiet {
        eprintln!("Connecting to dest profile '{}'...", dest_profile);
    }
    if let Err(e) = dest.connect().await {
        print_error(
            format,
            &format!("Dest connection failed: {}", e),
            provider_error_to_exit_code(&e),
        );
        let _ = source.disconnect().await;
        return provider_error_to_exit_code(&e);
    }

    // Build request
    let request = CrossProfileTransferRequest {
        source_profile: source_profile.to_string(),
        dest_profile: dest_profile.to_string(),
        source_path: source_path.to_string(),
        dest_path: dest_path.to_string(),
        recursive,
        dry_run,
        skip_existing,
    };

    // Plan
    if !quiet {
        eprintln!("Planning transfer...");
    }
    let plan = match plan_transfer(source.as_mut(), dest.as_mut(), &request).await {
        Ok(p) => p,
        Err(e) => {
            print_error(
                format,
                &format!("Planning failed: {}", e),
                provider_error_to_exit_code(&e),
            );
            let _ = source.disconnect().await;
            let _ = dest.disconnect().await;
            return provider_error_to_exit_code(&e);
        }
    };

    if cancelled.load(std::sync::atomic::Ordering::Relaxed) {
        if !quiet {
            eprintln!("Transfer cancelled.");
        }
        let _ = source.disconnect().await;
        let _ = dest.disconnect().await;
        return 130;
    }

    if plan.entries.is_empty() {
        if !quiet {
            eprintln!("Nothing to transfer.");
            eprintln!(
                "Next: {}",
                suggest_transfer_verify(dest_profile, dest_path, 0)
            );
        }
        if matches!(format, OutputFormat::Json) {
            print_json(&serde_json::json!({
                "source_profile": source_profile,
                "dest_profile": dest_profile,
                "planned_files": 0,
                "transferred_files": 0,
                "skipped_files": 0,
                "failed_files": 0,
                "total_bytes": 0,
                "duration_ms": 0,
                "dry_run": dry_run,
                "suggested_next_command": suggest_transfer_verify(dest_profile, dest_path, 0),
            }));
        }
        let _ = source.disconnect().await;
        let _ = dest.disconnect().await;
        return 0;
    }

    // Dry-run: print plan and exit
    if dry_run {
        if !quiet {
            eprintln!(
                "DRY RUN: {} file(s), {} total",
                plan.total_files,
                format_size(plan.total_bytes)
            );
            for entry in &plan.entries {
                eprintln!(
                    "  {} -> {} ({})",
                    entry.source_path,
                    entry.dest_path,
                    format_size(entry.size)
                );
            }
            eprintln!(
                "Next: {}",
                suggest_transfer_apply(source_profile, dest_profile, source_path, dest_path)
            );
        }
        if matches!(format, OutputFormat::Json) {
            print_json(&serde_json::json!({
                "plan": plan,
                "suggested_next_command": suggest_transfer_apply(
                    source_profile,
                    dest_profile,
                    source_path,
                    dest_path
                ),
            }));
        }
        let _ = source.disconnect().await;
        let _ = dest.disconnect().await;
        return 0;
    }

    let summary = execute_cross_profile_plan(
        source.as_mut(),
        dest.as_mut(),
        &plan,
        skip_existing,
        cli,
        quiet,
        cancelled.clone(),
    )
    .await;

    if !quiet {
        eprintln!(
            "Done: {} transferred, {} skipped, {} failed ({}, {:.1}s)",
            summary.transferred_files,
            summary.skipped_files,
            summary.failed_files,
            format_size(summary.total_bytes),
            summary.duration_ms as f64 / 1000.0
        );
        eprintln!(
            "Next: {}",
            suggest_transfer_verify(dest_profile, dest_path, summary.planned_files)
        );
    }
    if matches!(format, OutputFormat::Json) {
        print_json(&serde_json::json!({
            "source_profile": summary.source_profile,
            "dest_profile": summary.dest_profile,
            "planned_files": summary.planned_files,
            "transferred_files": summary.transferred_files,
            "skipped_files": summary.skipped_files,
            "failed_files": summary.failed_files,
            "total_bytes": summary.total_bytes,
            "duration_ms": summary.duration_ms,
            "dry_run": summary.dry_run,
            "suggested_next_command": suggest_transfer_verify(
                dest_profile,
                dest_path,
                summary.planned_files
            ),
        }));
    }

    let _ = source.disconnect().await;
    let _ = dest.disconnect().await;

    if cancelled.load(std::sync::atomic::Ordering::Relaxed) {
        return 130;
    }

    if summary.failed_files > 0 {
        4
    } else {
        0
    }
}

#[derive(Serialize)]
struct TransferCliSummary {
    source_profile: String,
    dest_profile: String,
    planned_files: u64,
    transferred_files: u64,
    skipped_files: u64,
    failed_files: u64,
    total_bytes: u64,
    duration_ms: u64,
    dry_run: bool,
}

async fn execute_cross_profile_plan(
    source: &mut dyn StorageProvider,
    dest: &mut dyn StorageProvider,
    plan: &ftp_client_gui_lib::cross_profile_transfer::CrossProfileTransferPlan,
    skip_existing: bool,
    cli: &Cli,
    quiet: bool,
    cancelled: Arc<AtomicBool>,
) -> TransferCliSummary {
    use ftp_client_gui_lib::cross_profile_transfer::{copy_one_file, should_skip_existing};

    let total = plan.entries.len();
    let max_attempts = cli.retries.max(1);
    let sleep_dur = parse_retry_sleep(&cli.retries_sleep);
    let start = std::time::Instant::now();
    let mut transferred: u64 = 0;
    let mut skipped: u64 = 0;
    let mut failed: u64 = 0;
    let mut bytes_transferred: u64 = 0;

    if !quiet {
        eprintln!(
            "Transferring {} file(s), {} total...",
            total,
            format_size(plan.total_bytes)
        );
    }

    for (idx, entry) in plan.entries.iter().enumerate() {
        if cancelled.load(std::sync::atomic::Ordering::Relaxed) {
            if !quiet {
                eprintln!("Transfer cancelled.");
            }
            break;
        }

        if skip_existing {
            match should_skip_existing(dest, &entry.dest_path, entry).await {
                Ok(true) => {
                    skipped += 1;
                    if !quiet {
                        eprintln!(
                            "  [{}/{}] {} ... SKIPPED (exists)",
                            idx + 1,
                            total,
                            entry.display_name
                        );
                    }
                    continue;
                }
                Ok(false) => {}
                Err(e) => {
                    if !quiet {
                        eprintln!(
                            "  [{}/{}] {} skip-existing check failed: {}, transferring anyway",
                            idx + 1,
                            total,
                            entry.display_name,
                            e
                        );
                    }
                }
            }
        }

        if !quiet {
            eprint!(
                "  [{}/{}] {} ({}) ... ",
                idx + 1,
                total,
                entry.display_name,
                format_size(entry.size)
            );
        }

        let mut file_ok = false;
        for attempt in 1..=max_attempts {
            match copy_one_file(
                source,
                dest,
                &entry.source_path,
                &entry.dest_path,
                entry.modified.as_deref(),
            )
            .await
            {
                Ok(()) => {
                    file_ok = true;
                    break;
                }
                Err(e) => {
                    let code = provider_error_to_exit_code(&e);
                    if !is_retryable_exit(code) || attempt == max_attempts {
                        if !quiet {
                            eprintln!("FAILED: {}", e);
                        }
                        break;
                    }
                    if !quiet {
                        eprintln!(
                            "attempt {}/{} failed ({}), retrying in {:?}...",
                            attempt, max_attempts, e, sleep_dur
                        );
                        eprint!(
                            "  [{}/{}] {} ({}) ... ",
                            idx + 1,
                            total,
                            entry.display_name,
                            format_size(entry.size)
                        );
                    }
                    if !sleep_dur.is_zero() {
                        tokio::time::sleep(sleep_dur).await;
                    }
                }
            }
        }

        if file_ok {
            transferred += 1;
            bytes_transferred += entry.size;
            if !quiet {
                eprintln!("OK");
            }
        } else {
            failed += 1;
        }
    }

    TransferCliSummary {
        source_profile: plan.source_profile.clone(),
        dest_profile: plan.dest_profile.clone(),
        planned_files: total as u64,
        transferred_files: transferred,
        skipped_files: skipped,
        failed_files: failed,
        total_bytes: bytes_transferred,
        duration_ms: start.elapsed().as_millis() as u64,
        dry_run: false,
    }
}

/// Resolve a profile name, create a provider, and connect it.
/// Used by batch CONNECT_SOURCE_PROFILE / CONNECT_DEST_PROFILE.
async fn batch_connect_profile(
    profile_name: &str,
    cli: &Cli,
    format: OutputFormat,
) -> Result<Box<dyn StorageProvider>, i32> {
    let (cfg, _) = profile_to_provider_config(profile_name, cli, format)?;
    let mut provider = ProviderFactory::create(&cfg).map_err(|e| {
        print_error(
            format,
            &format!("Failed to create provider for '{}': {}", profile_name, e),
            provider_error_to_exit_code(&e),
        );
        provider_error_to_exit_code(&e)
    })?;
    // KE-B1 / KE-B2 / KE-B3 / KE-B4: apply per-backend knobs before connect.
    apply_s3_runtime_knobs(&mut provider, cli);
    apply_onedrive_runtime_knobs(&mut provider, cli);
    apply_azure_runtime_knobs(&mut provider, cli);
    apply_google_drive_runtime_knobs(&mut provider, cli);
    provider.connect().await.map_err(|e| {
        print_error(
            format,
            &format!("Connection failed for '{}': {}", profile_name, e),
            provider_error_to_exit_code(&e),
        );
        provider_error_to_exit_code(&e)
    })?;
    Ok(provider)
}

// ── Audit subcommand (M3) ──────────────────────────────────────────

#[derive(Copy, Clone, Debug, PartialEq, Eq, PartialOrd, Ord, Serialize)]
#[serde(rename_all = "lowercase")]
enum AuditStatus {
    Ok,
    Warning,
    Critical,
    Error,
}

#[derive(Serialize)]
struct AuditResult {
    server: String,
    protocol: String,
    host: String,
    status: AuditStatus,
    #[serde(skip_serializing_if = "Option::is_none")]
    message: Option<String>,
    #[serde(flatten)]
    details: serde_json::Value,
}

#[derive(Serialize)]
struct AuditReport {
    audit: String,
    timestamp: String,
    servers_checked: usize,
    servers_ok: usize,
    servers_warning: usize,
    servers_critical: usize,
    servers_error: usize,
    results: Vec<AuditResult>,
}

/// Filter saved vault profiles by glob match against the `name` field.
///
/// `pattern` defaults to "all" (alias for "*"), in which case all profiles
/// are returned. Patterns containing path traversal characters (`/`, `..`,
/// or NUL) are rejected as a safety measure: profile names are simple
/// identifiers, not paths.
fn match_servers_glob(
    profiles: &[serde_json::Value],
    pattern: &str,
) -> Result<Vec<serde_json::Value>, String> {
    let trimmed = pattern.trim();
    if trimmed.is_empty() {
        return Err("Empty server glob".to_string());
    }
    if trimmed.contains('/') || trimmed.contains("..") || trimmed.contains('\0') {
        return Err(format!(
            "Invalid characters in server glob '{}'. Profile names cannot contain '/', '..', or NUL.",
            trimmed
        ));
    }
    let effective = if trimmed.eq_ignore_ascii_case("all") {
        "*"
    } else {
        trimmed
    };
    let matcher = globset::Glob::new(effective)
        .map_err(|e| format!("Invalid server glob '{}': {}", trimmed, e))?
        .compile_matcher();
    Ok(profiles
        .iter()
        .filter(|p| {
            let name = p.get("name").and_then(|v| v.as_str()).unwrap_or("");
            matcher.is_match(name)
        })
        .cloned()
        .collect())
}

/// Open the vault, read `config_server_profiles`, filter by glob.
///
/// Returns `Err(exit_code)` for vault errors, parse errors, or invalid glob.
fn enumerate_audit_targets(
    cli: &Cli,
    glob: &str,
    format: OutputFormat,
) -> Result<Vec<serde_json::Value>, i32> {
    let store = open_vault(cli).map_err(|e| {
        print_error(format, &e, 5);
        5
    })?;
    let profiles = match load_active_user_profiles(cli, &store) {
        Ok(p) => p,
        Err(e) if e == "USER_LOCKED" || e == "NO_ACTIVE_USER" => {
            print_error(format, &e, 6);
            return Err(6);
        }
        Err(_) => Vec::new(),
    };
    match_servers_glob(&profiles, glob).map_err(|e| {
        print_error(format, &e, 3);
        3
    })
}

/// Build an `AuditResult` for an Error outcome with no body details.
fn audit_result_error(profile: &serde_json::Value, message: String) -> AuditResult {
    AuditResult {
        server: profile
            .get("name")
            .and_then(|v| v.as_str())
            .unwrap_or("unnamed")
            .to_string(),
        protocol: profile
            .get("protocol")
            .and_then(|v| v.as_str())
            .unwrap_or("?")
            .to_string(),
        host: profile
            .get("host")
            .and_then(|v| v.as_str())
            .unwrap_or("")
            .to_string(),
        status: AuditStatus::Error,
        message: Some(message),
        details: serde_json::Value::Object(serde_json::Map::new()),
    }
}

/// Profile name + protocol + host snapshot for AuditResult construction.
struct AuditTargetMeta {
    name: String,
    protocol: String,
    host: String,
}

impl AuditTargetMeta {
    fn from_profile(profile: &serde_json::Value) -> Self {
        Self {
            name: profile
                .get("name")
                .and_then(|v| v.as_str())
                .unwrap_or("unnamed")
                .to_string(),
            protocol: profile
                .get("protocol")
                .and_then(|v| v.as_str())
                .unwrap_or("?")
                .to_string(),
            host: profile
                .get("host")
                .and_then(|v| v.as_str())
                .unwrap_or("")
                .to_string(),
        }
    }
}

/// Aggregate `AuditResult` list into a final `AuditReport` with severity counts.
fn aggregate_audit_report(audit: &str, results: Vec<AuditResult>) -> AuditReport {
    let mut servers_ok = 0;
    let mut servers_warning = 0;
    let mut servers_critical = 0;
    let mut servers_error = 0;
    for r in &results {
        match r.status {
            AuditStatus::Ok => servers_ok += 1,
            AuditStatus::Warning => servers_warning += 1,
            AuditStatus::Critical => servers_critical += 1,
            AuditStatus::Error => servers_error += 1,
        }
    }
    let timestamp = chrono::Utc::now().to_rfc3339();
    AuditReport {
        audit: audit.to_string(),
        timestamp,
        servers_checked: results.len(),
        servers_ok,
        servers_warning,
        servers_critical,
        servers_error,
        results,
    }
}

/// Compute the worst-severity exit code for an `AuditReport`.
///
/// 0 = all OK, 1 = at least one warning, 2 = at least one critical or error.
/// `exit_code_flag` (when set) forces 0 regardless of severity.
fn audit_report_exit_code(report: &AuditReport, exit_code_flag: bool) -> i32 {
    if exit_code_flag {
        return 0;
    }
    if report.servers_critical > 0 || report.servers_error > 0 {
        2
    } else if report.servers_warning > 0 {
        1
    } else {
        0
    }
}

/// Print the audit report in JSON or markdown form, return the exit code.
fn emit_audit_report(report: &AuditReport, markdown: bool, exit_code_flag: bool) -> i32 {
    if markdown {
        let mut out = String::new();
        out.push_str(&format!("# Audit: {}\n\n", report.audit));
        out.push_str(&format!("Timestamp: {}\n\n", report.timestamp));
        out.push_str(&format!(
            "Servers checked: {} (ok: {}, warning: {}, critical: {}, error: {})\n\n",
            report.servers_checked,
            report.servers_ok,
            report.servers_warning,
            report.servers_critical,
            report.servers_error,
        ));
        out.push_str("| Server | Protocol | Host | Status | Message |\n");
        out.push_str("|---|---|---|---|---|\n");
        for r in &report.results {
            let status = match r.status {
                AuditStatus::Ok => "ok",
                AuditStatus::Warning => "warning",
                AuditStatus::Critical => "critical",
                AuditStatus::Error => "error",
            };
            let msg = r.message.as_deref().unwrap_or("");
            // Markdown table cells: escape `|` and newlines.
            let safe_msg = msg.replace('|', "\\|").replace('\n', " ");
            out.push_str(&format!(
                "| {} | {} | {} | {} | {} |\n",
                r.server, r.protocol, r.host, status, safe_msg,
            ));
        }
        println!("{}", out);
    } else {
        match serde_json::to_string_pretty(report) {
            Ok(s) => println!("{}", s),
            Err(e) => {
                eprintln!("Failed to serialize audit report: {}", e);
                return 99;
            }
        }
    }
    audit_report_exit_code(report, exit_code_flag)
}

/// Resolve `min_size` shorthand into bytes, e.g. "1K" → 1024.
fn parse_audit_min_size(s: &str) -> Result<u64, String> {
    parse_size_filter(s)
}

/// Build a connected provider for a given audit profile, applying CLI overrides.
async fn audit_connect_profile(
    profile: &serde_json::Value,
    cli: &Cli,
    format: OutputFormat,
) -> Result<Box<dyn StorageProvider>, String> {
    let name = profile
        .get("name")
        .and_then(|v| v.as_str())
        .unwrap_or("unnamed")
        .to_string();
    let (cfg, _) = profile_to_provider_config(&name, cli, format)
        .map_err(|_code| "profile resolution failed".to_string())?;
    let mut provider =
        ProviderFactory::create(&cfg).map_err(|e| format!("provider creation failed: {}", e))?;
    // KE-B1 / KE-B2 / KE-B3 / KE-B4: apply per-backend knobs before connect.
    apply_s3_runtime_knobs(&mut provider, cli);
    apply_onedrive_runtime_knobs(&mut provider, cli);
    apply_azure_runtime_knobs(&mut provider, cli);
    apply_google_drive_runtime_knobs(&mut provider, cli);
    provider
        .connect()
        .await
        .map_err(|e| format!("connection failed: {}", e))?;
    Ok(provider)
}

/// Compute the percent (0-100) of a `(used, total)` quota, preserving fractions.
fn quota_pct(used: u64, total: u64) -> Option<f64> {
    if total == 0 {
        None
    } else {
        Some((used as f64 / total as f64) * 100.0)
    }
}

/// Parse an ISO 8601 / RFC 3339 timestamp into UNIX seconds. Falls back to
/// `None` for unparseable input.
fn parse_iso8601_to_unix(s: &str) -> Option<i64> {
    chrono::DateTime::parse_from_rfc3339(s)
        .ok()
        .map(|dt| dt.timestamp())
        .or_else(|| {
            // Tolerate trailing space or Z-less variants used by some providers.
            chrono::NaiveDateTime::parse_from_str(s, "%Y-%m-%dT%H:%M:%S")
                .ok()
                .map(|ndt| ndt.and_utc().timestamp())
        })
}

/// Convert UNIX seconds to RFC 3339 string for inclusion in audit details.
fn unix_to_rfc3339(ts: i64) -> Option<String> {
    chrono::DateTime::<chrono::Utc>::from_timestamp(ts, 0).map(|dt| dt.to_rfc3339())
}

#[allow(clippy::too_many_arguments)]
async fn cmd_audit(command: &AuditCommands, cli: &Cli, format: OutputFormat) -> i32 {
    match command {
        AuditCommands::StorageQuota {
            servers,
            threshold,
            timeout,
            parallel,
            markdown,
            exit_code,
        } => {
            run_audit_storage_quota(
                cli, format, servers, *threshold, *timeout, *parallel, *markdown, *exit_code,
            )
            .await
        }
        AuditCommands::BackupFreshness {
            servers,
            path,
            max_age_hours,
            pattern,
            timeout,
            parallel,
            markdown,
            exit_code,
        } => {
            run_audit_backup_freshness(
                cli,
                format,
                servers,
                path,
                *max_age_hours,
                pattern.as_deref(),
                *timeout,
                *parallel,
                *markdown,
                *exit_code,
            )
            .await
        }
        AuditCommands::FileExists {
            servers,
            path,
            min_size,
            timeout,
            parallel,
            markdown,
            exit_code,
        } => {
            run_audit_file_exists(
                cli,
                format,
                servers,
                path,
                min_size.as_deref(),
                *timeout,
                *parallel,
                *markdown,
                *exit_code,
            )
            .await
        }
    }
}

#[allow(clippy::too_many_arguments)]
async fn run_audit_storage_quota(
    cli: &Cli,
    format: OutputFormat,
    servers: &str,
    threshold: f64,
    timeout: u64,
    parallel: usize,
    markdown: bool,
    exit_code_flag: bool,
) -> i32 {
    if !(0.0..=100.0).contains(&threshold) {
        print_error(format, "--threshold must be between 0 and 100", 3);
        return 3;
    }
    let parallel = parallel.clamp(1, 16);
    let targets = match enumerate_audit_targets(cli, servers, format) {
        Ok(t) => t,
        Err(code) => return code,
    };
    let timeout_dur = std::time::Duration::from_secs(timeout.max(1));

    let futures = targets.into_iter().map(|profile| {
        let cli_ref = cli;
        async move {
            let meta = AuditTargetMeta::from_profile(&profile);
            let work = async {
                let mut provider = match audit_connect_profile(&profile, cli_ref, format).await {
                    Ok(p) => p,
                    Err(e) => return audit_result_error(&profile, e),
                };
                let outcome = provider.storage_info().await;
                let _ = provider.disconnect().await;
                match outcome {
                    Ok(info) => {
                        let pct = quota_pct(info.used, info.total);
                        let (status, msg) = match pct {
                            None => (
                                AuditStatus::Error,
                                Some("storage quota not available (total = 0)".to_string()),
                            ),
                            Some(p) if p > threshold => (
                                AuditStatus::Warning,
                                Some(format!(
                                    "{:.1}% used exceeds threshold {:.1}%",
                                    p, threshold
                                )),
                            ),
                            Some(p) => (
                                AuditStatus::Ok,
                                Some(format!("{:.1}% used (threshold {:.1}%)", p, threshold)),
                            ),
                        };
                        AuditResult {
                            server: meta.name.clone(),
                            protocol: meta.protocol.clone(),
                            host: meta.host.clone(),
                            status,
                            message: msg,
                            details: serde_json::json!({
                                "used": info.used,
                                "total": info.total,
                                "free": info.free,
                                "percent": pct,
                                "threshold": threshold,
                            }),
                        }
                    }
                    Err(ProviderError::NotSupported(_)) => AuditResult {
                        server: meta.name.clone(),
                        protocol: meta.protocol.clone(),
                        host: meta.host.clone(),
                        status: AuditStatus::Error,
                        message: Some(format!(
                            "storage quota not supported by protocol {}",
                            meta.protocol
                        )),
                        details: serde_json::Value::Object(serde_json::Map::new()),
                    },
                    Err(e) => AuditResult {
                        server: meta.name.clone(),
                        protocol: meta.protocol.clone(),
                        host: meta.host.clone(),
                        status: AuditStatus::Error,
                        message: Some(format!("quota query failed: {}", e)),
                        details: serde_json::Value::Object(serde_json::Map::new()),
                    },
                }
            };
            match tokio::time::timeout(timeout_dur, work).await {
                Ok(r) => r,
                Err(_) => audit_result_error(
                    &profile,
                    format!("audit timed out after {}s", timeout_dur.as_secs()),
                ),
            }
        }
    });

    let mut stream = futures_util::stream::iter(futures).buffer_unordered(parallel);
    let mut results: Vec<AuditResult> = Vec::new();
    while let Some(r) = futures_util::StreamExt::next(&mut stream).await {
        results.push(r);
    }
    results.sort_by(|a, b| a.server.cmp(&b.server));
    let report = aggregate_audit_report("storage-quota", results);
    emit_audit_report(&report, markdown, exit_code_flag)
}

#[allow(clippy::too_many_arguments)]
async fn run_audit_backup_freshness(
    cli: &Cli,
    format: OutputFormat,
    servers: &str,
    path: &str,
    max_age_hours: f64,
    pattern: Option<&str>,
    timeout: u64,
    parallel: usize,
    markdown: bool,
    exit_code_flag: bool,
) -> i32 {
    if max_age_hours <= 0.0 || !max_age_hours.is_finite() {
        print_error(
            format,
            "--max-age-hours must be a positive finite number",
            3,
        );
        return 3;
    }
    let parallel = parallel.clamp(1, 16);
    let matcher: Option<globset::GlobMatcher> = match pattern {
        Some(p) => match globset::Glob::new(p) {
            Ok(g) => Some(g.compile_matcher()),
            Err(e) => {
                print_error(format, &format!("Invalid --pattern '{}': {}", p, e), 3);
                return 3;
            }
        },
        None => None,
    };
    let targets = match enumerate_audit_targets(cli, servers, format) {
        Ok(t) => t,
        Err(code) => return code,
    };
    let timeout_dur = std::time::Duration::from_secs(timeout.max(1));
    let path_owned = path.to_string();
    let pattern_owned = pattern.map(|s| s.to_string());

    let futures = targets.into_iter().map(|profile| {
        let cli_ref = cli;
        let path_ref = path_owned.clone();
        let pattern_ref = pattern_owned.clone();
        let matcher_ref = matcher.clone();
        async move {
            let meta = AuditTargetMeta::from_profile(&profile);
            let work = async {
                let mut provider = match audit_connect_profile(&profile, cli_ref, format).await {
                    Ok(p) => p,
                    Err(e) => return audit_result_error(&profile, e),
                };
                let entries = provider.list(&path_ref).await;
                let _ = provider.disconnect().await;
                match entries {
                    Ok(items) => {
                        let filtered: Vec<&RemoteEntry> = items
                            .iter()
                            .filter(|e| !e.is_dir)
                            .filter(|e| match &matcher_ref {
                                Some(m) => m.is_match(&e.name),
                                None => true,
                            })
                            .collect();
                        if filtered.is_empty() {
                            return AuditResult {
                                server: meta.name.clone(),
                                protocol: meta.protocol.clone(),
                                host: meta.host.clone(),
                                status: AuditStatus::Warning,
                                message: Some(match &pattern_ref {
                                    Some(p) => {
                                        format!("no backups matching '{}' in {}", p, path_ref)
                                    }
                                    None => format!("no backups found in {}", path_ref),
                                }),
                                details: serde_json::json!({
                                    "path": path_ref,
                                    "pattern": pattern_ref,
                                    "max_age_hours": max_age_hours,
                                    "files_listed": items.len(),
                                    "files_matching": 0,
                                }),
                            };
                        }
                        let now_unix = chrono::Utc::now().timestamp();
                        let mut newest_unix: Option<i64> = None;
                        let mut newest_name: Option<String> = None;
                        for e in &filtered {
                            if let Some(m) = e.modified.as_deref().and_then(parse_iso8601_to_unix) {
                                if newest_unix.is_none_or(|cur| m > cur) {
                                    newest_unix = Some(m);
                                    newest_name = Some(e.name.clone());
                                }
                            }
                        }
                        match newest_unix {
                            None => AuditResult {
                                server: meta.name.clone(),
                                protocol: meta.protocol.clone(),
                                host: meta.host.clone(),
                                status: AuditStatus::Warning,
                                message: Some(format!(
                                    "no parsable mtimes among {} files in {}",
                                    filtered.len(),
                                    path_ref
                                )),
                                details: serde_json::json!({
                                    "path": path_ref,
                                    "pattern": pattern_ref,
                                    "max_age_hours": max_age_hours,
                                    "files_matching": filtered.len(),
                                }),
                            },
                            Some(ts) => {
                                let age_seconds = (now_unix - ts).max(0);
                                let age_hours = age_seconds as f64 / 3600.0;
                                let (status, msg) = if age_hours > max_age_hours {
                                    (
                                        AuditStatus::Warning,
                                        Some(format!(
                                            "newest backup is {:.1}h old (max {:.1}h)",
                                            age_hours, max_age_hours
                                        )),
                                    )
                                } else {
                                    (
                                        AuditStatus::Ok,
                                        Some(format!(
                                            "newest backup is {:.1}h old (within {:.1}h)",
                                            age_hours, max_age_hours
                                        )),
                                    )
                                };
                                AuditResult {
                                    server: meta.name.clone(),
                                    protocol: meta.protocol.clone(),
                                    host: meta.host.clone(),
                                    status,
                                    message: msg,
                                    details: serde_json::json!({
                                        "path": path_ref,
                                        "pattern": pattern_ref,
                                        "max_age_hours": max_age_hours,
                                        "newest_file": newest_name,
                                        "newest_mtime": unix_to_rfc3339(ts),
                                        "age_hours": age_hours,
                                        "files_matching": filtered.len(),
                                    }),
                                }
                            }
                        }
                    }
                    Err(e) => audit_result_error(&profile, format!("list failed: {}", e)),
                }
            };
            match tokio::time::timeout(timeout_dur, work).await {
                Ok(r) => r,
                Err(_) => audit_result_error(
                    &profile,
                    format!("audit timed out after {}s", timeout_dur.as_secs()),
                ),
            }
        }
    });

    let mut stream = futures_util::stream::iter(futures).buffer_unordered(parallel);
    let mut results: Vec<AuditResult> = Vec::new();
    while let Some(r) = futures_util::StreamExt::next(&mut stream).await {
        results.push(r);
    }
    results.sort_by(|a, b| a.server.cmp(&b.server));
    let report = aggregate_audit_report("backup-freshness", results);
    emit_audit_report(&report, markdown, exit_code_flag)
}

#[allow(clippy::too_many_arguments)]
async fn run_audit_file_exists(
    cli: &Cli,
    format: OutputFormat,
    servers: &str,
    path: &str,
    min_size: Option<&str>,
    timeout: u64,
    parallel: usize,
    markdown: bool,
    exit_code_flag: bool,
) -> i32 {
    let min_size_bytes: Option<u64> = match min_size {
        Some(s) => match parse_audit_min_size(s) {
            Ok(v) => Some(v),
            Err(e) => {
                print_error(format, &format!("Invalid --min-size '{}': {}", s, e), 3);
                return 3;
            }
        },
        None => None,
    };
    let parallel = parallel.clamp(1, 16);
    let targets = match enumerate_audit_targets(cli, servers, format) {
        Ok(t) => t,
        Err(code) => return code,
    };
    let timeout_dur = std::time::Duration::from_secs(timeout.max(1));
    let path_owned = path.to_string();

    let futures = targets.into_iter().map(|profile| {
        let cli_ref = cli;
        let path_ref = path_owned.clone();
        async move {
            let meta = AuditTargetMeta::from_profile(&profile);
            let work = async {
                let mut provider = match audit_connect_profile(&profile, cli_ref, format).await {
                    Ok(p) => p,
                    Err(e) => return audit_result_error(&profile, e),
                };
                let outcome = provider.stat(&path_ref).await;
                let _ = provider.disconnect().await;
                match outcome {
                    Ok(entry) => {
                        let (status, msg) = match min_size_bytes {
                            Some(min) if entry.size < min => (
                                AuditStatus::Warning,
                                Some(format!(
                                    "file is {} bytes, below min {} bytes",
                                    entry.size, min
                                )),
                            ),
                            _ => (
                                AuditStatus::Ok,
                                Some(format!("file present ({} bytes)", entry.size)),
                            ),
                        };
                        AuditResult {
                            server: meta.name.clone(),
                            protocol: meta.protocol.clone(),
                            host: meta.host.clone(),
                            status,
                            message: msg,
                            details: serde_json::json!({
                                "path": path_ref,
                                "size": entry.size,
                                "min_size": min_size_bytes,
                                "modified": entry.modified,
                                "is_dir": entry.is_dir,
                            }),
                        }
                    }
                    Err(ProviderError::NotFound(_)) => AuditResult {
                        server: meta.name.clone(),
                        protocol: meta.protocol.clone(),
                        host: meta.host.clone(),
                        status: AuditStatus::Critical,
                        message: Some(format!("file not found: {}", path_ref)),
                        details: serde_json::json!({
                            "path": path_ref,
                            "min_size": min_size_bytes,
                        }),
                    },
                    Err(e) => audit_result_error(&profile, format!("stat failed: {}", e)),
                }
            };
            match tokio::time::timeout(timeout_dur, work).await {
                Ok(r) => r,
                Err(_) => audit_result_error(
                    &profile,
                    format!("audit timed out after {}s", timeout_dur.as_secs()),
                ),
            }
        }
    });

    let mut stream = futures_util::stream::iter(futures).buffer_unordered(parallel);
    let mut results: Vec<AuditResult> = Vec::new();
    while let Some(r) = futures_util::StreamExt::next(&mut stream).await {
        results.push(r);
    }
    results.sort_by(|a, b| a.server.cmp(&b.server));
    let report = aggregate_audit_report("file-exists", results);
    emit_audit_report(&report, markdown, exit_code_flag)
}

async fn cmd_batch(file: &str, cli: &Cli, format: OutputFormat, cancelled: Arc<AtomicBool>) -> i32 {
    // The `.aeroftp` extension is the canonical profile-export format
    // and is unrelated to batch scripts (issue #225). Reject it here
    // with a rename hint instead of silently reading a file that the
    // user almost certainly produced from the GUI export flow.
    // `-` (stdin) and any other extension are accepted.
    if file != "-" && file.to_ascii_lowercase().ends_with(".aeroftp") {
        print_error(
            format,
            &format!(
                "Refusing to execute '{}': the .aeroftp extension is reserved for profile-export backups. Rename your script to .aeroftp-script (or pipe it through stdin with `-`) and retry.",
                file
            ),
            5,
        );
        return 5;
    }

    let content = if file == "-" {
        let mut stdin = String::new();
        if let Err(e) = io::stdin().read_to_string(&mut stdin) {
            print_error(
                format,
                &format!("Cannot read batch script from stdin: {}", e),
                2,
            );
            return 2;
        }
        stdin
    } else {
        match std::fs::read_to_string(file) {
            Ok(c) => c,
            Err(e) => {
                print_error(
                    format,
                    &format!("Cannot read batch file '{}': {}", file, e),
                    2,
                );
                return 2;
            }
        }
    };

    // Limit batch file size to 1 MB
    if content.len() > 1_048_576 {
        print_error(format, "Batch file exceeds 1 MB limit", 5);
        return 5;
    }

    let mut variables: HashMap<String, String> = HashMap::new();
    let mut current_url: Option<String> = None;
    let mut exit_code = 0;
    let mut on_error_continue = false;
    let mut total_commands: u32 = 0;
    let mut failed_commands: u32 = 0;

    // Cross-profile transfer state (CONNECT_SOURCE_PROFILE / CONNECT_DEST_PROFILE / TRANSFER)
    let mut cross_source: Option<(Box<dyn StorageProvider>, String)> = None; // (provider, profile_name)
    let mut cross_dest: Option<(Box<dyn StorageProvider>, String)> = None;

    /// Check exit code and handle ON_ERROR policy.
    /// Returns Some(exit_code) if batch should abort, None to continue.
    fn check_exit(
        code: i32,
        line_num: usize,
        cmd: &str,
        on_error_continue: bool,
        failed_commands: &mut u32,
    ) -> Option<i32> {
        if code != 0 {
            if on_error_continue {
                eprintln!(
                    "Warning: line {} ({}) failed with exit code {} (continuing)",
                    line_num + 1,
                    cmd,
                    code
                );
                *failed_commands += 1;
                None
            } else {
                eprintln!(
                    "Batch failed at line {} ({}): exit code {}",
                    line_num + 1,
                    cmd,
                    code
                );
                Some(code)
            }
        } else {
            None
        }
    }

    /// Require an active connection URL, or return error.
    fn require_url(current_url: &Option<String>, line_num: usize) -> Result<String, i32> {
        match current_url {
            Some(u) => Ok(u.clone()),
            None => {
                eprintln!(
                    "Line {}: No active connection. Use CONNECT first.",
                    line_num + 1
                );
                Err(5)
            }
        }
    }

    for (line_num, raw_line) in content.lines().enumerate() {
        if cancelled.load(Ordering::Relaxed) {
            eprintln!("Batch interrupted at line {}", line_num + 1);
            return 4;
        }

        let line = raw_line.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }

        // Single-pass variable substitution (prevents recursive expansion)
        // Uses char indices for proper UTF-8 handling
        let expanded = {
            let mut result = String::with_capacity(line.len());
            let chars: Vec<(usize, char)> = line.char_indices().collect();
            let mut ci = 0;
            while ci < chars.len() {
                let (byte_idx, ch) = chars[ci];
                if ch == '$' && ci + 1 < chars.len() {
                    let (_, next_ch) = chars[ci + 1];
                    if next_ch == '$' {
                        // $$ escape → literal $
                        result.push('$');
                        ci += 2;
                        continue;
                    } else if next_ch == '{' {
                        // ${VAR} syntax
                        let start_byte = chars[ci + 2..]
                            .first()
                            .map(|(b, _)| *b)
                            .unwrap_or(line.len());
                        if let Some(close_pos) = line[start_byte..].find('}') {
                            let key = &line[start_byte..start_byte + close_pos];
                            if let Some(val) = variables.get(key) {
                                result.push_str(val);
                            } else {
                                let end_byte = start_byte + close_pos + 1;
                                result.push_str(&line[byte_idx..end_byte]);
                            }
                            // Skip past the closing }
                            let end_byte = start_byte + close_pos + 1;
                            ci = chars
                                .iter()
                                .position(|(b, _)| *b >= end_byte)
                                .unwrap_or(chars.len());
                            continue;
                        }
                    } else if next_ch.is_ascii_alphabetic() || next_ch == '_' {
                        // $VAR syntax
                        let start = ci + 1;
                        let mut end = start;
                        while end < chars.len()
                            && (chars[end].1.is_ascii_alphanumeric() || chars[end].1 == '_')
                        {
                            end += 1;
                        }
                        let key_start = chars[start].0;
                        let key_end = if end < chars.len() {
                            chars[end].0
                        } else {
                            line.len()
                        };
                        let key = &line[key_start..key_end];
                        if let Some(val) = variables.get(key) {
                            result.push_str(val);
                        } else {
                            result.push_str(&line[byte_idx..key_end]);
                        }
                        ci = end;
                        continue;
                    }
                }
                result.push(ch);
                ci += 1;
            }
            result
        };

        // Shell-like splitting that respects double quotes for paths with spaces
        let parts_owned: Vec<String> = {
            let mut parts = Vec::new();
            let mut current = String::new();
            let mut in_quotes = false;
            for ch in expanded.chars() {
                match ch {
                    '"' => in_quotes = !in_quotes,
                    ' ' | '\t' if !in_quotes => {
                        if !current.is_empty() {
                            parts.push(std::mem::take(&mut current));
                        }
                    }
                    _ => current.push(ch),
                }
            }
            if in_quotes {
                eprintln!("Warning: line {}: unmatched quote", line_num + 1);
            }
            if !current.is_empty() {
                parts.push(current);
            }
            parts
        };
        if parts_owned.is_empty() {
            continue;
        }
        let parts: Vec<&str> = parts_owned.iter().map(|s| s.as_str()).collect();

        let cmd = parts[0].to_uppercase();
        total_commands += 1;

        match cmd.as_str() {
            "SET" => {
                if expanded.len() > 3 {
                    let rest = expanded[3..].trim();
                    if let Some(eq_pos) = rest.find('=') {
                        let key = rest[..eq_pos].trim().to_string();
                        let value = rest[eq_pos + 1..].trim().to_string();
                        // Limit variable value size to 64 KB
                        if value.len() > 65_536 {
                            eprintln!(
                                "Line {}: variable value too large (max 64 KB)",
                                line_num + 1
                            );
                            return 5;
                        }
                        // Validate variable name: [A-Za-z_][A-Za-z0-9_]*
                        if !key.is_empty()
                            && key
                                .chars()
                                .next()
                                .is_some_and(|c| c.is_ascii_alphabetic() || c == '_')
                            && key.chars().all(|c| c.is_ascii_alphanumeric() || c == '_')
                        {
                            if variables.len() >= 256 && !variables.contains_key(&key) {
                                eprintln!("Line {}: too many variables (max 256)", line_num + 1);
                                return 5;
                            }
                            variables.insert(key, value);
                        } else {
                            eprintln!("Line {}: invalid variable name '{}' (must match [A-Za-z_][A-Za-z0-9_]*)", line_num + 1, key);
                            return 5;
                        }
                    } else {
                        eprintln!("Line {}: SET requires KEY=VALUE syntax", line_num + 1);
                        return 5;
                    }
                } else {
                    eprintln!("Line {}: SET requires KEY=VALUE syntax", line_num + 1);
                    return 5;
                }
            }
            "ECHO" => {
                // ECHO <message> - print to stderr for logging
                let msg = if expanded.len() > 4 {
                    expanded[4..].trim()
                } else {
                    ""
                };
                eprintln!("{}", msg);
            }
            "ON_ERROR" => {
                // ON_ERROR CONTINUE | ON_ERROR FAIL
                if parts.len() >= 2 {
                    match parts[1].to_uppercase().as_str() {
                        "CONTINUE" => on_error_continue = true,
                        "FAIL" => on_error_continue = false,
                        other => {
                            eprintln!(
                                "Line {}: ON_ERROR expects CONTINUE or FAIL, got '{}'",
                                line_num + 1,
                                other
                            );
                            return 5;
                        }
                    }
                }
            }
            "CONNECT" => {
                if parts.len() < 2 {
                    eprintln!("Line {}: CONNECT requires a URL", line_num + 1);
                    return 5;
                }
                // Clear previous URL before attempting new connection
                // Prevents stale URL reuse if CONNECT fails with ON_ERROR CONTINUE
                current_url = None;
                // Reset profile info flag so each batch CONNECT prints its profile
                PROFILE_INFO_PRINTED.store(false, Ordering::Relaxed);
                exit_code = cmd_connect(parts[1], cli, format).await;
                if exit_code == 0 {
                    current_url = Some(parts[1].to_string());
                } else if let Some(code) = check_exit(
                    exit_code,
                    line_num,
                    "CONNECT",
                    on_error_continue,
                    &mut failed_commands,
                ) {
                    return code;
                }
            }
            "DISCONNECT" => {
                current_url = None;
            }
            "GET" => {
                let url = match require_url(&current_url, line_num) {
                    Ok(u) => u,
                    Err(code) => return code,
                };
                if parts.len() < 2 {
                    eprintln!("Line {}: GET requires a remote path", line_num + 1);
                    return 5;
                }
                let local = if parts.len() > 2 {
                    Some(parts[2])
                } else {
                    None
                };
                exit_code = cmd_get(
                    &url,
                    parts[1],
                    local,
                    false,
                    1,
                    false,
                    cli,
                    format,
                    cancelled.clone(),
                )
                .await;
                if let Some(code) = check_exit(
                    exit_code,
                    line_num,
                    "GET",
                    on_error_continue,
                    &mut failed_commands,
                ) {
                    return code;
                }
            }
            "PUT" => {
                let url = match require_url(&current_url, line_num) {
                    Ok(u) => u,
                    Err(code) => return code,
                };
                if parts.len() < 2 {
                    eprintln!("Line {}: PUT requires a local path", line_num + 1);
                    return 5;
                }
                let remote = if parts.len() > 2 {
                    Some(parts[2])
                } else {
                    None
                };
                exit_code = cmd_put(
                    &url,
                    parts[1],
                    remote,
                    false,
                    false,
                    false,
                    None,
                    cli,
                    format,
                    cancelled.clone(),
                )
                .await;
                if let Some(code) = check_exit(
                    exit_code,
                    line_num,
                    "PUT",
                    on_error_continue,
                    &mut failed_commands,
                ) {
                    return code;
                }
            }
            "RM" => {
                let url = match require_url(&current_url, line_num) {
                    Ok(u) => u,
                    Err(code) => return code,
                };
                if parts.len() < 2 {
                    eprintln!("Line {}: RM requires a path", line_num + 1);
                    return 5;
                }
                let recursive = parts.contains(&"-r") || parts.contains(&"-rf");
                exit_code = cmd_rm(&url, parts[1], recursive, true, false, cli, format).await;
                if let Some(code) = check_exit(
                    exit_code,
                    line_num,
                    "RM",
                    on_error_continue,
                    &mut failed_commands,
                ) {
                    return code;
                }
            }
            "MV" => {
                let url = match require_url(&current_url, line_num) {
                    Ok(u) => u,
                    Err(code) => return code,
                };
                if parts.len() < 3 {
                    eprintln!("Line {}: MV requires <from> <to>", line_num + 1);
                    return 5;
                }
                exit_code = cmd_mv(&url, parts[1], parts[2], cli, format).await;
                if let Some(code) = check_exit(
                    exit_code,
                    line_num,
                    "MV",
                    on_error_continue,
                    &mut failed_commands,
                ) {
                    return code;
                }
            }
            "LS" => {
                let url = match require_url(&current_url, line_num) {
                    Ok(u) => u,
                    Err(code) => return code,
                };
                let path = if parts.len() > 1 { parts[1] } else { "/" };
                let long = parts.contains(&"-l");
                exit_code = cmd_ls(
                    &url, path, long, "name", false, true, None, false, false, cli, format,
                )
                .await;
                if let Some(code) = check_exit(
                    exit_code,
                    line_num,
                    "LS",
                    on_error_continue,
                    &mut failed_commands,
                ) {
                    return code;
                }
            }
            "CAT" => {
                let url = match require_url(&current_url, line_num) {
                    Ok(u) => u,
                    Err(code) => return code,
                };
                if parts.len() < 2 {
                    eprintln!("Line {}: CAT requires a path", line_num + 1);
                    return 5;
                }
                exit_code = cmd_cat(&url, parts[1], cli, format).await;
                if let Some(code) = check_exit(
                    exit_code,
                    line_num,
                    "CAT",
                    on_error_continue,
                    &mut failed_commands,
                ) {
                    return code;
                }
            }
            "STAT" => {
                let url = match require_url(&current_url, line_num) {
                    Ok(u) => u,
                    Err(code) => return code,
                };
                if parts.len() < 2 {
                    eprintln!("Line {}: STAT requires a path", line_num + 1);
                    return 5;
                }
                exit_code = cmd_stat(&url, parts[1], cli, format).await;
                if let Some(code) = check_exit(
                    exit_code,
                    line_num,
                    "STAT",
                    on_error_continue,
                    &mut failed_commands,
                ) {
                    return code;
                }
            }
            "FIND" => {
                let url = match require_url(&current_url, line_num) {
                    Ok(u) => u,
                    Err(code) => return code,
                };
                if parts.len() < 3 {
                    eprintln!("Line {}: FIND requires <path> <pattern>", line_num + 1);
                    return 5;
                }
                exit_code =
                    cmd_find(&url, parts[1], parts[2], false, false, None, cli, format).await;
                if let Some(code) = check_exit(
                    exit_code,
                    line_num,
                    "FIND",
                    on_error_continue,
                    &mut failed_commands,
                ) {
                    return code;
                }
            }
            "DF" => {
                let url = match require_url(&current_url, line_num) {
                    Ok(u) => u,
                    Err(code) => return code,
                };
                exit_code = cmd_df(&url, false, false, cli, format).await;
                if let Some(code) = check_exit(
                    exit_code,
                    line_num,
                    "DF",
                    on_error_continue,
                    &mut failed_commands,
                ) {
                    return code;
                }
            }
            "MKDIR" => {
                let url = match require_url(&current_url, line_num) {
                    Ok(u) => u,
                    Err(code) => return code,
                };
                if parts.len() < 2 {
                    eprintln!("Line {}: MKDIR requires a path", line_num + 1);
                    return 5;
                }
                exit_code = cmd_mkdir(&url, parts[1], false, None, cli, format).await;
                if let Some(code) = check_exit(
                    exit_code,
                    line_num,
                    "MKDIR",
                    on_error_continue,
                    &mut failed_commands,
                ) {
                    return code;
                }
            }
            "TREE" => {
                let url = match require_url(&current_url, line_num) {
                    Ok(u) => u,
                    Err(code) => return code,
                };
                let path = if parts.len() > 1 { parts[1] } else { "/" };
                exit_code = cmd_tree(&url, path, 3, cli, format).await;
                if let Some(code) = check_exit(
                    exit_code,
                    line_num,
                    "TREE",
                    on_error_continue,
                    &mut failed_commands,
                ) {
                    return code;
                }
            }
            "SYNC" => {
                let url = match require_url(&current_url, line_num) {
                    Ok(u) => u,
                    Err(code) => return code,
                };
                if parts.len() < 3 {
                    eprintln!("Line {}: SYNC requires <local> <remote>", line_num + 1);
                    return 5;
                }
                exit_code = cmd_sync(
                    &url,
                    parts[1],
                    parts[2],
                    "both",
                    false,
                    false,
                    &[],
                    None,
                    0,
                    false,
                    None,
                    None,
                    "",
                    false,
                    None,
                    None,
                    None,
                    "newer",
                    false,
                    false,
                    cli,
                    format,
                    cancelled.clone(),
                    None,
                    false, // Z.1.2: batch script SYNC keeps classic path; users opt in via dedicated CLI invocation
                )
                .await
                .exit_code;
                if let Some(code) = check_exit(
                    exit_code,
                    line_num,
                    "SYNC",
                    on_error_continue,
                    &mut failed_commands,
                ) {
                    return code;
                }
            }
            "CONNECT_SOURCE_PROFILE" => {
                if parts.len() < 2 {
                    eprintln!(
                        "Line {}: CONNECT_SOURCE_PROFILE requires a profile name",
                        line_num + 1
                    );
                    return 5;
                }
                let profile_name = parts[1..].join(" ");
                PROFILE_INFO_PRINTED.store(false, Ordering::Relaxed);
                // Disconnect previous source if any
                if let Some((mut old, _)) = cross_source.take() {
                    let _ = old.disconnect().await;
                }
                match batch_connect_profile(&profile_name, cli, format).await {
                    Ok(provider) => {
                        eprintln!("Source profile '{}' connected", profile_name);
                        cross_source = Some((provider, profile_name));
                    }
                    Err(code) => {
                        if let Some(c) = check_exit(
                            code,
                            line_num,
                            "CONNECT_SOURCE_PROFILE",
                            on_error_continue,
                            &mut failed_commands,
                        ) {
                            return c;
                        }
                    }
                }
            }
            "CONNECT_DEST_PROFILE" => {
                if parts.len() < 2 {
                    eprintln!(
                        "Line {}: CONNECT_DEST_PROFILE requires a profile name",
                        line_num + 1
                    );
                    return 5;
                }
                let profile_name = parts[1..].join(" ");
                PROFILE_INFO_PRINTED.store(false, Ordering::Relaxed);
                if let Some((mut old, _)) = cross_dest.take() {
                    let _ = old.disconnect().await;
                }
                match batch_connect_profile(&profile_name, cli, format).await {
                    Ok(provider) => {
                        eprintln!("Dest profile '{}' connected", profile_name);
                        cross_dest = Some((provider, profile_name));
                    }
                    Err(code) => {
                        if let Some(c) = check_exit(
                            code,
                            line_num,
                            "CONNECT_DEST_PROFILE",
                            on_error_continue,
                            &mut failed_commands,
                        ) {
                            return c;
                        }
                    }
                }
            }
            "TRANSFER" => {
                use ftp_client_gui_lib::cross_profile_transfer::{
                    plan_transfer, CrossProfileTransferRequest,
                };

                let (src_provider, src_name) = match &mut cross_source {
                    Some((p, n)) => (p.as_mut(), n.clone()),
                    None => {
                        eprintln!(
                            "Line {}: No source profile. Use CONNECT_SOURCE_PROFILE first.",
                            line_num + 1
                        );
                        if !on_error_continue {
                            return 5;
                        }
                        failed_commands += 1;
                        continue;
                    }
                };
                let (dest_provider, dest_name) = match &mut cross_dest {
                    Some((p, n)) => (p.as_mut(), n.clone()),
                    None => {
                        eprintln!(
                            "Line {}: No dest profile. Use CONNECT_DEST_PROFILE first.",
                            line_num + 1
                        );
                        if !on_error_continue {
                            return 5;
                        }
                        failed_commands += 1;
                        continue;
                    }
                };

                if parts.len() < 3 {
                    eprintln!("Line {}: TRANSFER requires <source_path> <dest_path> [-r] [--skip-existing]", line_num + 1);
                    return 5;
                }
                let source_path = parts[1];
                let dest_path = parts[2];
                let recursive = parts.contains(&"-r") || parts.contains(&"--recursive");
                let skip_existing = parts.contains(&"--skip-existing");
                let dry_run = parts.contains(&"--dry-run");

                let request = CrossProfileTransferRequest {
                    source_profile: src_name.clone(),
                    dest_profile: dest_name.clone(),
                    source_path: source_path.to_string(),
                    dest_path: dest_path.to_string(),
                    recursive,
                    dry_run,
                    skip_existing,
                };

                exit_code = 0;
                match plan_transfer(src_provider, dest_provider, &request).await {
                    Ok(plan) => {
                        if plan.entries.is_empty() {
                            eprintln!("  Nothing to transfer.");
                        } else if dry_run {
                            eprintln!(
                                "  DRY RUN: {} file(s), {}",
                                plan.total_files,
                                format_size(plan.total_bytes)
                            );
                            for entry in &plan.entries {
                                eprintln!("    {} -> {}", entry.source_path, entry.dest_path);
                            }
                        } else {
                            let src_p = cross_source.as_mut().unwrap().0.as_mut();
                            let dst_p = cross_dest.as_mut().unwrap().0.as_mut();
                            let summary = execute_cross_profile_plan(
                                src_p,
                                dst_p,
                                &plan,
                                skip_existing,
                                cli,
                                cli.quiet,
                                cancelled.clone(),
                            )
                            .await;
                            eprintln!(
                                "  Transfer done: {} ok, {} skipped, {} failed",
                                summary.transferred_files,
                                summary.skipped_files,
                                summary.failed_files
                            );
                            if summary.failed_files > 0 {
                                exit_code = 4;
                            }
                        }
                        if let Some(code) = check_exit(
                            exit_code,
                            line_num,
                            "TRANSFER",
                            on_error_continue,
                            &mut failed_commands,
                        ) {
                            return code;
                        }
                    }
                    Err(e) => {
                        let code = provider_error_to_exit_code(&e);
                        eprintln!("  Planning failed: {}", e);
                        if let Some(c) = check_exit(
                            code,
                            line_num,
                            "TRANSFER",
                            on_error_continue,
                            &mut failed_commands,
                        ) {
                            return c;
                        }
                    }
                }
            }
            _ => {
                print_error(
                    format,
                    &format!("Line {}: Unknown command '{}'. Supported: SET, ECHO, ON_ERROR, CONNECT, DISCONNECT, GET, PUT, RM, MV, LS, CAT, STAT, FIND, DF, MKDIR, TREE, SYNC, CONNECT_SOURCE_PROFILE, CONNECT_DEST_PROFILE, TRANSFER", line_num + 1, cmd),
                    5,
                );
                if !on_error_continue {
                    return 5;
                }
                failed_commands += 1;
            }
        }
    }

    // Cleanup cross-profile providers
    if let Some((mut p, _)) = cross_source.take() {
        let _ = p.disconnect().await;
    }
    if let Some((mut p, _)) = cross_dest.take() {
        let _ = p.disconnect().await;
    }

    if failed_commands > 0 {
        eprintln!(
            "\nBatch completed: {}/{} commands succeeded, {} failed",
            total_commands - failed_commands,
            total_commands,
            failed_commands
        );
        4
    } else {
        exit_code
    }
}

