    #[test]
    fn test_decide_import_merge_reports_skipped_indices() {
        // The dry-run lists skipped profiles by name, so the decision must
        // expose WHICH imported entries were skipped, not just the count. A
        // same-id profile is skipped (never overwritten); a new id is added,
        // and flagged `similar` when it shares host:port:username.
        let current = vec![json!({
            "id": "a", "name": "Kept", "host": "h", "port": 22, "username": "u"
        })];
        let imported = vec![
            json!({"id": "a", "name": "Dup", "host": "h", "port": 22, "username": "u"}),
            json!({"id": "b", "name": "New", "host": "h", "port": 22, "username": "u"}),
            json!({"id": "c", "name": "Fresh", "host": "other", "port": 21, "username": "x"}),
        ];
        let d = decide_import_merge(&imported, &current);
        assert_eq!(d.add_indices, vec![1, 2]);
        assert_eq!(d.skipped_indices, vec![0]);
        assert_eq!(d.skipped, 1);
        // index 1 shares the account of the kept profile, index 2 does not.
        assert_eq!(d.similar, 1);
    }

    #[test]
    fn test_lsjson_ndjson_line_is_single_line_compact_json() {
        // The NDJSON path emits `serde_json::to_string(&entry)` per line, so a
        // record must serialise to exactly one line (no embedded newline) and
        // parse back to the same object. This pins the contract that a
        // line-based consumer can split on '\n'.
        let entry = LsjsonEntry {
            path: "dir/file.txt".to_string(),
            name: "file.txt".to_string(),
            size: 42,
            mime_type: Some("text/plain".to_string()),
            mod_time: Some("2026-07-10 12:00:00Z".to_string()),
            is_dir: false,
            hashes: None,
        };
        let line = serde_json::to_string(&entry).expect("serialize");
        assert!(!line.contains('\n'), "NDJSON record must be one line");
        let back: serde_json::Value = serde_json::from_str(&line).expect("parse");
        assert_eq!(back["Path"], "dir/file.txt");
        assert_eq!(back["Name"], "file.txt");
        assert_eq!(back["Size"], 42);
        assert_eq!(back["IsDir"], false);
    }

    /// One directory of a walk, as `build_rm_dry_run_plan` would have recorded it.
    fn walk_dir(
        path: &str,
        parent: Option<usize>,
        depth: usize,
        children_total: usize,
        children_removed: usize,
    ) -> RmWalkDir {
        RmWalkDir {
            path: path.to_string(),
            parent,
            depth,
            children_total,
            children_removed,
            listing_complete: true,
        }
    }

    fn dir_paths(entries: &[DryRunEntry]) -> Vec<&str> {
        entries.iter().map(|e| e.path.as_str()).collect()
    }

    #[test]
    fn unfiltered_plan_removes_every_directory_in_discovery_order() {
        let mut dirs = vec![
            walk_dir("/root", None, 0, 1, 0),
            walk_dir("/root/keep", Some(0), 1, 0, 0),
        ];
        let entries = plan_dir_entries(&mut dirs, false);
        assert_eq!(dir_paths(&entries), vec!["/root", "/root/keep"]);
        assert!(entries.iter().all(|e| e.is_dir));
    }

    #[test]
    fn filtered_plan_spares_a_directory_that_still_holds_unmatched_files() {
        // /root holds one matched file and one directory that keeps a file.
        let mut dirs = vec![
            walk_dir("/root", None, 0, 2, 1),
            walk_dir("/root/mixed", Some(0), 1, 2, 1),
        ];
        let entries = plan_dir_entries(&mut dirs, true);
        assert!(
            entries.is_empty(),
            "no directory may go: /root/mixed keeps a file, so /root keeps /root/mixed"
        );
    }

    #[test]
    fn filtered_plan_removes_emptied_directories_deepest_first() {
        // Everything under /root matched, so the emptied tree collapses upward.
        let mut dirs = vec![
            walk_dir("/root", None, 0, 1, 0),
            walk_dir("/root/a", Some(0), 1, 1, 0),
            walk_dir("/root/a/b", Some(1), 2, 3, 3),
        ];
        let entries = plan_dir_entries(&mut dirs, true);
        assert_eq!(dir_paths(&entries), vec!["/root/a/b", "/root/a", "/root"]);
    }

    #[test]
    fn filtered_plan_leaves_an_already_empty_directory_alone() {
        // Nothing in it matched because nothing was in it. `rm --include "*.snap"`
        // was not an invitation to prune empty directories.
        let mut dirs = vec![walk_dir("/root", None, 0, 0, 0)];
        assert!(plan_dir_entries(&mut dirs, true).is_empty());
    }

    #[test]
    fn filtered_plan_keeps_a_directory_whose_listing_was_truncated() {
        // The cap cut the listing short, so children_total is a lower bound and
        // "everything in it is going" cannot be trusted.
        let mut dirs = vec![walk_dir("/root", None, 0, 2, 2)];
        dirs[0].listing_complete = false;
        assert!(plan_dir_entries(&mut dirs, true).is_empty());
    }

