    #[test]
    fn test_update_check_due_after_24_hours() {
        let now = chrono::DateTime::parse_from_rfc3339("2026-04-03T11:00:00Z")
            .unwrap()
            .with_timezone(&chrono::Utc);
        let due_cache = CliUpdateCache {
            checked_at: Some("2026-04-02T10:59:59Z".to_string()),
            latest_version: Some("3.3.5".to_string()),
        };
        let fresh_cache = CliUpdateCache {
            checked_at: Some("2026-04-02T12:00:00Z".to_string()),
            latest_version: Some("3.3.5".to_string()),
        };

        assert!(update_check_due(&due_cache, now));
        assert!(!update_check_due(&fresh_cache, now));
    }

    #[test]
    fn test_update_check_due_on_invalid_timestamp() {
        let now = chrono::DateTime::parse_from_rfc3339("2026-04-03T11:00:00Z")
            .unwrap()
            .with_timezone(&chrono::Utc);
        let cache = CliUpdateCache {
            checked_at: Some("not-a-timestamp".to_string()),
            latest_version: None,
        };

        assert!(update_check_due(&cache, now));
    }

    // ── pget effective-segment-count tests ─────────────────────────
    //
    // The actual gap-free byte windows are planned and unit-tested in
    // `providers::multi_thread` (`plan_multi_thread_ranges`). The CLI only
    // derives the segment *count* (degenerate-fallback decision + display);
    // these assert the historical anti-fragmentation policy is preserved.

    #[test]
    fn test_pget_effective_segments_basic() {
        // 100 MB / 4 -> 25 MB chunks, well above PGET_MIN_CHUNK_SIZE.
        assert_eq!(pget_effective_segments(100 * 1024 * 1024, 4), 4);
    }

    #[test]
    fn test_pget_effective_segments_uneven_division() {
        // 10_000_003 / 4 ~= 2.5 MB chunks, above PGET_MIN_CHUNK_SIZE.
        assert_eq!(pget_effective_segments(10_000_003, 4), 4);
    }

    #[test]
    fn test_pget_effective_segments_reduces_for_small_files() {
        // 3 MB with 16 segments -> each chunk < PGET_MIN_CHUNK_SIZE (1 MB),
        // so the count collapses to floor(3 MB / 1 MB) = 3.
        assert_eq!(pget_effective_segments(3 * 1024 * 1024, 16), 3);
    }

    #[test]
    fn test_pget_effective_segments_single_segment() {
        assert_eq!(pget_effective_segments(500_000, 1), 1);
    }

    #[test]
    fn test_pget_effective_segments_zero_size() {
        assert_eq!(pget_effective_segments(0, 4), 0);
    }

    #[test]
    fn test_pget_effective_segments_clamps_segments() {
        // 100 > hard cap 16; 100 MB / 16 = 6.25 MB chunks, above the floor.
        assert_eq!(pget_effective_segments(100 * 1024 * 1024, 100), 16);
    }

    #[test]
    fn test_pget_effective_segments_tiny_file() {
        // Below PGET_MIN_CHUNK_SIZE -> never split, exactly 1 segment.
        assert_eq!(pget_effective_segments(500_000, 8), 1);
    }

    #[test]
    fn test_pget_effective_segments_zero_requested() {
        assert_eq!(pget_effective_segments(100 * 1024 * 1024, 0), 0);
    }

    // ── --max-transfer pre-flight cap (PD-UX-1) ──────────────────────

    #[test]
    fn test_cap_files_to_max_transfer() {
        // This test owns the process-global session counter (no other
        // test touches it), so it is deterministic under parallel runs.
        let files: Vec<(String, String, u64)> = vec![
            ("a".into(), "a".into(), 40),
            ("b".into(), "b".into(), 40),
            ("c".into(), "c".into(), 40),
        ];

        // No --max-transfer: every file kept, nothing skipped.
        SESSION_TRANSFERRED_BYTES.store(0, Ordering::Relaxed);
        let (kept, skipped) = cap_files_to_max_transfer(&files, &test_cli());
        assert_eq!(kept.len(), 3);
        assert_eq!(skipped, 0);

        // Limit 100 B, fresh session: a file is started while the running
        // total is still under the cap (it then transfers fully, the
        // single-overshoot rule). running 0->40 (a), 40->80 (b),
        // 80->120 (c): all three began under 100, so all three are kept.
        SESSION_TRANSFERRED_BYTES.store(0, Ordering::Relaxed);
        let cli = Cli {
            max_transfer: Some("100".to_string()),
            ..test_cli()
        };
        let (kept, skipped) = cap_files_to_max_transfer(&files, &cli);
        assert_eq!(kept.len(), 3);
        assert_eq!(skipped, 0);

        // Session already spent 90 B against a 100 B cap: a starts
        // (90 < 100) -> kept, running 130; b sees running >= 100 ->
        // skipped, and so is c. Honest single-overshoot.
        SESSION_TRANSFERRED_BYTES.store(90, Ordering::Relaxed);
        let (kept, skipped) = cap_files_to_max_transfer(&files, &cli);
        assert_eq!(kept.len(), 1);
        assert_eq!(skipped, 2);

        // Budget fully spent before the batch: every file skipped, never
        // a silent no-op (caller emits the honest note).
        SESSION_TRANSFERRED_BYTES.store(100, Ordering::Relaxed);
        let (kept, skipped) = cap_files_to_max_transfer(&files, &cli);
        assert!(kept.is_empty());
        assert_eq!(skipped, 3);

        // Empty input is a no-op regardless of the budget.
        SESSION_TRANSFERRED_BYTES.store(0, Ordering::Relaxed);
        let (kept, skipped) = cap_files_to_max_transfer(&[], &cli);
        assert!(kept.is_empty());
        assert_eq!(skipped, 0);

        // Restore the global for any later-scheduled reader.
        SESSION_TRANSFERRED_BYTES.store(0, Ordering::Relaxed);
    }

